--
-- Name: apps_public_auth_ip_allowlist_cidr_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_public_auth_ip_allowlist_cidr_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  bad cidr;
begin
  if new.public_auth_ip_allowlist is null or cardinality(new.public_auth_ip_allowlist) = 0 then
    return new;
  end if;
  -- Per-entry guards: family must be v4 or v6, mask must be non-zero.
  -- The /0 reject closes the same hole as the egress allowlist's
  -- chain-policy accept: an operator cannot pin "the entire
  -- address space" — that is the default-pass posture's job, not
  -- the allowlist's. Two narrow selects (one per guard) keep the
  -- error messages specific; a combined select with bool_or would
  -- conflate family and masklen failures.
  for bad in
    select c
      from unnest(new.public_auth_ip_allowlist) c
     where family(c) not in (4, 6)
     limit 1
  loop
    raise exception 'apps_public_auth_ip_allowlist: only v4 or v6 CIDRs (got family % for %)', family(bad), bad
      using errcode = '23514',
            constraint = 'apps_public_auth_ip_allowlist_cidr';
  end loop;
  for bad in
    select c
      from unnest(new.public_auth_ip_allowlist) c
     where masklen(c) = 0
     limit 1
  loop
    raise exception 'apps_public_auth_ip_allowlist: rejected % (masklen /0; ADR-118 non-/0 contract)', bad
      using errcode = '23514',
            constraint = 'apps_public_auth_ip_allowlist_cidr';
  end loop;
  return new;
end;
$$;


--
-- Name: apps_record_control_plane_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_record_control_plane_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Scale-in/out bookkeeping changes often and is not gateway policy.
    -- Avoid serializing those writes behind the global replay-order lock or
    -- claiming that a gateway has a new policy revision to apply.
    IF TG_OP = 'UPDATE' THEN
        IF (to_jsonb(NEW) - ARRAY['last_scale_out_at', 'last_scale_in_at']) =
           (to_jsonb(OLD) - ARRAY['last_scale_out_at', 'last_scale_in_at']) THEN
            RETURN NEW;
        END IF;
    END IF;
    PERFORM pg_advisory_xact_lock(711901248671::bigint);
    IF TG_OP = 'INSERT' THEN
        INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
        VALUES ('app', NEW.id, NEW.id, 'created');
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
        VALUES ('app', NEW.id, NEW.id, 'updated');
        RETURN NEW;
    ELSE
        INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
        VALUES ('app', OLD.id, OLD.id, 'deleted');
        RETURN OLD;
    END IF;
END;
$$;


--
-- Name: apps_streaming_plan_account_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_streaming_plan_account_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.plan = 'free'
       AND OLD.plan IS DISTINCT FROM NEW.plan
       AND EXISTS (
           SELECT 1
             FROM apps
            WHERE account_id = NEW.id
              AND streaming_enabled
       ) THEN
        RAISE EXCEPTION
            'account % cannot downgrade to Free while a streaming-enabled app exists',
            NEW.id
            USING ERRCODE = '23514',
                  CONSTRAINT = 'apps_streaming_enabled_plan_check';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: apps_streaming_plan_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apps_streaming_plan_allowed(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM accounts
         WHERE id = p_account_id
           AND plan <> 'free'
    );
$$;


