--
-- Name: enforce_app_task_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_app_task_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('succeeded', 'failed', 'timed_out', 'cancelled') THEN
        IF OLD.status IN ('failed', 'timed_out')
           AND NEW.status = 'queued'
           AND OLD.kind = 'cron'
           AND OLD.retry_max > 0
           AND OLD.attempt_count BETWEEN 1 AND OLD.retry_max
           AND NEW.attempt_count = OLD.attempt_count
           AND NEW.retry_max = OLD.retry_max
           AND NEW.cron_id IS NOT DISTINCT FROM OLD.cron_id
           AND NEW.scheduled_for IS NOT DISTINCT FROM OLD.scheduled_for
           AND NEW.retry_at > NEW.updated_at
           AND NEW.updated_at >= OLD.updated_at
           AND NEW.started_at IS NULL
           AND NEW.finished_at IS NULL
           AND NEW.lease_token IS NULL
           AND NEW.lease_owner IS NULL
           AND NEW.lease_expires_at IS NULL
           AND NEW.cancel_requested_at IS NULL THEN
            -- Retry is a lifecycle-only rewrite: all payload, ownership,
            -- command, and prior failure evidence must remain unchanged.
            -- Subtract only fields that are expected to change so any new
            -- app_tasks column remains immutable by default.
            IF (to_jsonb(NEW) - ARRAY['status', 'retry_at', 'started_at', 'finished_at', 'updated_at',
                                      'lease_token', 'lease_owner', 'lease_expires_at']) =
               (to_jsonb(OLD) - ARRAY['status', 'retry_at', 'started_at', 'finished_at', 'updated_at',
                                      'lease_token', 'lease_owner', 'lease_expires_at']) THEN
                RETURN NEW;
            END IF;
        END IF;
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'terminal app task % is immutable', OLD.id USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.status = 'queued' AND NEW.status IN ('restoring', 'cancelled'))
        OR
        (OLD.status = 'restoring' AND NEW.status IN ('queued', 'running', 'failed',
                                                     'timed_out', 'cancelled'))
        OR
        (OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed',
                                                   'timed_out', 'cancelled'))
    ) THEN
        RAISE EXCEPTION 'invalid app task % transition from % to %',
            OLD.id, OLD.status, NEW.status USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: enforce_binding_release_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_binding_release_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app uuid;
BEGIN
 IF (TG_OP='UPDATE' AND NEW.active=OLD.active) OR (TG_OP='INSERT' AND NOT NEW.active) THEN RETURN NEW; END IF;
 FOR app IN SELECT id FROM apps WHERE project_id=NEW.project_id AND status<>'deleted' ORDER BY id LOOP
  PERFORM 1 FROM app_binding_promotion_revisions WHERE app_id=app FOR UPDATE;
  IF EXISTS(SELECT 1 FROM app_binding_release_policies WHERE app_id=app AND scope=NEW.environment_slug AND mode='enforce') THEN
   RAISE EXCEPTION 'project release switching requires a binding release gate' USING ERRCODE='23514',CONSTRAINT='binding_release_required';
  END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: enforce_binding_release_traffic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_binding_release_traffic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE prior_percent integer:=0; p app_binding_release_policies%ROWTYPE; f jsonb; granted boolean:=false;
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='live' AND OLD.app_id=NEW.app_id AND OLD.scope=NEW.scope THEN prior_percent:=OLD.traffic_percent; END IF;
 -- Admission with positive intended traffic is also gated, so unguarded
 -- automatic activation cannot fail only after a build has run.
 IF NEW.traffic_percent<=prior_percent OR NEW.traffic_percent=0 OR (TG_OP='UPDATE' AND NEW.status<>'live') THEN RETURN NEW; END IF;
 -- Even a missing policy must serialize with concurrent enabling.
 PERFORM 1 FROM app_binding_promotion_revisions WHERE app_id=NEW.app_id FOR UPDATE;
 SELECT * INTO p FROM app_binding_release_policies WHERE app_id=NEW.app_id AND scope=NEW.scope;
 IF p.mode IS DISTINCT FROM 'enforce' THEN RETURN NEW; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(NULLIF(current_setting('gregale.binding_release_fences',true),''),'[]')::jsonb) LOOP
  IF f->>'deployment_id'=NEW.id::text AND f->>'app_id'=NEW.app_id::text AND f->>'scope'=NEW.scope
    AND (f->>'policy_revision')::bigint=p.revision
    AND (NULLIF(f->>'valid_until','') IS NULL OR (f->>'valid_until')::timestamptz>clock_timestamp()) THEN granted:=true; EXIT; END IF;
 END LOOP;
 IF NOT granted THEN
  RAISE EXCEPTION 'binding release requires fresh checked evidence' USING ERRCODE='23514',CONSTRAINT='binding_release_required';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: enforce_cancelled_deployment_release_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_cancelled_deployment_release_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    terminal_at timestamptz;
    cancel_detail text;
    stage_started_at timestamptz;
    duration_ms bigint;
BEGIN
    IF NEW.status = 'cancelled' THEN
        terminal_at := COALESCE(NEW.cancelled_at, now());
        cancel_detail := 'deployment cancelled: ' || COALESCE(NULLIF(NEW.cancel_reason, ''), 'system');
        NEW.cancelled_at := terminal_at;
        NEW.traffic_percent := 0;
        NEW.rollout_state := 'aborted';
        NEW.rollout_completed_at := NULL;
        NEW.rollout_aborted_at := COALESCE(NEW.rollout_aborted_at, terminal_at);
        NEW.rollout_aborted_reason := COALESCE(NULLIF(NEW.rollout_aborted_reason, ''), cancel_detail);

        IF COALESCE(NEW.stage_state->>'current', '') <> '' THEN
            stage_started_at := COALESCE(
				NULLIF(NEW.stage_state->>'current_started_at', '')::timestamptz,
                NEW.created_at,
                terminal_at
            );
            duration_ms := GREATEST(0, floor(extract(epoch FROM (terminal_at - stage_started_at)) * 1000)::bigint);
            NEW.stage_state := jsonb_set(
                jsonb_set(
                    jsonb_set(
                        NEW.stage_state,
                        '{history}',
                        COALESCE(NEW.stage_state->'history', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
                            'name', NEW.stage_state->>'current',
                            'started_at', to_jsonb(stage_started_at),
                            'ended_at', to_jsonb(terminal_at),
                            'duration_ms', duration_ms,
                            'status', 'cancelled',
                            'reason', cancel_detail
                        )),
                        true
                    ),
                    '{current}', '""'::jsonb, true
                ),
                '{current_started_at}', 'null'::jsonb, true
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_event_delivery_age_ordering(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_event_delivery_age_ordering() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p jsonb;
BEGIN
 IF TG_TABLE_NAME='event_subscriptions' THEN
  IF coalesce((NEW.routing_retry_policy->>'max_delivery_age_ms')::bigint,0)>0
   AND EXISTS(SELECT 1 FROM event_subscription_work_bindings b WHERE b.subscription_id=NEW.id AND b.ordered) THEN
   RAISE EXCEPTION 'ordered event delivery cannot configure max_delivery_age' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.ordered THEN
  SELECT routing_retry_policy INTO p FROM event_subscriptions WHERE id=NEW.subscription_id FOR UPDATE;
  IF coalesce((p->>'max_delivery_age_ms')::bigint,0)>0 THEN
   RAISE EXCEPTION 'ordered event delivery cannot configure max_delivery_age' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: enforce_execution_profile_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_execution_profile_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.profile IS DISTINCT FROM OLD.profile THEN
  RAISE EXCEPTION 'execution profile is immutable' USING ERRCODE = '23514';
 END IF;
 IF TG_TABLE_NAME = 'executions' THEN
  IF NEW.runtime_image_digest IS DISTINCT FROM OLD.runtime_image_digest AND
     (OLD.status <> 'restoring' OR OLD.runtime_image_digest IS NOT NULL) THEN
   RAISE EXCEPTION 'execution image digest is immutable after selection' USING ERRCODE = '23514';
  END IF;
 END IF;
 RETURN NEW;
END
$$;


--
-- Name: enforce_execution_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_execution_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('succeeded', 'failed', 'timed_out', 'out_of_memory', 'cancelled') THEN
        RAISE EXCEPTION 'terminal execution % is immutable', OLD.id USING ERRCODE = '23514';
    END IF;

    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.status = 'queued' AND NEW.status IN ('restoring', 'timed_out', 'cancelled'))
        OR
        (OLD.status = 'restoring' AND NEW.status IN ('queued', 'running', 'failed',
                                                     'timed_out', 'out_of_memory', 'cancelled'))
        OR
        (OLD.status = 'running' AND NEW.status IN ('succeeded', 'failed',
                                                   'timed_out', 'out_of_memory', 'cancelled'))
    ) THEN
        RAISE EXCEPTION 'invalid execution % transition from % to %',
            OLD.id, OLD.status, NEW.status USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: enforce_failed_deployment_stage_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_failed_deployment_stage_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    terminal_at timestamptz;
    stage_started_at timestamptz;
    duration_ms bigint;
    failure_detail text;
BEGIN
    IF NEW.status = 'failed' AND COALESCE(NEW.stage_state->>'current', '') <> '' THEN
        terminal_at := COALESCE(NEW.rollout_aborted_at, now());
        stage_started_at := COALESCE(
            NULLIF(NEW.stage_state->>'current_started_at', '')::timestamptz,
            NEW.created_at,
            terminal_at
        );
        duration_ms := GREATEST(
            0,
            floor(extract(epoch FROM (GREATEST(stage_started_at, terminal_at) - stage_started_at)) * 1000)::bigint
        );
        failure_detail := COALESCE(
            NULLIF(NEW.error_code, ''),
            NULLIF(NEW.error, ''),
            'deployment failed'
        );
        NEW.stage_state := jsonb_set(
            jsonb_set(
                jsonb_set(
                    NEW.stage_state,
                    '{history}',
                    jsonb_path_query_array(
                        COALESCE(NEW.stage_state->'history', '[]'::jsonb),
                        '$[last - 62 to last]'
                    ) || jsonb_build_array(jsonb_build_object(
                        'name', NEW.stage_state->>'current',
                        'started_at', to_jsonb(stage_started_at),
                        'ended_at', to_jsonb(GREATEST(stage_started_at, terminal_at)),
                        'duration_ms', duration_ms,
                        'status', 'failed',
                        'reason', failure_detail
                    )),
                    true
                ),
                '{current}', '""'::jsonb, true
            ),
            '{current_started_at}', 'null'::jsonb, true
        );
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: enforce_failed_deployment_traffic_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_failed_deployment_traffic_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'failed' THEN
        NEW.traffic_percent := 0;
        NEW.rollout_state := 'aborted';
        NEW.rollout_completed_at := NULL;
        NEW.rollout_aborted_at := COALESCE(NEW.rollout_aborted_at, now());
        NEW.rollout_aborted_reason := COALESCE(NULLIF(NEW.rollout_aborted_reason, ''), NULLIF(NEW.error, ''), 'deployment failed');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_runtime_upgrade_pin_traffic_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_runtime_upgrade_pin_traffic_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE candidate deployments;
BEGIN
 SELECT * INTO candidate FROM deployments WHERE id=NEW.deployment_id FOR SHARE;
 IF candidate.status='live' AND candidate.traffic_percent>0 THEN
  RAISE EXCEPTION 'serving deployment cannot acquire runtime upgrade preparation'
   USING ERRCODE='23514',CONSTRAINT='runtime_upgrade_traffic_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: enforce_runtime_upgrade_traffic_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_runtime_upgrade_traffic_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.status='live' AND NEW.traffic_percent>0
  AND EXISTS(SELECT 1 FROM deployment_runtime_upgrade_targets WHERE deployment_id=NEW.id)
  AND NOT EXISTS (
   SELECT 1 FROM deployment_runtime_upgrade_cutovers c
   JOIN deployment_runtime_upgrade_acceptances a ON a.deployment_id=c.deployment_id
   JOIN deployment_runtime_upgrade_targets t ON t.deployment_id=c.deployment_id
   WHERE c.deployment_id=NEW.id AND c.target_release_id=t.release_id AND c.target_release_id=a.target_release_id
    AND c.wake_id=a.wake_id AND c.qualification_report_sha256=a.qualification_report_sha256 AND a.rootfs_key=NEW.rootfs_key
  ) THEN
  RAISE EXCEPTION 'runtime upgrade requires atomic qualified cutover' USING ERRCODE='23514',CONSTRAINT='runtime_upgrade_traffic_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: enqueue_automatic_route_check(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_automatic_route_check(p_app uuid, p_deployment uuid DEFAULT NULL::uuid, p_force boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO automatic_route_checks (deployment_id, app_id, account_id)
    SELECT d.id, a.id, a.account_id FROM deployments d
    JOIN apps a ON a.id = d.app_id
    JOIN saved_route_requirements s ON s.app_id = a.id AND s.account_id = a.account_id
    WHERE a.id = p_app AND a.status <> 'deleted'
      AND (p_deployment IS NULL OR d.id = p_deployment)
      AND (p_deployment IS NOT NULL OR EXISTS (SELECT 1 FROM deployment_openapi_docs c WHERE c.deployment_id = d.id AND c.app_id = a.id AND c.account_id = a.account_id) OR EXISTS (SELECT 1 FROM automatic_route_checks j WHERE j.deployment_id = d.id))
    ORDER BY d.id
    ON CONFLICT (deployment_id) DO UPDATE SET
        request_id = gen_random_uuid(), queued_at = now(), next_attempt_at = now(),
        attempts = 0, last_error_code = '', lease_token = NULL, lease_until = NULL, claimed_request_id = NULL
    WHERE p_force OR automatic_route_checks.completed_request_id = automatic_route_checks.request_id OR automatic_route_checks.last_error_code <> '';
END;
$$;


--
-- Name: enqueue_debug_regression_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_debug_regression_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    event_payload jsonb;
    transition_id timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'active' THEN
            RETURN NEW;
        END IF;
        event_name := 'debug.regression.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'active' AND OLD.state <> 'active' THEN
        event_name := 'debug.regression.detected';
        transition_id := NEW.first_detected_at;
    ELSIF NEW.state = 'resolved' AND OLD.state <> 'resolved' THEN
        event_name := 'debug.regression.resolved';
        transition_id := NEW.resolved_at;
    ELSE
        RETURN NEW;
    END IF;

    event_payload := jsonb_build_object(
        'app_id', NEW.app_id,
        'deployment_id', NEW.deployment_id,
        'route', NEW.route,
        'p95_ms', NEW.p95_ms,
        'p95_base_ms', NEW.p95_base_ms,
        'affected_count', NEW.affected_count,
        'regression_factor', NEW.regression_factor,
        'first_detected_at', NEW.first_detected_at,
        'last_detected_at', NEW.last_detected_at,
        'state', NEW.state,
        'transition_id', transition_id,
        'resolved_at', NEW.resolved_at
    );

    INSERT INTO app_webhook_deliveries
        (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, event_payload
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.scope = 'app'
       AND h.app_id = NEW.app_id
       AND h.enabled
       AND (cardinality(h.event_filter) = 0 OR event_name = ANY(h.event_filter))
    ON CONFLICT DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: enqueue_deployment_lifecycle_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_deployment_lifecycle_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    event_payload jsonb;
BEGIN
    IF NEW.status = OLD.status OR NEW.status NOT IN ('live', 'failed') THEN
        RETURN NEW;
    END IF;

    event_name := 'deployment.' || NEW.status;
    event_payload := jsonb_build_object(
        'app_id', NEW.app_id,
        'deployment_id', NEW.id,
        'status', NEW.status
    );
    IF NEW.status = 'failed' THEN
        event_payload := event_payload || jsonb_strip_nulls(jsonb_build_object(
            'error_code', NEW.error_code,
            'error_hint', NEW.error_hint,
            'error_why', NEW.error_why,
            'error_fix', NEW.error_fix
        ));
    END IF;

    INSERT INTO app_webhook_deliveries
        (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, event_payload
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.enabled
       AND ((h.scope = 'app' AND h.app_id = NEW.app_id)
            OR (h.scope = 'account' AND h.app_id IS NULL))
       AND (event_name = ANY(h.event_filter)
            OR (h.scope = 'app' AND cardinality(h.event_filter) = 0));
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_environment_git_source_poll(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_environment_git_source_poll() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO environment_git_source_polls(source_id) VALUES (NEW.id);
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_event_fanout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_event_fanout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE existing_type text;
DECLARE existing_data jsonb;
DECLARE existing_schema_version text;
DECLARE recipients jsonb;
DECLARE target_app uuid;
DECLARE target_tenant uuid;
BEGIN
    IF NEW.kind <> 'event.published' THEN
        RETURN NEW;
    END IF;
    IF NEW.subject IS NULL OR NEW.data->>'source' IS NULL OR
       NEW.data->>'id' IS NULL OR NEW.data->>'type' IS NULL OR
       NEW.data->'data' IS NULL THEN
        RAISE EXCEPTION 'event.published requires account, source, id, type and data'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.data ? 'platformtenantid' THEN
        BEGIN
            target_app := (NEW.data->>'appid')::uuid;
            target_tenant := (NEW.data->>'platformtenantid')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'tenant event identity must be UUIDs' USING ERRCODE = '23514';
        END;
        recipients := coalesce((SELECT jsonb_agg(recipient ORDER BY recipient->>'id')
            FROM workflow_tenant_event_recipients(NEW.subject, target_app, target_tenant,
                NEW.data->>'source', NEW.data->>'type')), '[]'::jsonb);
    ELSE
        SELECT coalesce(jsonb_agg(jsonb_build_object(
            'id', s.id, 'account_id', s.account_id, 'app_id', s.app_id,
            'source', s.source, 'type', s.type, 'filter', s.filter,
            'routing_retry_policy', s.routing_retry_policy,
            'schema_versions', s.schema_versions,
            'work_snapshot_captured', true,
            'work', CASE WHEN b.subscription_id IS NULL THEN NULL
                ELSE jsonb_build_object(
                    'policy_name', b.policy_name, 'key_selector', b.key_selector,
                    'fairness_selector', b.fairness_key_selector, 'action', b.action,
                    'ordered', b.ordered,
                    'policy', CASE WHEN p.name IS NULL THEN NULL
                        ELSE jsonb_build_object(
                            'revision', p.revision,
                            'max_running_per_key', p.max_running_per_key,
                            'max_running_per_fairness_key', p.max_running_per_fairness_key,
                            'pending_updates', p.pending_updates,
                            'debounce_ms', p.debounce_ms,
                            'expires_after_ms', p.expires_after_ms) END)
                END)
            ORDER BY s.created_at, s.id), '[]'::jsonb)
        INTO recipients
        FROM event_subscriptions s
        JOIN apps a ON a.id = s.app_id AND a.account_id = s.account_id
        LEFT JOIN event_subscription_work_bindings b
          ON b.subscription_id = s.id AND b.app_id = s.app_id
        LEFT JOIN app_work_policies p
          ON p.app_id = b.app_id AND p.name = b.policy_name
        WHERE s.account_id = NEW.subject AND s.enabled AND a.status <> 'deleted'
          AND event_fanout_pattern_matches(s.source, NEW.data->>'source')
          AND event_fanout_pattern_matches(s.type, NEW.data->>'type');

        recipients := recipients || coalesce((SELECT jsonb_agg(recipient ORDER BY recipient->>'id')
            FROM workflow_event_recipients(NEW.subject, NEW.data->>'source', NEW.data->>'type')), '[]'::jsonb);
    END IF;

    INSERT INTO event_fanout_outbox
        (account_id, source, event_id, event_type, schema_version, event_data, payload, recipient_snapshot)
    VALUES (NEW.subject, NEW.data->>'source', NEW.data->>'id',
            NEW.data->>'type', NEW.data->>'schemaversion', NEW.data->'data', NEW.data, recipients)
    ON CONFLICT (account_id, source, event_id) DO NOTHING;
    IF NOT FOUND THEN
        SELECT event_type, schema_version, event_data INTO existing_type, existing_schema_version, existing_data
        FROM event_fanout_outbox WHERE account_id = NEW.subject
          AND source = NEW.data->>'source' AND event_id = NEW.data->>'id';
        IF existing_type IS DISTINCT FROM NEW.data->>'type' OR
           existing_schema_version IS DISTINCT FROM NEW.data->>'schemaversion' OR
           existing_data IS DISTINCT FROM NEW.data->'data' THEN
            RAISE EXCEPTION 'event identity already has different content'
                USING ERRCODE = '23505', CONSTRAINT = 'event_fanout_identity_uniq';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_customer_lifecycle_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_customer_lifecycle_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_name text;
  tenant_external_ref text;
  event_payload jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.platform_tenant_id IS NULL OR NEW.status <> 'active' THEN
      RETURN NEW;
    END IF;
    event_name := 'platform_tenant.customer.linked';
  ELSIF OLD.platform_tenant_id IS NULL AND NEW.platform_tenant_id IS NOT NULL
        AND OLD.status = 'active' AND NEW.status = 'active' THEN
    event_name := 'platform_tenant.customer.linked';
  ELSIF OLD.platform_tenant_id = NEW.platform_tenant_id
        AND OLD.platform_tenant_id IS NOT NULL
        AND OLD.status = 'active' AND NEW.status = 'revoked' THEN
    event_name := 'platform_tenant.customer.offboarded';
  ELSE
    RETURN NEW;
  END IF;

  SELECT external_ref INTO tenant_external_ref
    FROM platform_tenants
   WHERE account_id = NEW.account_id AND id = NEW.platform_tenant_id;
  IF tenant_external_ref IS NULL THEN
    RETURN NEW;
  END IF;

  event_payload := jsonb_build_object(
    'platform_tenant_id', NEW.platform_tenant_id,
    'external_ref', tenant_external_ref,
    'consumer_id', NEW.id,
    'app_id', NEW.app_id,
    'customer_external_ref', NEW.external_ref,
    'customer_name', NEW.name,
    'customer_status', NEW.status,
    'changed_at', statement_timestamp()
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, event_name, event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = NEW.platform_tenant_id
     AND h.account_id = NEW.account_id
     AND h.enabled
     AND event_name = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_hostname_verified_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_hostname_verified_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_payload jsonb;
  v_tenant_id uuid;
  v_tenant_external_ref text;
  v_surface_name text;
  v_app_id uuid;
  v_account_id uuid;
BEGIN
  IF OLD.verified_at IS NOT NULL OR NEW.verified_at IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT s.platform_tenant_id, t.external_ref, s.name::text, s.app_id, s.account_id
    INTO v_tenant_id, v_tenant_external_ref, v_surface_name, v_app_id, v_account_id
    FROM tenant_surfaces s
    LEFT JOIN platform_tenants t
      ON t.account_id = s.account_id AND t.id = s.platform_tenant_id
   WHERE s.id = NEW.surface_id;

  -- Unlinked surfaces stay on their existing app-scoped integration path.
  IF v_tenant_id IS NULL OR v_tenant_external_ref IS NULL THEN
    RETURN NEW;
  END IF;

  event_payload := jsonb_build_object(
    'platform_tenant_id', v_tenant_id,
    'external_ref', v_tenant_external_ref,
    'surface_id', NEW.surface_id,
    'surface_name', v_surface_name,
    'app_id', v_app_id,
    'hostname_id', NEW.id,
    'hostname', NEW.hostname,
    'verified_at', NEW.verified_at
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.hostname.verified', event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = v_tenant_id
     AND h.account_id = v_account_id
     AND h.enabled
     AND 'platform_tenant.hostname.verified' = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_reconciliation_applied_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_reconciliation_applied_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.reconciliation.applied',
         jsonb_build_object(
           'platform_tenant_id', t.id,
           'external_ref', t.external_ref,
           'receipt_id', NEW.receipt_id,
           'plan_hash', NEW.plan_hash,
           'applied_at', NEW.applied_at,
           'change_count', jsonb_array_length(NEW.changes)
         )
    FROM platform_tenants t
    JOIN app_webhooks h
      ON h.account_id = t.account_id
     AND h.platform_tenant_id = t.id
     AND h.scope = 'platform_tenant'
     AND h.enabled
     AND 'platform_tenant.reconciliation.applied' = ANY(h.event_filter)
   WHERE t.account_id = NEW.account_id
     AND t.id = NEW.tenant_id
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_statement_finalized_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_statement_finalized_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_payload jsonb;
  tenant_external_ref text;
BEGIN
  IF OLD.status = 'finalized' OR NEW.status <> 'finalized' THEN
    RETURN NEW;
  END IF;

  SELECT external_ref INTO tenant_external_ref
    FROM platform_tenants
   WHERE account_id = NEW.account_id AND id = NEW.platform_tenant_id;

  event_payload := jsonb_build_object(
    'platform_tenant_id', NEW.platform_tenant_id,
    'external_ref', tenant_external_ref,
    'statement_id', NEW.id,
    'revision', NEW.revision,
    'status', NEW.status,
    'period_start', NEW.period_start,
    'period_end', NEW.period_end,
    'currency', NEW.currency,
    'billable_units', NEW.billable_units,
    'unpriced_units', NEW.unpriced_units,
    'amount_millicents', NEW.amount_millicents,
    'priced', NEW.unpriced_units = 0 AND NEW.currency <> '',
    'lines', NEW.lines,
    'as_of', NEW.as_of,
    'finalized_at', NEW.finalized_at
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, NEW.account_id, 'platform_tenant.statement.finalized', event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = NEW.platform_tenant_id
     AND h.account_id = NEW.account_id
     AND h.enabled
     AND 'platform_tenant.statement.finalized' = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_surface_certificate_changed_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_surface_certificate_changed_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  event_payload jsonb;
  v_tenant_external_ref text;
BEGIN
  IF OLD.cert_state IS NOT DISTINCT FROM NEW.cert_state THEN
    RETURN NEW;
  END IF;

  IF NEW.platform_tenant_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT external_ref INTO v_tenant_external_ref
    FROM platform_tenants
   WHERE account_id = NEW.account_id AND id = NEW.platform_tenant_id;

  -- Unlinked surfaces remain on the existing app-scoped integration path.
  IF v_tenant_external_ref IS NULL THEN
    RETURN NEW;
  END IF;

  event_payload := jsonb_build_object(
    'platform_tenant_id', NEW.platform_tenant_id,
    'external_ref', v_tenant_external_ref,
    'surface_id', NEW.id,
    'surface_name', NEW.name::text,
    'app_id', NEW.app_id,
    'cert_state', NEW.cert_state,
    'cert_not_after', NEW.cert_not_after,
    'changed_at', statement_timestamp()
  );

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.surface.certificate.changed', event_payload
    FROM app_webhooks h
   WHERE h.scope = 'platform_tenant'
     AND h.platform_tenant_id = NEW.platform_tenant_id
     AND h.account_id = NEW.account_id
     AND h.enabled
     AND 'platform_tenant.surface.certificate.changed' = ANY(h.event_filter)
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_platform_tenant_surface_deployment_changed_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_platform_tenant_surface_deployment_changed_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status NOT IN ('live', 'failed') OR NEW.revision <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO app_webhook_deliveries
      (webhook_id, app_id, account_id, event, payload)
  SELECT h.id, NULL, h.account_id, 'platform_tenant.surface.deployment.changed',
         jsonb_build_object(
           'platform_tenant_id', t.id,
           'external_ref', t.external_ref,
           'surface_id', s.id,
           'surface_name', s.name::text,
           'revision', NEW.revision,
           'deployment_status', NEW.status,
           'started_at', NEW.created_at,
           'changed_at', statement_timestamp()
         )
    FROM tenant_surfaces s
    JOIN platform_tenants t
      ON t.account_id = s.account_id AND t.id = s.platform_tenant_id
    JOIN app_webhooks h
      ON h.account_id = s.account_id
     AND h.platform_tenant_id = t.id
     AND h.scope = 'platform_tenant'
     AND h.enabled
     AND 'platform_tenant.surface.deployment.changed' = ANY(h.event_filter)
   WHERE s.app_id = NEW.app_id
     AND s.platform_tenant_id IS NOT NULL
     AND s.status <> 'deleted'
  ON CONFLICT DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: enqueue_rollout_outcome_webhooks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_rollout_outcome_webhooks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_name text;
    event_payload jsonb;
BEGIN
    IF NEW.rollout_state IS NOT DISTINCT FROM OLD.rollout_state
       OR OLD.rollout_state NOT IN ('pending', 'rolling_out') THEN
        RETURN NEW;
    END IF;

    IF NEW.rollout_state = 'complete' AND NEW.status = 'live' THEN
        event_name := 'rollout.completed';
        event_payload := jsonb_build_object(
            'app_id', NEW.app_id,
            'deployment_id', NEW.id,
            'rollout_state', 'complete',
            'traffic_percent', NEW.traffic_percent,
            'completed_at', COALESCE(NEW.rollout_completed_at, now())
        );
    ELSIF NEW.rollout_state = 'aborted' AND OLD.status = 'live'
          AND NEW.status IN ('live', 'superseded') THEN
        event_name := 'rollout.aborted';
        event_payload := jsonb_build_object(
            'app_id', NEW.app_id,
            'deployment_id', NEW.id,
            'rollout_state', 'aborted',
            'traffic_percent', NEW.traffic_percent,
            'reason', COALESCE(NULLIF(NEW.rollout_aborted_reason, ''), 'rollout aborted'),
            'aborted_at', COALESCE(NEW.rollout_aborted_at, now())
        );
    ELSE
        RETURN NEW;
    END IF;

    INSERT INTO app_webhook_deliveries
        (webhook_id, app_id, account_id, event, payload)
    SELECT h.id, NEW.app_id, h.account_id, event_name, event_payload
      FROM app_webhooks h
      JOIN apps a ON a.id = NEW.app_id AND a.account_id = h.account_id
     WHERE h.enabled
       AND ((h.scope = 'app' AND h.app_id = NEW.app_id)
            OR (h.scope = 'account' AND h.app_id IS NULL))
       AND (event_name = ANY(h.event_filter)
            OR (h.scope = 'app' AND cardinality(h.event_filter) = 0));
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_route_policy_checks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_route_policy_checks(p_app uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE target uuid;
BEGIN
    FOR target IN SELECT d.id FROM deployments d JOIN apps a ON a.id = d.app_id
        JOIN saved_route_requirements s ON s.app_id = a.id AND s.account_id = a.account_id
        WHERE a.id = p_app AND a.status <> 'deleted' AND d.status = 'live'
          AND (EXISTS (SELECT 1 FROM deployment_openapi_docs c WHERE c.deployment_id = d.id AND c.app_id = a.id AND c.account_id = a.account_id)
            OR EXISTS (SELECT 1 FROM automatic_route_checks j WHERE j.deployment_id = d.id))
        ORDER BY d.id
    LOOP
        PERFORM enqueue_automatic_route_check(p_app, target, true);
    END LOOP;
END;
$$;


--
-- Name: environment_gitops_guard_app_presence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_app_presence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE;
BEGIN
    IF pg_trigger_depth() > 1 THEN
        IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.status = 'deleted') = (OLD.status = 'deleted') THEN RETURN NEW; END IF;
    FOR src IN SELECT s.* FROM active_environment_git_sources s
        JOIN environment_gitops_resources r ON r.source_id = s.id
        WHERE r.app_id = OLD.id ORDER BY s.id FOR UPDATE OF s
    LOOP
        IF (TG_OP = 'DELETE' OR NEW.status = 'deleted') AND src.mode = 'enforce' AND EXISTS (
            SELECT 1 FROM environment_managed_fields f JOIN environment_gitops_resources r
            ON r.source_id = f.source_id AND r.logical_name = f.resource
            WHERE f.source_id = src.id AND r.app_id = OLD.id AND f.field_path = 'presence'
              AND NOT EXISTS (SELECT 1 FROM environment_management_overrides o
                  WHERE o.environment_id = f.environment_id AND o.resource = f.resource AND o.field_path = 'presence'
                    AND o.expires_at > clock_timestamp())) THEN
            RAISE EXCEPTION 'workload membership is managed by the environment Git source'
                USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
        END IF;
        UPDATE environment_git_sources SET intent_version = intent_version + 1, updated_at = now() WHERE id = src.id;
        IF src.generation > 0 THEN
            INSERT INTO environment_gitops_jobs(source_id, desired_generation, next_attempt_at)
            VALUES (src.id, src.generation, now()) ON CONFLICT (source_id) DO UPDATE
            SET next_attempt_at = least(environment_gitops_jobs.next_attempt_at, excluded.next_attempt_at);
        END IF;
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: environment_gitops_guard_config_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_config_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF pg_trigger_depth() <= 1 AND EXISTS (
        SELECT 1 FROM active_environment_git_sources s JOIN project_environments e ON e.id = s.environment_id
        WHERE s.project_id = OLD.project_id AND s.account_id = OLD.account_id AND e.slug = OLD.environment_slug) THEN
        RAISE EXCEPTION 'managed configuration history is append-only'
            USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: environment_gitops_guard_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (to_jsonb(NEW) - ARRAY['value', 'updated_at', 'only_allow_declared_routes', 'declared_routes', 'rules'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['value', 'updated_at', 'only_allow_declared_routes', 'declared_routes', 'rules'])
       AND EXISTS (SELECT 1 FROM environment_gitops_resources r JOIN active_environment_git_sources s ON s.id = r.source_id
           JOIN project_environments e ON e.id = s.environment_id
           WHERE r.app_id = OLD.app_id AND s.account_id = OLD.account_id
           AND e.slug = coalesce(to_jsonb(OLD)->>'scope', to_jsonb(OLD)->>'environment_slug')) THEN
        RAISE EXCEPTION 'environment resource identity cannot be moved'
            USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: environment_gitops_guard_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_guard_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_value jsonb;
    src environment_git_sources%ROWTYPE;
    resource_name text;
    paths text[];
    prior_config jsonb;
    controller boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN row_value := to_jsonb(OLD); ELSE row_value := to_jsonb(NEW); END IF;
    IF TG_TABLE_NAME = 'project_environment_config_versions' THEN
        SELECT s.* INTO src FROM active_environment_git_sources s JOIN project_environments e ON e.id = s.environment_id
        WHERE s.account_id = (row_value->>'account_id')::uuid AND s.project_id = (row_value->>'project_id')::uuid
          AND e.slug = row_value->>'environment_slug' FOR UPDATE OF s;
        resource_name := 'environment';
        SELECT config_json INTO prior_config FROM project_environment_config_versions
        WHERE project_id = (row_value->>'project_id')::uuid AND environment_slug = row_value->>'environment_slug'
        ORDER BY version DESC LIMIT 1;
        SELECT array_agg('configuration/' || k) INTO paths FROM (
            SELECT key AS k FROM jsonb_each(coalesce(prior_config, '{}'))
            UNION SELECT key FROM jsonb_each(coalesce(row_value->'config_json', '{}'))
        ) keys WHERE (prior_config->k) IS DISTINCT FROM (row_value->'config_json'->k);
    ELSE
        SELECT s.* INTO src
        FROM active_environment_git_sources s JOIN project_environments e ON e.id = s.environment_id
        JOIN environment_gitops_resources r ON r.source_id = s.id
        WHERE s.account_id = (row_value->>'account_id')::uuid AND r.app_id = (row_value->>'app_id')::uuid
          AND e.slug = coalesce(row_value->>'scope', row_value->>'environment_slug') FOR UPDATE OF s;
        SELECT logical_name INTO resource_name FROM environment_gitops_resources
        WHERE source_id = src.id AND app_id = (row_value->>'app_id')::uuid;
        IF TG_TABLE_NAME = 'app_envs' THEN paths := ARRAY['variables/' || (row_value->>'key')];
        ELSIF TG_TABLE_NAME = 'project_environment_route_policies' THEN paths := ARRAY['routes'];
        ELSE paths := ARRAY['policies']; END IF;
    END IF;
    IF src.id IS NOT NULL THEN
        controller := EXISTS (SELECT 1 FROM environment_gitops_jobs j
            WHERE j.source_id = src.id AND j.desired_generation = src.generation AND j.claimed_generation = src.generation
              AND j.lease_until > clock_timestamp() AND j.lease_token <> ''
              AND j.lease_token = current_setting('gregale.gitops_lease', true)
              AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
        IF src.mode = 'enforce' AND NOT controller AND EXISTS (
            SELECT 1 FROM environment_managed_fields f
            WHERE f.environment_id = src.environment_id AND f.resource = resource_name AND f.field_path = ANY(paths)
              AND f.source_id = src.id AND NOT EXISTS (
                  SELECT 1 FROM environment_management_overrides o
                  WHERE o.environment_id = f.environment_id AND o.resource = f.resource AND o.field_path = f.field_path
                    AND o.expires_at > clock_timestamp())) THEN
            RAISE EXCEPTION 'setting is managed by the environment Git source'
                USING ERRCODE = '23514', CONSTRAINT = 'environment_gitops_field_owned';
        END IF;
        UPDATE environment_git_sources SET intent_version = intent_version + 1, updated_at = now() WHERE id = src.id;
        IF src.generation > 0 THEN
            INSERT INTO environment_gitops_jobs(source_id, desired_generation, next_attempt_at)
            VALUES (src.id, src.generation, now()) ON CONFLICT (source_id) DO UPDATE
            SET next_attempt_at = least(environment_gitops_jobs.next_attempt_at, excluded.next_attempt_at);
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: environment_gitops_queue_recovery_authorized(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_queue_recovery_authorized(target_binding uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE;
BEGIN
 -- Legacy SQL writers may acquire the binding first. Serialize authority on
 -- the source too; a deadlock aborts the whole transaction rather than granting
 -- a stale approved generation permission to release retained work.
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN queue_bindings b ON b.environment_id=s.environment_id
  JOIN apps a ON a.id=b.app_id AND a.account_id=s.account_id AND a.project_id=s.project_id
  WHERE b.id=target_binding AND b.account_id=s.account_id FOR UPDATE OF s;
 IF src.id IS NULL OR src.mode<>'enforce' OR src.suspended THEN RETURN false; END IF;
 RETURN environment_gitops_queue_recovery_declared(src.id,target_binding) AND EXISTS(
  SELECT 1 FROM environment_gitops_jobs j
   JOIN environment_gitops_queue_bindings q ON q.source_id=j.source_id AND q.binding_id=target_binding
   JOIN environment_managed_fields f ON f.source_id=q.source_id AND f.resource=q.resource AND f.field_path=q.field_path
  WHERE j.source_id=src.id AND j.desired_generation=src.generation AND j.claimed_generation=src.generation
   AND j.lease_until>clock_timestamp() AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND NOT EXISTS(SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=src.environment_id
    AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp()));
END;
$$;


--
-- Name: environment_gitops_queue_recovery_declared(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_gitops_queue_recovery_declared(target_source uuid, target_binding uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM active_environment_git_sources s
  JOIN environment_desired_revisions v ON v.id=s.approved_revision_id AND v.source_id=s.id
  JOIN environment_gitops_resources r ON r.source_id=s.id
  JOIN queue_bindings b ON b.id=target_binding AND b.app_id=r.app_id AND b.account_id=s.account_id AND b.environment_id=s.environment_id
  JOIN project_environments e ON e.id=s.environment_id AND e.account_id=s.account_id AND e.project_id=s.project_id
  WHERE s.id=target_source AND r.logical_name LIKE 'workload/%'
   AND v.definition->'workloads'->substr(r.logical_name,10)->'queue_recoveries'->>b.name=b.id::text
   AND v.definition->'workloads'->substr(r.logical_name,10)->'queue_bindings' ? b.name);
$$;


SET default_table_access_method = heap;

--
-- Name: environment_workload_qualification_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.environment_workload_qualification_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    graph_id uuid NOT NULL,
    deployment_id uuid NOT NULL,
    app_id uuid NOT NULL,
    resource text NOT NULL,
    artifact jsonb NOT NULL,
    frozen_inputs jsonb NOT NULL,
    execution_mode text NOT NULL,
    phase text DEFAULT 'queued'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    worker_id text DEFAULT ''::text NOT NULL,
    lease_token text DEFAULT ''::text NOT NULL,
    lease_until timestamp with time zone,
    attempt bigint DEFAULT 0 NOT NULL,
    reserved_instance_id uuid,
    CONSTRAINT environment_workload_qualification_request_execution_mode_check CHECK ((execution_mode = ANY (ARRAY['request'::text, 'service'::text, 'worker'::text, 'job'::text]))),
    CONSTRAINT environment_workload_qualification_requests_artifact_check CHECK ((jsonb_typeof(artifact) = 'object'::text)),
    CONSTRAINT environment_workload_qualification_requests_attempt_check CHECK ((attempt >= 0)),
    CONSTRAINT environment_workload_qualification_requests_check CHECK ((((phase = 'queued'::text) AND (worker_id = ''::text) AND (lease_token = ''::text) AND (lease_until IS NULL) AND (attempt = 0)) OR ((phase = 'claimed'::text) AND (worker_id <> ''::text) AND (lease_token <> ''::text) AND (lease_until IS NOT NULL) AND (attempt > 0)))),
    CONSTRAINT environment_workload_qualification_requests_frozen_inputs_check CHECK ((jsonb_typeof(frozen_inputs) = 'object'::text)),
    CONSTRAINT environment_workload_qualification_requests_phase_check CHECK ((phase = ANY (ARRAY['queued'::text, 'claimed'::text]))),
    CONSTRAINT environment_workload_qualification_requests_resource_check CHECK ((resource ~ '^workload/[a-z0-9][a-z0-9-]*$'::text)),
    CONSTRAINT environment_workload_qualification_requests_worker_id_check CHECK ((octet_length(worker_id) <= 256)),
    CONSTRAINT environment_workload_qualification_reserved_instance_shape CHECK ((((phase = 'queued'::text) AND (reserved_instance_id IS NULL)) OR ((phase = 'claimed'::text) AND (((execution_mode = 'job'::text) AND (reserved_instance_id IS NULL)) OR ((execution_mode <> 'job'::text) AND (reserved_instance_id IS NOT NULL))))))
);


--
-- Name: instances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instances (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    app_id uuid,
    deployment_id uuid,
    state text NOT NULL,
    netns text,
    guest_uid integer,
    host_ip inet,
    ram_mb integer NOT NULL,
    started_at timestamp with time zone,
    last_request_at timestamp with time zone,
    parked_at timestamp with time zone,
    terminal_at timestamp with time zone,
    node_id uuid NOT NULL,
    wake_id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    migrated_from_node_id uuid,
    migrated_at timestamp with time zone,
    lease_token text,
    framework_ready_at timestamp with time zone,
    tail_count integer DEFAULT 0 NOT NULL,
    request_count bigint DEFAULT 0 NOT NULL,
    kind text DEFAULT 'wake'::text NOT NULL,
    job_id uuid,
    mode text DEFAULT 'normal'::text NOT NULL,
    migration_started_at timestamp with time zone,
    startup_cpu_boost_until timestamp with time zone,
    exclusive_capture_blocked boolean DEFAULT false NOT NULL,
    capacity_ram_mb bigint DEFAULT 0 NOT NULL,
    capacity_cpu_millicores bigint DEFAULT 0 NOT NULL,
    capacity_vcpu integer DEFAULT 0 NOT NULL,
    CONSTRAINT instances_app_or_job_chk CHECK ((((kind = ANY (ARRAY['wake'::text, 'build'::text])) AND (app_id IS NOT NULL) AND (job_id IS NULL)) OR ((kind = 'job_task'::text) AND (app_id IS NULL) AND (job_id IS NOT NULL)))),
    CONSTRAINT instances_capacity_cpu_millicores_check CHECK ((capacity_cpu_millicores >= 0)),
    CONSTRAINT instances_capacity_ram_mb_check CHECK ((capacity_ram_mb >= 0)),
    CONSTRAINT instances_capacity_vcpu_check CHECK ((capacity_vcpu >= 0)),
    CONSTRAINT instances_kind_check CHECK ((kind = ANY (ARRAY['wake'::text, 'build'::text, 'job_task'::text]))),
    CONSTRAINT instances_migrated_at_chk CHECK (((migrated_at IS NULL) OR (migrated_at <= (now() + '00:01:00'::interval)))),
    CONSTRAINT instances_mode_check CHECK ((mode = ANY (ARRAY['normal'::text, 'mirror'::text, 'job'::text, 'worker'::text, 'service'::text]))),
    CONSTRAINT instances_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'parked'::text, 'waking'::text, 'cold_booting'::text, 'running'::text, 'draining'::text, 'snapshotting'::text, 'migrating'::text, 'warm'::text, 'stopped'::text, 'failed'::text, 'evicting_account_deleting'::text])))
);


--
-- Name: environment_qualification_execution_frame(public.environment_workload_qualification_requests, public.instances); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_qualification_execution_frame(q public.environment_workload_qualification_requests, i public.instances) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('instance_id',i.id,'request_id',q.id,'graph_id',q.graph_id,'app_id',i.app_id,'deployment_id',i.deployment_id,
  'node_id',i.node_id,'wake_id',i.wake_id,'source_id',q.frozen_inputs->>'source_id','environment_id',q.frozen_inputs->>'environment_id',
  'revision_id',q.frozen_inputs->>'revision_id','resource',q.resource,'scope',q.frozen_inputs->>'scope','plan_hash',q.frozen_inputs->>'plan_hash',
  'generation',(q.frozen_inputs->>'generation')::bigint,'intent_version',(q.frozen_inputs->>'intent_version')::bigint,
  'attempt',q.attempt,'ram_mb',i.ram_mb,'artifact',q.artifact);
$$;


--
-- Name: environment_runtime_base_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_base_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT
    NOT EXISTS (SELECT 1 FROM app_runtime_config_changes c WHERE c.app_id = target_app AND c.changed_at > boundary)
    AND NOT EXISTS (SELECT 1 FROM app_runtime_config_scope_changes c WHERE c.app_id = target_app
        AND c.scope IN ('default', target_scope) AND c.changed_at > boundary)
    AND observed_variables = coalesce((SELECT jsonb_object_agg(v.key, v.value) FROM app_envs v
        WHERE v.app_id = target_app AND v.scope = target_scope), '{}'::jsonb)
    AND NOT EXISTS (SELECT 1 FROM jsonb_each_text(observed_secrets) r WHERE NOT EXISTS (
        SELECT 1 FROM app_secrets v WHERE v.app_id = target_app AND v.scope = target_scope
        AND v.scope || '/' || v.key = r.key AND v.delivery_version::text = r.value))
    AND (NOT observed_all_secrets OR observed_secrets = coalesce((SELECT jsonb_object_agg(v.scope || '/' || v.key, v.delivery_version)
        FROM app_secrets v WHERE v.app_id = target_app AND v.scope = target_scope), '{}'::jsonb));
$$;


--
-- Name: environment_runtime_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_runtime_inputs_fresh(target_app,target_scope,boundary,observed_variables,observed_secrets,observed_all_secrets,'{}'::jsonb);
$$;


--
-- Name: environment_runtime_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean, observed_secret_refs jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_runtime_inputs_fresh(target_app,target_scope,boundary,observed_variables,observed_secrets,
  observed_all_secrets,observed_secret_refs,'{}'::jsonb);
$$;


--
-- Name: environment_runtime_inputs_fresh(uuid, text, timestamp with time zone, jsonb, jsonb, boolean, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_inputs_fresh(target_app uuid, target_scope text, boundary timestamp with time zone, observed_variables jsonb, observed_secrets jsonb, observed_all_secrets boolean, observed_secret_refs jsonb, observed_sidecar_secrets jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 WITH managed AS (SELECT environment_scoped_secret_refs(target_app,target_scope) AS refs),
 suppressed AS (SELECT environment_scoped_secret_suppressions(target_app,target_scope) AS keys),
 eligible AS (
  SELECT s.key,s.scope,s.delivery_version FROM app_secrets s
  WHERE s.app_id=target_app AND s.scope=target_scope AND
   (s.managed_postgres_binding_id IS NULL OR EXISTS (
    SELECT 1 FROM managed_postgres_bindings b WHERE b.id=s.managed_postgres_binding_id
     AND b.account_id=s.account_id AND b.app_id=s.app_id AND b.scope=s.scope
     AND b.environment_key=s.key AND b.access IN ('read_write','read_only','data_api')))
 ),
 baseline AS (SELECT coalesce(jsonb_object_agg(s.key,'secret:'||s.key),'{}'::jsonb) AS refs,
  coalesce(jsonb_object_agg(s.scope||'/'||s.key,s.delivery_version),'{}'::jsonb) AS versions FROM eligible s)
 SELECT environment_runtime_base_inputs_fresh(target_app,target_scope,boundary,observed_variables,observed_secrets,false)
  AND observed_sidecar_secrets <@ observed_secrets
  AND managed.refs <@ observed_secret_refs
  AND NOT observed_secret_refs ?| suppressed.keys
  AND NOT EXISTS (SELECT 1 FROM jsonb_each_text(observed_secrets) v WHERE NOT EXISTS (
   SELECT 1 FROM eligible s WHERE v.key=s.scope||'/'||s.key AND v.value=s.delivery_version::text))
  AND (cardinality(suppressed.keys)=0 OR observed_secrets=(coalesce((SELECT jsonb_object_agg(s.scope||'/'||s.key,s.delivery_version)
   FROM eligible s WHERE EXISTS (
    SELECT 1 FROM jsonb_each_text(observed_secret_refs) r WHERE r.value='secret:'||s.key)),'{}'::jsonb)||observed_sidecar_secrets))
  AND NOT EXISTS(SELECT 1 FROM jsonb_each(managed.refs) r WHERE observed_variables ? r.key)
  AND NOT EXISTS (SELECT 1 FROM jsonb_each_text(observed_secret_refs) r WHERE
   NOT EXISTS (SELECT 1 FROM eligible s WHERE r.value='secret:'||s.key
    AND observed_secrets->>(target_scope||'/'||s.key)=s.delivery_version::text))
  AND (NOT observed_all_secrets OR
   CASE WHEN observed_secret_refs='{}'::jsonb AND managed.refs='{}'::jsonb AND cardinality(suppressed.keys)=0
    THEN observed_secrets=baseline.versions
    ELSE observed_secret_refs=((baseline.refs - suppressed.keys)||managed.refs) END)
 FROM managed,baseline,suppressed;
$$;


--
-- Name: environment_runtime_receipt_required(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_runtime_receipt_required(target_app uuid, target_scope text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT environment_scoped_secret_refs(target_app,target_scope)<>'{}'::jsonb
  OR cardinality(environment_scoped_secret_suppressions(target_app,target_scope))>0 OR EXISTS (
  SELECT 1 FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
  JOIN environment_gitops_resources r ON r.source_id=s.id WHERE r.app_id=target_app AND e.slug=target_scope
  AND (EXISTS (SELECT 1 FROM environment_managed_fields f WHERE f.source_id=s.id AND f.resource=r.logical_name
   AND (f.field_path LIKE 'variables/%' OR f.field_path LIKE 'secret_refs/%'))
   OR EXISTS (SELECT 1 FROM environment_gitops_runtime_effects x WHERE x.source_id=s.id AND x.app_id=r.app_id AND x.completed_at IS NULL)));
$$;


--
-- Name: environment_scoped_secret_refs(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_scoped_secret_refs(target_app uuid, target_scope text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(jsonb_object_agg(r.key,'secret:'||r.secret_name),'{}'::jsonb)
 FROM app_environment_secret_refs r JOIN project_environments e ON e.id=r.environment_id
 JOIN apps a ON a.id=r.app_id AND a.account_id=r.account_id AND a.project_id=r.project_id
 WHERE r.app_id=target_app AND e.slug=target_scope AND e.account_id=r.account_id AND e.project_id=r.project_id;
$$;


--
-- Name: environment_scoped_secret_suppressions(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_scoped_secret_suppressions(target_app uuid, target_scope text) RETURNS text[]
    LANGUAGE sql STABLE
    AS $$
 SELECT coalesce(array_agg(r.key ORDER BY r.key),ARRAY[]::text[])
 FROM app_environment_secret_ref_suppressions r JOIN project_environments e ON e.id=r.environment_id
 JOIN apps a ON a.id=r.app_id AND a.account_id=r.account_id AND a.project_id=r.project_id
 WHERE r.app_id=target_app AND e.slug=target_scope AND e.account_id=r.account_id AND e.project_id=r.project_id;
$$;


--
-- Name: deployments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.deployments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    app_id uuid NOT NULL,
    build_id uuid,
    image_digest text NOT NULL,
    rootfs_path text,
    rootfs_bytes bigint,
    status text NOT NULL,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text DEFAULT 'image'::text NOT NULL,
    source_path text,
    source_bytes bigint,
    handler text,
    log_path text,
    error_code text,
    rootfs_key text DEFAULT ''::text NOT NULL,
    source_url text,
    commit_sha text,
    override_entrypoint text[],
    override_cmd text[],
    override_env jsonb,
    override_env_secrets jsonb,
    override_port integer,
    override_healthcheck jsonb,
    sidecars jsonb DEFAULT '[]'::jsonb NOT NULL,
    min_instances integer DEFAULT 0 NOT NULL,
    scan_result jsonb,
    scan_status text,
    scanned_at timestamp with time zone,
    override_liveness_probe jsonb,
    parked_reason text,
    parked_at timestamp with time zone,
    traffic_percent integer DEFAULT 100 NOT NULL,
    scope text DEFAULT 'default'::text NOT NULL,
    secret_findings jsonb DEFAULT '[]'::jsonb NOT NULL,
    secret_scanned_at timestamp with time zone,
    error_hint text,
    error_why text,
    error_fix text,
    error_relevant_logs jsonb,
    stage_state jsonb DEFAULT '{"current": "source_download", "history": [], "current_started_at": null}'::jsonb NOT NULL,
    deployed_by_user_id uuid,
    deployed_via text DEFAULT 'api'::text NOT NULL,
    deployed_from_ip inet,
    pusher_login text,
    reason text,
    tag text,
    deployed_by text,
    pr_number integer,
    rollback_on_5xx boolean DEFAULT false NOT NULL,
    first_wake_at timestamp with time zone,
    first_5xx_window_ends_at timestamp with time zone,
    first_5xx_count integer DEFAULT 0 NOT NULL,
    last_auto_rollback_at timestamp with time zone,
    last_auto_rollback_reason text,
    liveness_restart_count integer DEFAULT 0 NOT NULL,
    canary_preset text DEFAULT 'none'::text NOT NULL,
    canary_step integer DEFAULT 0 NOT NULL,
    canary_total_steps integer DEFAULT 0 NOT NULL,
    canary_step_started_at timestamp with time zone DEFAULT now() NOT NULL,
    rollout_state text DEFAULT 'pending'::text NOT NULL,
    rollout_started_at timestamp with time zone,
    rollout_completed_at timestamp with time zone,
    rollout_aborted_at timestamp with time zone,
    rollout_aborted_reason text,
    cancelled_at timestamp with time zone,
    cancelled_by_principal text,
    cancel_reason text,
    deleted_at timestamp with time zone,
    deleted_by_principal text,
    priority integer DEFAULT 100 NOT NULL,
    reordered_at timestamp with time zone,
    reordered_by_principal text,
    canary_stages jsonb,
    snapshot_miss_count integer DEFAULT 0 NOT NULL,
    snapshot_miss_last_at timestamp with time zone,
    snapshot_miss_backoff_until timestamp with time zone,
    workflows jsonb DEFAULT '[]'::jsonb NOT NULL,
    source_root text,
    full_rootfs_allow_auto boolean DEFAULT false NOT NULL,
    full_rootfs_override boolean,
    source_sha256 text,
    api_hosting_receipt jsonb DEFAULT '{}'::jsonb NOT NULL,
    inferred_profile jsonb,
    traffic_percent_explicit boolean DEFAULT false NOT NULL,
    revision integer DEFAULT 0 NOT NULL,
    service_rollout_handoff jsonb DEFAULT '{}'::jsonb NOT NULL,
    release_command text[] DEFAULT ARRAY[]::text[] NOT NULL,
    release_command_shell boolean DEFAULT false NOT NULL,
    disable_startup_cpu_boost boolean DEFAULT false NOT NULL,
    override_main_depends_on jsonb DEFAULT '[]'::jsonb NOT NULL,
    override_readiness_probe jsonb,
    secret_reload_signal text,
    github_source_ref text,
    github_installation_id bigint,
    environment_workload_runtime jsonb,
    serving_ended_at timestamp with time zone,
    runtime_upgrade_routing_token uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT deployments_canary_preset_chk CHECK ((canary_preset = ANY (ARRAY['none'::text, 'slow'::text, 'balanced'::text, 'aggressive'::text, '1-10-50-100'::text, 'custom'::text]))),
    CONSTRAINT deployments_canary_stages_shape CHECK (((canary_preset <> 'custom'::text) OR ((canary_stages IS NOT NULL) AND (jsonb_typeof(canary_stages) = 'array'::text) AND (jsonb_array_length(canary_stages) > 0)))),
    CONSTRAINT deployments_canary_step_nonneg_chk CHECK ((canary_step >= 0)),
    CONSTRAINT deployments_canary_total_steps_nonneg_chk CHECK ((canary_total_steps >= 0)),
    CONSTRAINT deployments_cancel_reason_check CHECK (((cancel_reason IS NULL) OR (cancel_reason = ANY (ARRAY['user'::text, 'auto_quota'::text, 'auto_health'::text, 'system'::text])))),
    CONSTRAINT deployments_cancelled_release_fence_chk CHECK (((status <> 'cancelled'::text) OR ((traffic_percent = 0) AND (rollout_state = 'aborted'::text) AND (rollout_aborted_at IS NOT NULL) AND (COALESCE((stage_state ->> 'current'::text), ''::text) = ''::text)))),
    CONSTRAINT deployments_commit_sha_shape_chk CHECK (((commit_sha IS NULL) OR (((char_length(commit_sha) >= 7) AND (char_length(commit_sha) <= 64)) AND (commit_sha ~ '^[0-9a-f]+$'::text)))),
    CONSTRAINT deployments_deployed_via_set_chk CHECK ((deployed_via = ANY (ARRAY['api'::text, 'cli'::text, 'dashboard'::text, 'github'::text, 'operator'::text]))),
    CONSTRAINT deployments_environment_workload_runtime_shape CHECK (((environment_workload_runtime IS NULL) OR ((jsonb_typeof(environment_workload_runtime) = 'object'::text) AND (environment_workload_runtime ?& ARRAY['source_id'::text, 'environment_id'::text, 'revision_id'::text, 'generation'::text, 'intent_version'::text, 'resource'::text, 'plan_hash'::text, 'app_id'::text, 'scope'::text, 'baseline'::text, 'start_command'::text, 'runtime'::text]) AND (jsonb_typeof((environment_workload_runtime -> 'runtime'::text)) = 'object'::text) AND (jsonb_typeof((environment_workload_runtime -> 'baseline'::text)) = 'object'::text) AND (((environment_workload_runtime ->> 'generation'::text))::bigint > 0) AND (((environment_workload_runtime ->> 'intent_version'::text))::bigint >= 0) AND ((environment_workload_runtime ->> 'plan_hash'::text) ~ '^[a-f0-9]{64}$'::text) AND ((environment_workload_runtime ->> 'resource'::text) ~ '^workload/[a-z0-9][a-z0-9-]*$'::text)))),
    CONSTRAINT deployments_failed_stage_fence_chk CHECK (((status <> 'failed'::text) OR (COALESCE((stage_state ->> 'current'::text), ''::text) = ''::text))),
    CONSTRAINT deployments_failed_traffic_fence_chk CHECK (((status <> 'failed'::text) OR ((traffic_percent = 0) AND (rollout_state = 'aborted'::text) AND (rollout_aborted_at IS NOT NULL)))),
    CONSTRAINT deployments_github_source_ref_pair_chk CHECK ((((github_source_ref IS NULL) AND (github_installation_id IS NULL)) OR ((github_source_ref IS NOT NULL) AND (btrim(github_source_ref) <> ''::text) AND (github_installation_id IS NOT NULL) AND (github_installation_id > 0)))),
    CONSTRAINT deployments_kind_check CHECK ((kind = ANY (ARRAY['image'::text, 'tarball'::text, 'dockerfile'::text, 'github'::text, 'preview'::text]))),
    CONSTRAINT deployments_last_auto_rollback_reason_check CHECK (((last_auto_rollback_reason IS NULL) OR (last_auto_rollback_reason = ANY (ARRAY['threshold_exceeded'::text, 'first_window_expired'::text])))),
    CONSTRAINT deployments_liveness_restart_count_nonneg_chk CHECK ((liveness_restart_count >= 0)),
    CONSTRAINT deployments_main_depends_on_shape_chk CHECK (((jsonb_typeof(override_main_depends_on) = 'array'::text) AND (jsonb_array_length(override_main_depends_on) <= 6))),
    CONSTRAINT deployments_min_instances_chk CHECK (((min_instances >= 0) AND (min_instances <= 100))),
    CONSTRAINT deployments_parked_reason_check CHECK (((parked_reason IS NULL) OR (parked_reason = ANY (ARRAY['liveness_exhausted'::text, 'lifecycle_park'::text, 'admin_park'::text, 'security_scan_regressed'::text])))),
    CONSTRAINT deployments_pr_number_positive_chk CHECK (((pr_number IS NULL) OR (pr_number > 0))),
    CONSTRAINT deployments_priority_check CHECK (((priority >= 0) AND (priority <= 1000))),
    CONSTRAINT deployments_reason_len_chk CHECK (((reason IS NULL) OR (length(reason) <= 280))),
    CONSTRAINT deployments_release_command_chk CHECK ((((cardinality(release_command) = 0) AND (NOT release_command_shell)) OR (((cardinality(release_command) >= 1) AND (cardinality(release_command) <= 64)) AND (array_position(release_command, NULL::text) IS NULL) AND ((octet_length(btrim(release_command[1])) >= 1) AND (octet_length(btrim(release_command[1])) <= 4096)) AND ((octet_length(array_to_string(release_command, ''::text)) >= 1) AND (octet_length(array_to_string(release_command, ''::text)) <= 16384)) AND ((NOT release_command_shell) OR (cardinality(release_command) = 1))))),
    CONSTRAINT deployments_revision_nonneg_chk CHECK ((revision >= 0)),
    CONSTRAINT deployments_rollout_state_chk CHECK ((rollout_state = ANY (ARRAY['pending'::text, 'rolling_out'::text, 'complete'::text, 'aborted'::text]))),
    CONSTRAINT deployments_runtime_upgrade_routing_token_check CHECK ((runtime_upgrade_routing_token <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT deployments_scan_status_chk CHECK (((scan_status IS NULL) OR (scan_status = ANY (ARRAY['pending'::text, 'complete'::text, 'failed'::text, 'skipped'::text, 'complete_with_redactions'::text])))),
    CONSTRAINT deployments_scope_shape CHECK ((scope ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'::text)),
    CONSTRAINT deployments_secret_reload_signal_chk CHECK (((secret_reload_signal IS NULL) OR (secret_reload_signal = ANY (ARRAY[''::text, 'SIGHUP'::text, 'SIGUSR1'::text, 'SIGUSR2'::text])))),
    CONSTRAINT deployments_service_rollout_handoff_object_chk CHECK ((jsonb_typeof(service_rollout_handoff) = 'object'::text)),
    CONSTRAINT deployments_service_rollout_handoff_size_chk CHECK ((octet_length((service_rollout_handoff)::text) <= 16384)),
    CONSTRAINT deployments_service_rollout_handoff_state_chk CHECK (((service_rollout_handoff = '{}'::jsonb) OR (((service_rollout_handoff ->> 'action'::text) = ANY (ARRAY['promote'::text, 'abort'::text])) AND ((service_rollout_handoff ->> 'phase'::text) = ANY (ARRAY['pending'::text, 'routing'::text, 'draining'::text, 'complete'::text])) AND (COALESCE(((service_rollout_handoff ->> 'retry_count'::text))::integer, 0) >= 0)))),
    CONSTRAINT deployments_sidecars_cap_chk CHECK ((jsonb_array_length(sidecars) <= 5)),
    CONSTRAINT deployments_source_root_shape_chk CHECK (((source_root IS NULL) OR (source_root = ''::text) OR (source_root = '.'::text) OR ((source_root !~ '^/'::text) AND (source_root !~ '(^|/)\.\.(/|$)'::text)))),
    CONSTRAINT deployments_source_sha256_shape_chk CHECK (((source_sha256 IS NULL) OR (source_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT deployments_stage_state_current_check CHECK ((((stage_state ->> 'current'::text) IS NULL) OR ((stage_state ->> 'current'::text) = ''::text) OR ((stage_state ->> 'current'::text) = ANY (ARRAY['source_download'::text, 'dependency_restore'::text, 'image_build'::text, 'security_scan'::text, 'snapshot_prepare'::text, 'readiness'::text])))),
    CONSTRAINT deployments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'building'::text, 'imaging'::text, 'snapshotting'::text, 'live'::text, 'failed'::text, 'superseded'::text, 'cancelled'::text]))),
    CONSTRAINT deployments_tag_set_chk CHECK (((tag IS NULL) OR (tag = ANY (ARRAY['incident_recovery'::text, 'hotfix'::text, 'scheduled_maintenance'::text, 'compliance_hold'::text, 'partner_request'::text])))),
    CONSTRAINT deployments_traffic_percent_chk CHECK (((traffic_percent >= 0) AND (traffic_percent <= 100)))
);


--
-- Name: environment_workload_artifact(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_artifact(d public.deployments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object('rootfs_path',coalesce((d).rootfs_path,''),'rootfs_key',coalesce((d).rootfs_key,''),
  'rootfs_bytes',coalesce((d).rootfs_bytes,0),'image_digest',coalesce((d).image_digest,''),
  'build_id',coalesce((d).build_id::text,''),'kind',(d).kind,'commit_sha',coalesce((d).commit_sha,''));
$$;


--
-- Name: environment_workload_deployment_inputs(public.deployments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_deployment_inputs(d public.deployments) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT jsonb_build_object(
  'override_entrypoint',coalesce((d).override_entrypoint,ARRAY[]::text[]),'override_cmd',coalesce((d).override_cmd,ARRAY[]::text[]),
  'override_env',coalesce(nullif((d).override_env,'null'::jsonb),'{}'::jsonb),'override_env_secrets',coalesce(nullif((d).override_env_secrets,'null'::jsonb),'{}'::jsonb),
  'override_port',coalesce((d).override_port,0),'override_healthcheck',coalesce(nullif((d).override_healthcheck,'null'::jsonb),'{}'::jsonb),
  'override_liveness_probe',coalesce(nullif((d).override_liveness_probe,'null'::jsonb),'{}'::jsonb),'override_readiness_probe',coalesce(nullif((d).override_readiness_probe,'null'::jsonb),'{}'::jsonb),
  'override_main_depends_on',(d).override_main_depends_on,
  'sidecars',coalesce((SELECT jsonb_agg(sc-'secret_reload_signal' ORDER BY position) FROM jsonb_array_elements((d).sidecars) WITH ORDINALITY AS s(sc,position)),'[]'::jsonb),
  'workflows',(d).workflows,
  'full_rootfs_allow_auto',(d).full_rootfs_allow_auto,'full_rootfs_override',(d).full_rootfs_override,
  'min_instances',(d).min_instances,'release_command',(d).release_command,'release_command_shell',(d).release_command_shell,
  'disable_startup_cpu_boost',(d).disable_startup_cpu_boost,
  'rollback_on_5xx',(d).rollback_on_5xx);
$$;


--
-- Name: environment_workload_qualification_inputs_current(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.environment_workload_qualification_inputs_current(request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
 SELECT EXISTS(SELECT 1 FROM environment_workload_qualification_requests target
  JOIN environment_workload_graphs g ON g.id=target.graph_id JOIN active_environment_git_sources s ON s.id=g.source_id
  JOIN project_environments e ON e.id=g.environment_id JOIN accounts c ON c.id=s.account_id
  WHERE target.id=request_id AND g.phase='prepared' AND s.mode='enforce' AND NOT s.suspended
   AND c.status='active' AND c.abuse_hold_at IS NULL
   AND g.generation=s.generation AND g.intent_version=s.intent_version AND g.revision_id=s.approved_revision_id
   AND g.environment_id=s.environment_id AND e.account_id=s.account_id AND e.project_id=s.project_id
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m LEFT JOIN apps a ON a.id=(m->>'app_id')::uuid
    WHERE a.id IS NULL OR a.status NOT IN ('active','evicted_cold') OR a.account_id<>s.account_id OR a.project_id<>s.project_id
     OR m->'retained_deployments' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(d.id::text ORDER BY d.id),'[]'::jsonb)
      FROM deployments d WHERE d.app_id=a.id AND d.scope=e.slug AND d.status='live'))
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.members) m
    LEFT JOIN environment_workload_qualification_requests q ON q.graph_id=g.id AND q.resource=m->>'resource'
     AND q.app_id=(m->>'app_id')::uuid AND q.deployment_id=(m->>'candidate_deployment_id')::uuid
    LEFT JOIN deployments d ON d.id=q.deployment_id LEFT JOIN apps a ON a.id=q.app_id
    WHERE m ? 'candidate_deployment_id' AND (q.id IS NULL OR d.status IS DISTINCT FROM 'snapshotting' OR coalesce(d.rootfs_bytes,0)<=0
     OR q.artifact IS DISTINCT FROM environment_workload_artifact(d) OR q.frozen_inputs IS DISTINCT FROM d.environment_workload_runtime
     OR d.scope IS DISTINCT FROM e.slug OR d.app_id IS DISTINCT FROM a.id
     OR jsonb_strip_nulls(q.frozen_inputs->'baseline') IS DISTINCT FROM jsonb_strip_nulls(a.manifest)
     OR q.frozen_inputs->>'start_command' IS DISTINCT FROM coalesce(a.start_command,'') OR q.frozen_inputs->>'app_type' IS DISTINCT FROM a.type
     OR q.frozen_inputs->>'runtime_base' IS DISTINCT FROM coalesce(a.runtime,'') OR q.frozen_inputs->>'workload_class' IS DISTINCT FROM a.workload_class
     OR q.frozen_inputs ? 'deployment_inputs' AND EXISTS(SELECT 1 FROM deployments original
      WHERE original.app_id=a.id AND original.scope=e.slug AND original.status='live'
       AND environment_workload_deployment_inputs(original) IS DISTINCT FROM q.frozen_inputs->'deployment_inputs'))));
$$;


--
-- Name: event_backlog_waiting_reason(text, text, text, timestamp with time zone, timestamp with time zone, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_backlog_waiting_reason(routing_state text, capacity_scope text, routing_mode text, lease_until timestamp with time zone, next_attempt_at timestamp with time zone, consumer_kind text, blocker jsonb, observed_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
 WHEN routing_state = 'processing' THEN 'routing_in_progress'
 WHEN blocker IS NOT NULL THEN 'ordering_blocked'
 WHEN routing_state = 'pending' AND capacity_scope <> '' THEN 'capacity_' || capacity_scope
 WHEN routing_mode = 'event' AND lease_until > observed_at THEN 'receipt_processing'
 WHEN next_attempt_at > observed_at THEN 'retry_backoff'
 WHEN consumer_kind = 'workflow' THEN 'workflow_routing'
 ELSE 'ready' END;
$$;


--
-- Name: event_fanout_pattern_matches(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_fanout_pattern_matches(pattern text, value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT CASE
        WHEN pattern = '*' THEN true
        WHEN left(pattern, 1) = '*' AND right(pattern, 1) = '*' THEN
            position(substring(pattern, 2, greatest(length(pattern) - 2, 0)) in value) > 0
        WHEN left(pattern, 1) = '*' THEN
            right(value, greatest(length(pattern) - 1, 0)) = right(pattern, greatest(length(pattern) - 1, 0))
        WHEN right(pattern, 1) = '*' THEN
            left(value, greatest(length(pattern) - 1, 0)) = left(pattern, greatest(length(pattern) - 1, 0))
        ELSE pattern = value
    END
$$;


--
-- Name: event_order_lane_active(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_order_lane_active(lane_app_id text, lane_policy_name text, configured_ordered boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT coalesce(configured_ordered, false) OR EXISTS (
    SELECT 1 FROM event_subscription_work_bindings b
    WHERE b.app_id = lane_app_id::uuid
      AND b.policy_name = lane_policy_name
      AND b.ordered
);
$$;


--
-- Name: event_order_lane_lock_id(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_order_lane_lock_id(lane_app_id text, lane_policy_name text, event_payload jsonb, key_selector text) RETURNS bigint
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
WITH selected AS (
    SELECT event_payload #> string_to_array(key_selector, '.') AS value
), canonical AS (
    SELECT CASE jsonb_typeof(value)
        WHEN 'string' THEN 's:' || (value #>> '{}')
        WHEN 'number' THEN 'n:' || trim_scale((value #>> '{}')::numeric)::text
        WHEN 'boolean' THEN 'b:' || (value #>> '{}')
        ELSE NULL
    END AS key
    FROM selected
)
SELECT CASE WHEN key IS NULL OR key = 's:' THEN NULL
    ELSE hashtextextended(jsonb_build_array(lane_app_id, lane_policy_name, key)::text, 0)
    END
FROM canonical;
$$;


--
-- Name: event_recipient_delivery_deadline(jsonb, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_delivery_deadline(recipient jsonb, accepted_at timestamp with time zone, progress jsonb) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    AS $$
 SELECT CASE WHEN recipient ? 'workflow' OR recipient ? 'object_notification'
 OR coalesce((recipient->'work'->>'ordered')::boolean,false)
 OR coalesce((progress->>'delivery_age_override')::boolean,false)
 OR coalesce((recipient->>'delivery_age_override')::boolean,false)
 OR coalesce((recipient->'routing_retry_policy'->>'max_delivery_age_ms')::bigint,0)=0 THEN NULL
 ELSE accepted_at + ((recipient->'routing_retry_policy'->>'max_delivery_age_ms')::bigint * interval '1 millisecond') END;
$$;


--
-- Name: event_recipient_order_blocked(bigint, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_order_blocked(target_outbox_id bigint, target_subscription_id text, target_recipient jsonb, include_same_receipt boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT event_recipient_order_blocker(target_outbox_id, target_subscription_id, target_recipient, include_same_receipt) IS NOT NULL;
$$;


--
-- Name: event_recipient_order_blocker(bigint, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_order_blocker(target_outbox_id bigint, target_subscription_id text, target_recipient jsonb, include_same_receipt boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
WITH current_event AS (
    SELECT o.id, o.account_id, o.payload,
        (SELECT item.position
         FROM jsonb_array_elements(coalesce(o.recipient_snapshot, '[]'::jsonb))
              WITH ORDINALITY AS item(recipient, position)
         WHERE item.recipient->>'id' = target_subscription_id
         LIMIT 1) AS position,
        (SELECT coalesce((item.recipient->'work'->>'routing_order')::bigint, o.id)
         FROM jsonb_array_elements(coalesce(o.recipient_snapshot, '[]'::jsonb))
              WITH ORDINALITY AS item(recipient, position)
         WHERE item.recipient->>'id' = target_subscription_id
         LIMIT 1) AS routing_order
    FROM event_fanout_outbox o
    WHERE o.id = target_outbox_id
)
SELECT (
    SELECT jsonb_build_object(
        'event_source', prior.source, 'event_id', prior.event_id,
        'subscription_id', item.recipient->>'id', 'accepted_at', prior.created_at,
        'state', coalesce(routed.state, prior.recipient_progress->(item.recipient->>'id')->>'state', 'pending'),
        'next_attempt_at', CASE WHEN routed.state = 'pending' THEN routed.available_at
          WHEN routed.state IS NULL AND coalesce(prior.recipient_progress->(item.recipient->>'id')->>'state','pending') = 'pending'
          THEN coalesce((prior.recipient_progress->(item.recipient->>'id')->>'next_attempt_at')::timestamptz, prior.available_at) ELSE NULL END)
    FROM current_event current
    JOIN event_fanout_outbox prior ON prior.account_id = current.account_id
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(prior.recipient_snapshot, '[]'::jsonb))
        WITH ORDINALITY AS item(recipient, position)
    LEFT JOIN event_fanout_recipients routed
      ON routed.outbox_id = prior.id AND routed.subscription_id = item.recipient->>'id'
    WHERE ((prior.id <> current.id AND
            (coalesce((item.recipient->'work'->>'routing_order')::bigint, prior.id) < current.routing_order OR
             (item.recipient->'work'->>'routing_order' IS NULL AND
              target_recipient->'work'->>'routing_order' IS NOT NULL AND prior.id < current.id))) OR
           (include_same_receipt AND prior.id = current.id AND item.position < current.position))
      AND prior.state <> 'delivered'
      AND item.recipient->>'app_id' = target_recipient->>'app_id'
      AND item.recipient->'work'->>'policy_name' = target_recipient->'work'->>'policy_name'
      AND item.recipient->'work'->>'policy_name' <> ''
      AND event_order_lane_lock_id(item.recipient->>'app_id',
          item.recipient->'work'->>'policy_name', prior.payload,
          item.recipient->'work'->>'key_selector') IS NOT NULL
      AND event_order_lane_lock_id(target_recipient->>'app_id',
          target_recipient->'work'->>'policy_name', current.payload,
          target_recipient->'work'->>'key_selector') IS NOT NULL
      AND (coalesce((item.recipient->'work'->>'ordered')::boolean, false) OR
           item.recipient->'work'->>'routing_order' IS NOT NULL OR
           coalesce((target_recipient->'work'->>'ordered')::boolean, false) OR
           target_recipient->'work'->>'routing_order' IS NOT NULL)
      AND prior.payload #> string_to_array(item.recipient->'work'->>'key_selector', '.')
          IS NOT DISTINCT FROM
          current.payload #> string_to_array(target_recipient->'work'->>'key_selector', '.')
      AND coalesce(routed.state,
          (prior.recipient_progress->(item.recipient->>'id'))->>'state', 'pending')
          NOT IN ('enqueued', 'filtered', 'failed')
    ORDER BY coalesce((item.recipient->'work'->>'routing_order')::bigint, prior.id), prior.id, item.position
    LIMIT 1
);
$$;


--
-- Name: event_recipient_schema_version_mismatch(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recipient_schema_version_mismatch(recipient jsonb, payload jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT NOT recipient ? 'workflow' AND NOT recipient ? 'object_notification' AND jsonb_array_length(coalesce(recipient->'schema_versions','[]'::jsonb))>0 AND NOT (recipient->'schema_versions' ? coalesce(payload->>'schemaversion',''));
$$;


--
-- Name: event_recovery_failure_identity(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_recovery_failure_identity(progress jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
SELECT jsonb_build_object('state',progress->'state','attempts',progress->'attempts',
 'updated_at',progress->'updated_at','failure_code',progress->'failure_code','retryable',progress->'retryable');
$$;


--
-- Name: event_subscription_delivery_waiting_reason(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.event_subscription_delivery_waiting_reason(account uuid, app uuid, subscription text, observed_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
SELECT coalesce((SELECT CASE WHEN c.paused THEN 'subscription_paused'
 WHEN b.state_data->>'state'='open' AND (b.state_data->>'cooldown_until')::timestamptz>observed_at THEN 'circuit_open'
 WHEN b.state_data->>'state'='half_open' AND ((coalesce(b.state_data->>'probe_token','')<>'' AND (b.state_data->>'probe_until')::timestamptz>observed_at) OR (b.state_data->>'next_probe_at')::timestamptz>observed_at) THEN 'circuit_probe_wait'
 WHEN b.state_data->>'state'='draining' AND (b.state_data->>'recovery_window')::timestamptz+interval '1 second'>observed_at
 AND (b.state_data->>'recovery_count')::integer>=least((b.policy->>'recovery_max_rate_per_second')::integer,
 power(2,least(7,greatest(0,floor(extract(epoch FROM observed_at-(b.state_data->>'changed_at')::timestamptz)/10))))::integer) THEN 'circuit_recovery_rate_limited'
 WHEN c.rate_per_second>0 AND c.window_count>=c.rate_per_second AND c.window_started_at+interval '1 second'>observed_at THEN 'subscription_rate_limited' ELSE '' END
 FROM event_subscription_delivery_controls c JOIN apps a ON a.id=c.app_id AND a.account_id=c.account_id AND a.status<>'deleted'
 LEFT JOIN event_subscription_circuit_breakers b ON b.subscription_id=c.subscription_id AND b.account_id=c.account_id AND b.app_id=c.app_id
 WHERE c.account_id=account AND c.app_id=app AND c.subscription_id::text=subscription),'');
$$;


--
-- Name: exclusive_work_instance_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exclusive_work_instance_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE old_incarnation text;
BEGIN
  old_incarnation := old.id::text || '/' || old.wake_id::text || '/' || old.node_id::text;
  IF new.state IN ('snapshotting','parked') AND new.state IS DISTINCT FROM old.state
     AND EXISTS(SELECT 1 FROM exclusive_work_operations WHERE state='running'
       AND incarnation_id=old_incarnation AND lease_expires_at>clock_timestamp()
       AND attempt_deadline>clock_timestamp()) THEN
    RAISE EXCEPTION 'active exclusive operation prevents parking' USING errcode='55000';
  END IF;
  IF new.wake_id IS DISTINCT FROM old.wake_id OR new.node_id IS DISTINCT FROM old.node_id
     OR new.state IS DISTINCT FROM old.state THEN
    UPDATE exclusive_work_operations SET state='pending',claim_token=NULL,
      lease_expires_at=NULL,attempt_deadline=NULL,last_error='runtime incarnation revoked',
      due_at=clock_timestamp()
    WHERE state='running' AND incarnation_id=old_incarnation;
    NEW.exclusive_capture_blocked := false;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: exclusive_work_release_quota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.exclusive_work_release_quota() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.quota_reserved AND NEW.state<>'running' THEN
    UPDATE account_async_quota SET current_inflight=greatest(0,current_inflight-1),updated_at=clock_timestamp()
      WHERE account_id=OLD.account_id;
    NEW.quota_reserved := false;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: faas_capture_app_webhook_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_app_webhook_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'dead' AND OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        ) VALUES (
            NEW.account_id, NEW.app_id, 'webhook_delivery', NEW.id, NEW.event,
            COALESCE(NEW.payload, '{}'::jsonb), '{}'::jsonb,
            CASE WHEN NEW.last_response_code IS NULL
                 THEN 'delivery_failed'
                 ELSE 'http_' || NEW.last_response_code::text END,
            jsonb_build_object(
                'last_error', COALESCE(NEW.last_error, ''),
                'last_response_code', NEW.last_response_code
            ),
            NEW.attempt, COALESCE(NEW.updated_at, NOW()),
            COALESCE(NEW.updated_at, NOW()), COALESCE(NEW.created_at, NOW())
        )
        ON CONFLICT (source, source_id) DO UPDATE SET
            origin = EXCLUDED.origin,
            event_payload = EXCLUDED.event_payload,
            headers = EXCLUDED.headers,
            error_kind = EXCLUDED.error_kind,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_invocation_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_invocation_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state = 'dead_letter' AND OLD.state IS DISTINCT FROM NEW.state THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        ) VALUES (
            NEW.account_id, NEW.app_id, 'invocation', NEW.id,
            CASE
                WHEN COALESCE(NEW.headers->>'x-gregale-event-id', '') <> ''
                    THEN 'event_subscription'
                ELSE NEW.source
            END,
            COALESCE(NEW.payload, '{}'::jsonb),
            COALESCE(NEW.headers, '{}'::jsonb),
            COALESCE(NULLIF(NEW.outcome, ''), 'dead_letter'),
            jsonb_build_object('last_error', COALESCE(NEW.last_error, '')),
            NEW.attempts,
            COALESCE(NEW.completed_at, NOW()),
            COALESCE(NEW.completed_at, NOW()),
            COALESCE(NEW.completed_at, NOW())
        )
        ON CONFLICT (source, source_id) DO UPDATE SET
            origin = EXCLUDED.origin,
            event_payload = EXCLUDED.event_payload,
            headers = EXCLUDED.headers,
            error_kind = EXCLUDED.error_kind,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_job_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_job_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.dead_letter_count > COALESCE(OLD.dead_letter_count, 0) THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        ) VALUES (
            NEW.account_id, NULL, 'job_run', NEW.id, NEW.trigger_kind,
            jsonb_build_object(
                'job_id', NEW.job_id::text,
                'trigger_kind', NEW.trigger_kind,
                'tasks', NEW.tasks,
                'tasks_failed', NEW.tasks_failed,
                'dead_letter_count', NEW.dead_letter_count
            ),
            '{}'::jsonb,
            'job_run_dead_letter',
            jsonb_build_object(
                'dead_letter_count', NEW.dead_letter_count,
                'tasks_failed', NEW.tasks_failed
            ),
            NEW.dead_letter_count,
            COALESCE(NEW.finished_at, NOW()),
            COALESCE(NEW.finished_at, NOW()),
            COALESCE(NEW.finished_at, NOW())
        )
        ON CONFLICT (source, source_id) DO UPDATE SET
            event_payload = EXCLUDED.event_payload,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_trigger_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_trigger_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO dead_letter_events (
        account_id, app_id, source, source_id, origin, trigger_id,
        event_payload, headers, error_kind, error_detail, retry_count,
        first_failed_at, last_failed_at, created_at
    )
    SELECT t.account_id, t.app_id, 'trigger_record', NEW.record_id,
           t.kind, NEW.trigger_id,
           COALESCE(r.payload, '{}'::jsonb),
           COALESCE(r.headers, '{}'::jsonb),
           NEW.reason, COALESCE(NEW.detail, '{}'::jsonb),
           COALESCE(r.attempts, 0), NEW.created_at, NEW.created_at, NEW.created_at
      FROM triggers t
      JOIN trigger_records r ON r.id = NEW.record_id
     WHERE t.id = NEW.trigger_id
    ON CONFLICT (source, source_id) DO UPDATE SET
        origin = EXCLUDED.origin,
        trigger_id = EXCLUDED.trigger_id,
        event_payload = EXCLUDED.event_payload,
        headers = EXCLUDED.headers,
        error_kind = EXCLUDED.error_kind,
        error_detail = EXCLUDED.error_detail,
        retry_count = EXCLUDED.retry_count,
        last_failed_at = EXCLUDED.last_failed_at,
        replayed_at = NULL;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_workflow_dead_letter_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_workflow_dead_letter_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'dead' AND OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO dead_letter_events (
            account_id, app_id, source, source_id, origin, event_payload,
            headers, error_kind, error_detail, retry_count,
            first_failed_at, last_failed_at, created_at
        )
        SELECT a.account_id, NEW.app_id, 'workflow_run', NEW.id,
               NEW.workflow_name,
               jsonb_build_object(
                   'workflow_name', NEW.workflow_name,
                   'input', COALESCE(NEW.input, '{}'::jsonb),
                   'current_step', NEW.current_step
               ),
               '{}'::jsonb,
               'workflow_run_dead',
               jsonb_build_object('last_error', COALESCE(NEW.last_error, '')),
               COALESCE((
                   SELECT MAX(ws.attempt) FROM workflow_steps ws
                    WHERE ws.run_id = NEW.id
               ), 0),
               COALESCE(NEW.finished_at, NOW()),
               COALESCE(NEW.finished_at, NOW()),
               COALESCE(NEW.finished_at, NOW())
          FROM apps a
         WHERE a.id = NEW.app_id
        ON CONFLICT (source, source_id) DO UPDATE SET
            event_payload = EXCLUDED.event_payload,
            error_detail = EXCLUDED.error_detail,
            retry_count = EXCLUDED.retry_count,
            last_failed_at = EXCLUDED.last_failed_at,
            replayed_at = NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: faas_capture_workflow_finished_webhook_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_capture_workflow_finished_webhook_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_account_id uuid;
    recipient_ids uuid[];
    event_finished_at timestamptz;
BEGIN
    IF OLD.status IS NOT DISTINCT FROM NEW.status
       OR OLD.status IN ('succeeded', 'failed', 'dead')
       OR NEW.status NOT IN ('succeeded', 'failed', 'dead') THEN
        RETURN NEW;
    END IF;

    SELECT a.account_id,
           COALESCE(
               array_agg(h.id ORDER BY h.id) FILTER (WHERE h.id IS NOT NULL),
               ARRAY[]::uuid[]
           )
      INTO event_account_id, recipient_ids
      FROM apps a
      LEFT JOIN app_webhooks h
        ON h.app_id = NEW.app_id
       AND h.account_id = a.account_id
       AND h.scope = 'app'
       AND h.enabled
       AND (cardinality(h.event_filter) = 0 OR 'workflow.finished' = ANY(h.event_filter))
     WHERE a.id = NEW.app_id
     GROUP BY a.account_id;

    IF COALESCE(cardinality(recipient_ids), 0) = 0 THEN
        RETURN NEW;
    END IF;

    event_finished_at := COALESCE(NEW.finished_at, clock_timestamp());
    INSERT INTO app_webhook_event_outbox (
        account_id, app_id, event, source_id, payload, recipient_webhook_ids
    ) VALUES (
        event_account_id,
        NEW.app_id,
        'workflow.finished',
        gen_random_uuid(),
        jsonb_build_object(
            'app_id', NEW.app_id::text,
            'run_id', NEW.id::text,
            'workflow_name', NEW.workflow_name,
            'status', NEW.status,
            'finished_at', event_finished_at,
            'resume_count', NEW.resume_count
        ),
        recipient_ids
    ) ON CONFLICT (event, source_id) DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: faas_invocation_headers_own_stage(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_invocation_headers_own_stage(owner_app uuid, pin_headers jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT
    EXISTS(SELECT 1 FROM deployments stage
        WHERE stage.app_id=owner_app AND stage.scope NOT IN ('production','default')
            AND EXISTS(SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(pin_headers)='object' THEN pin_headers ELSE '{}'::jsonb END) pin
                WHERE lower(pin.key)='x-gregale-revision' AND translate(regexp_replace(regexp_replace(lower(pin.value), '[[:space:]{}]', '', 'g'), '^urn:uuid:', ''), '-', '')=replace(stage.id::text,'-','')))
    OR EXISTS(SELECT 1 FROM project_release_sets stage JOIN apps owner
        ON owner.project_id=stage.project_id AND owner.account_id=stage.account_id
        WHERE owner.id=owner_app AND stage.environment_slug NOT IN ('production','default')
            AND EXISTS(SELECT 1 FROM jsonb_each_text(CASE WHEN jsonb_typeof(pin_headers)='object' THEN pin_headers ELSE '{}'::jsonb END) pin
                WHERE lower(pin.key)='x-gregale-release' AND translate(regexp_replace(regexp_replace(lower(pin.value), '[[:space:]{}]', '', 'g'), '^urn:uuid:', ''), '-', '')=replace(stage.id::text,'-','')));
$$;


--
-- Name: faas_retain_dead_letter_environment_ownership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_retain_dead_letter_environment_ownership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' THEN NEW.environment_owned := NEW.environment_owned OR OLD.environment_owned; END IF;
    NEW.environment_owned := NEW.environment_owned OR (NEW.source='invocation' AND (faas_invocation_headers_own_stage(NEW.app_id,NEW.headers)
        OR EXISTS(SELECT 1 FROM invocations i WHERE i.id=NEW.source_id
            AND NOT EXISTS(SELECT 1 FROM production_invocation_work p WHERE p.id=i.id))));
    RETURN NEW;
END;
$$;


--
-- Name: faas_stamp_app_deletion_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faas_stamp_app_deletion_deadline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'deleted' THEN
        NEW.deleted_at := coalesce(NEW.deleted_at, now());
        NEW.delete_grace_until := coalesce(NEW.delete_grace_until, now() + interval '7 days');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fence_immutable_object_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_immutable_object_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.selector IN ('','null') THEN RETURN NEW; END IF;
 -- Match the service's bucket-before-account admission order. The durable
 -- capacity intent owns this lock before any provider page is requested.
 PERFORM 1 FROM object_buckets WHERE id=NEW.bucket_id AND state='ready' FOR NO KEY UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM object_version_references v WHERE v.id::text=NEW.selector AND v.bucket_id=NEW.bucket_id AND v.object_key=NEW.object_key AND v.native_version_id=NEW.target_provider_version_id AND v.native_version_id<>'null') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Immutable deletion requires the exact owned version reference';
 END IF;
 IF EXISTS(SELECT 1 FROM object_storage_capacity_reconciliations c WHERE c.bucket_id=NEW.bucket_id AND c.state IN ('waiting','scanning'))
  OR EXISTS(SELECT 1 FROM object_bucket_versioning v WHERE v.bucket_id=NEW.bucket_id AND v.state<>'ready') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_deletion_fenced',MESSAGE='Inventory and configuration exclude immutable deletion';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_bucket_account_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_bucket_account_cleanup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE current_status text;
BEGIN
 SELECT status INTO current_status FROM accounts WHERE id=NEW.account_id FOR UPDATE;
 IF current_status IS DISTINCT FROM 'active' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_account_cleanup_fenced',MESSAGE='Inactive account cannot reserve new object buckets';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_bucket_pending_writes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_bucket_pending_writes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bid uuid; bucket_state text;
BEGIN
 IF TG_TABLE_NAME='object_storage_write_admissions' THEN
  SELECT state INTO bucket_state FROM object_buckets WHERE id=NEW.bucket_id FOR SHARE;
  IF bucket_state IS DISTINCT FROM 'ready' THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_pending_write_fenced',MESSAGE='Bucket cleanup fences new write admission';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN bid:=OLD.id;
 ELSE
  IF NEW.state NOT IN ('deleting','deleted') THEN RETURN NEW; END IF;
  bid:=NEW.id;
 END IF;
 IF EXISTS(SELECT 1 FROM object_storage_write_admissions w WHERE w.bucket_id=bid AND w.state='pending'
  AND (w.multipart_upload_id IS NULL OR EXISTS(SELECT 1 FROM object_storage_multipart_uploads m
   WHERE m.id=w.multipart_upload_id AND m.state IN ('initiating','active','completing','completing_conditional','aborting')))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_pending_write_fenced',MESSAGE='Settle accepted writes before bucket cleanup';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_capacity_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_capacity_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bid uuid;
BEGIN
 IF TG_TABLE_NAME='object_buckets' THEN
  IF NEW.state<>'deleting' OR OLD.state='deleting' THEN RETURN NEW; END IF;
  bid:=NEW.id;
 ELSE bid:=NEW.bucket_id;
 END IF;
 IF EXISTS(SELECT 1 FROM object_bucket_versioning WHERE bucket_id=bid AND state<>'ready') OR EXISTS (SELECT 1 FROM object_storage_capacity_reconciliations WHERE bucket_id=bid AND state IN ('waiting','scanning')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_capacity_write_fenced',MESSAGE='Object capacity reconciliation fences new writes';
 END IF;
 IF TG_TABLE_NAME='object_storage_key_grants' THEN
  IF NEW.last_write_id IS NULL OR (TG_OP='UPDATE' AND NEW.last_write_id IS NOT DISTINCT FROM OLD.last_write_id) THEN
   NEW.reclaimable:=false; NEW.last_write_id:=NULL;
  ELSE
   IF NOT EXISTS (SELECT 1 FROM object_storage_write_admissions WHERE id=NEW.last_write_id AND bucket_id=bid AND key_hash=NEW.key_hash AND state='pending') THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object grant lacks matching write admission';
   END IF;
   IF TG_OP='UPDATE' THEN NEW.reclaimable:=OLD.reclaimable AND NEW.reclaimable; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bid uuid;
BEGIN
 IF TG_TABLE_NAME='object_buckets' THEN
  IF TG_OP='DELETE' THEN bid:=OLD.id;
  ELSE IF NEW.state=OLD.state OR NEW.state NOT IN ('deleting','deleted') THEN RETURN NEW; END IF; bid:=NEW.id; END IF;
 ELSE
  bid:=NEW.bucket_id;
  IF TG_TABLE_NAME='object_bucket_versioning' THEN IF NEW.state='ready' THEN RETURN NEW; END IF; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM object_deletions d WHERE d.bucket_id=bid AND d.state IN ('prepared','dispatched')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_deletion_fenced',MESSAGE='Unsettled deletion fences mutation and inventory';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_deletion_capture_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_deletion_capture_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bucket_state text;
BEGIN
 -- Fence queries need a fresh snapshot after waiting for the source lock.
 -- Reject old transaction snapshots rather than hiding a committed hold.
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_deletion_admission_isolation',MESSAGE='Deletion admission requires READ COMMITTED';
 END IF;
 SELECT state INTO bucket_state FROM object_buckets WHERE id=NEW.bucket_id FOR UPDATE;
 IF bucket_state IS DISTINCT FROM 'ready' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_deletion_bucket_not_ready',MESSAGE='Bucket cleanup fences deletion admission';
 END IF;
 IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=NEW.bucket_id) THEN
  RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_deletion_capture_fenced',MESSAGE='Checkpoint capture fences new deletion admission';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_lifecycle_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_lifecycle_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE aid uuid; allowed boolean;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.lifecycle_scan_id IS DISTINCT FROM OLD.lifecycle_scan_id OR NEW.lifecycle_binding<>OLD.lifecycle_binding) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Lifecycle deletion identity is immutable';
 END IF;
 IF NEW.lifecycle_scan_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NOT (OLD.state='prepared' AND NEW.state='dispatched') THEN RETURN NEW; END IF;
 -- Both the API store and this defensive trigger follow bucket-before-account
 -- lock order. Re-read the lease and revision after acquiring those locks.
 SELECT account_id INTO aid FROM object_buckets WHERE id=NEW.bucket_id AND state='ready' FOR NO KEY UPDATE;
 IF aid IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Lifecycle deletion requires a ready owned bucket'; END IF;
 PERFORM 1 FROM accounts WHERE id=aid FOR UPDATE;
 SELECT EXISTS(
  SELECT 1 FROM object_lifecycle_scans s JOIN object_bucket_lifecycle p ON p.bucket_id=s.bucket_id,
   LATERAL jsonb_array_elements(s.rules) r
  WHERE s.id=NEW.lifecycle_scan_id AND s.bucket_id=NEW.bucket_id AND s.revision=p.revision AND s.state='scanning'
   AND s.lease_token=NEW.lifecycle_binding->>'scan_token' AND s.lease_until>clock_timestamp()
   AND r->>'id'=NEW.lifecycle_binding->>'rule_id' AND r->>'status'='Enabled'
   AND left(NEW.object_key,char_length(coalesce(r->'filter'->>'prefix','')))=coalesce(r->'filter'->>'prefix','')
   AND ((NEW.lifecycle_binding->>'kind'='current' AND (r->'expiration' ? 'days' OR r->'expiration' ? 'date'))
    OR (NEW.lifecycle_binding->>'kind'='noncurrent' AND r ? 'noncurrent_version_expiration')
    OR (NEW.lifecycle_binding->>'kind'='expired_marker' AND (r->'expiration' ? 'days' OR r->'expiration' ? 'date' OR r->'expiration'->>'expired_object_delete_marker'='true')))
 ) INTO allowed;
 IF NOT allowed OR (NEW.lifecycle_binding->>'expected_last_modified')::timestamptz>clock_timestamp()
  OR (NEW.selector='null' AND NEW.lifecycle_binding->>'expected_provider_version_id'<>'null')
  OR (NEW.selector NOT IN ('','null') AND NEW.lifecycle_binding->>'expected_provider_version_id'<>coalesce(to_jsonb(NEW)->>'target_provider_version_id','')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_lifecycle_deletion_fenced',MESSAGE='A live matching lifecycle scan and target are required before dispatch';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_lifecycle_multipart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_lifecycle_multipart() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE aid uuid; allowed boolean;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.lifecycle_scan_id IS NOT NULL OR NEW.lifecycle_binding<>'{}' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart lifecycle admission requires an existing active upload';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.lifecycle_scan_id IS NOT NULL THEN
  IF NEW.lifecycle_scan_id IS DISTINCT FROM OLD.lifecycle_scan_id OR NEW.lifecycle_binding<>OLD.lifecycle_binding
   OR NEW.id<>OLD.id OR NEW.account_id<>OLD.account_id OR NEW.app_id<>OLD.app_id OR NEW.bucket_id<>OLD.bucket_id
   OR NEW.object_key<>OLD.object_key OR NEW.provider_upload_id<>OLD.provider_upload_id OR NEW.created_at<>OLD.created_at THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart lifecycle admission identity is immutable';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.lifecycle_scan_id IS NULL THEN RETURN NEW; END IF;
 IF OLD.state<>'active' OR NEW.state<>'aborting' OR NEW.lease_until IS NOT NULL
  OR OLD.lease_until>clock_timestamp() OR NEW.provider_upload_id<>OLD.provider_upload_id OR NEW.created_at<>OLD.created_at
  OR NEW.id<>OLD.id OR NEW.account_id<>OLD.account_id OR NEW.app_id<>OLD.app_id OR NEW.bucket_id<>OLD.bucket_id OR NEW.object_key<>OLD.object_key
  OR (NEW.lifecycle_binding->>'expected_created_at')::timestamptz<>OLD.created_at THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart lifecycle admission requires the unchanged active upload';
 END IF;
 -- The store takes these locks before the upload row. Direct SQL callers must
 -- follow the same bucket/account/upload ordering to avoid deadlocks.
 SELECT account_id INTO aid FROM object_buckets WHERE id=NEW.bucket_id AND account_id=NEW.account_id AND app_id=NEW.app_id AND state='ready' FOR NO KEY UPDATE;
 IF aid IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart lifecycle admission requires an owned ready bucket'; END IF;
 PERFORM 1 FROM accounts WHERE id=aid FOR UPDATE;
 SELECT EXISTS(
  SELECT 1 FROM object_lifecycle_scans s JOIN object_bucket_lifecycle p ON p.bucket_id=s.bucket_id,
   LATERAL jsonb_array_elements(s.rules) r
  WHERE s.id=NEW.lifecycle_scan_id AND s.bucket_id=NEW.bucket_id AND s.revision=p.revision AND s.state='scanning' AND s.phase='multipart'
   AND s.created_at>=NEW.created_at AND (s.last_upload_id IS NULL OR NEW.id>s.last_upload_id)
   AND s.lease_token=NEW.lifecycle_binding->>'scan_token' AND s.lease_until>clock_timestamp()
   AND r->>'id'=NEW.lifecycle_binding->>'rule_id' AND r->>'status'='Enabled'
   AND left(NEW.object_key,char_length(coalesce(r->'filter'->>'prefix','')))=coalesce(r->'filter'->>'prefix','')
   AND coalesce(r->'filter'->'tags','{}')='{}' AND (r->>'abort_incomplete_multipart_days')::bigint>0
   -- Compare elapsed UTC days instead of constructing an out-of-range date
   -- for an otherwise valid large days value.
   AND (clock_timestamp() AT TIME ZONE 'UTC')::date-(NEW.created_at AT TIME ZONE 'UTC')::date > (r->>'abort_incomplete_multipart_days')::bigint
 ) INTO allowed;
 IF NOT allowed THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_lifecycle_multipart_fenced',MESSAGE='A live matching lifecycle scan and aged upload are required before admission';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_lifecycle_protection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_lifecycle_protection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE aid uuid; required boolean;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.protection_verified OR NEW.deletion_verified OR NEW.protection_required AND NEW.state<>'prepared' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protected lifecycle intents must begin prepared and unverified';
  END IF;
  SELECT account_id INTO aid FROM object_buckets WHERE id=NEW.bucket_id;
  PERFORM 1 FROM accounts WHERE id=aid FOR UPDATE;
  PERFORM 1 FROM object_buckets WHERE id=NEW.bucket_id FOR NO KEY UPDATE;
  SELECT NEW.lifecycle_scan_id IS NOT NULL AND NEW.selector<>'' AND EXISTS(
   SELECT 1 FROM object_bucket_object_lock l WHERE l.bucket_id=NEW.bucket_id
    AND (l.enabled_required OR l.native_enabled_observed OR l.observed_snapshot->>'enabled'='true')
  ) INTO required;
  IF NEW.protection_required IS DISTINCT FROM required OR required AND jsonb_typeof(NEW.lifecycle_binding->'expected_delete_marker') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protected lifecycle deletion requires a frozen target classification';
  END IF;
 ELSE
  IF NEW.protection_required<>OLD.protection_required OR OLD.protection_verified AND NOT NEW.protection_verified OR OLD.deletion_verified AND NOT NEW.deletion_verified THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Lifecycle protection evidence is immutable';
  END IF;
  IF NOT OLD.protection_verified AND NEW.protection_verified AND NOT (NEW.protection_required AND OLD.state='prepared' AND NEW.state='dispatched') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Protection proof must accompany initial dispatch';
  END IF;
  IF NOT OLD.deletion_verified AND NEW.deletion_verified AND NOT (OLD.state='dispatched' AND NEW.state='completed') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Absence proof must accompany completion';
  END IF;
  IF NEW.last_error_code='object_protected' AND NOT (OLD.state='prepared' AND NEW.state='failed') AND OLD.last_error_code<>'object_protected' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A dispatched uncertain attempt cannot be dismissed as protected';
  END IF;
  IF OLD.state='prepared' AND NEW.state='dispatched' AND NEW.protection_required AND NOT NEW.protection_verified THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Fresh native policy proof is required before lifecycle dispatch';
  END IF;
 END IF;
 IF NEW.protection_required AND NEW.state='completed' AND (
  NOT NEW.deletion_verified OR jsonb_typeof(NEW.lifecycle_binding->'expected_delete_marker') IS DISTINCT FROM 'boolean'
  OR NEW.delete_marker::text IS DISTINCT FROM NEW.lifecycle_binding->>'expected_delete_marker'
  OR NEW.provider_version_id IS DISTINCT FROM NEW.lifecycle_binding->>'expected_provider_version_id') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Exact lifecycle target absence proof is required before completion';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_lock_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_lock_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bid uuid;
BEGIN
 IF TG_TABLE_NAME='object_buckets' THEN
  IF NEW.state<>'deleting' OR OLD.state='deleting' THEN RETURN NEW; END IF;
  bid:=NEW.id;
 ELSE
  IF TG_TABLE_NAME='object_upload_completions' THEN
   IF NEW.status='rejected' THEN RETURN NEW; END IF;
  END IF;
  bid:=NEW.bucket_id;
  PERFORM 1 FROM object_buckets WHERE id=bid FOR SHARE;
 END IF;
 IF TG_TABLE_NAME='object_storage_write_admissions' THEN
  -- An already accepted variable-size session can acquire its completion
  -- admission while the preceding native default is still in effect.
  IF NEW.kind='multipart' AND EXISTS(SELECT 1 FROM object_storage_multipart_uploads m
   WHERE m.id=NEW.multipart_upload_id AND m.bucket_id=bid AND m.state NOT IN ('completed','aborted')) THEN RETURN NEW; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM object_bucket_object_lock WHERE bucket_id=bid AND state<>'ready') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_lock_admission_fenced',MESSAGE='Unresolved Object Lock configuration fences new writes and bucket deletion';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_lock_suspension(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_lock_suspension() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM object_buckets WHERE id=NEW.bucket_id FOR NO KEY UPDATE;
 IF NEW.desired_status='Suspended' AND EXISTS(SELECT 1 FROM object_bucket_object_lock WHERE bucket_id=NEW.bucket_id AND (enabled_required OR state<>'ready')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Object Lock permanently requires Enabled versioning';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_multipart_completion_conditions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_multipart_completion_conditions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state<>'active' AND (NEW.completion_if_match IS DISTINCT FROM OLD.completion_if_match
        OR NEW.completion_if_none_match IS DISTINCT FROM OLD.completion_if_none_match) THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart completion conditions are immutable';
    END IF;
    IF OLD.completion_error_code<>'' AND NEW.completion_error_code IS DISTINCT FROM OLD.completion_error_code THEN
        RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Multipart completion failure is immutable';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fence_object_native_version_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_native_version_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE mode text; bid uuid;
BEGIN
 bid:=NEW.bucket_id;
 IF EXISTS(SELECT 1 FROM object_bucket_versioning WHERE bucket_id=bid AND state<>'ready') OR EXISTS(SELECT 1 FROM object_storage_capacity_reconciliations WHERE bucket_id=bid AND state IN ('waiting','scanning')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Capacity inventory fences new writes';
 END IF;
 SELECT inventory_scope INTO mode FROM object_storage_bucket_usage WHERE bucket_id=bid;
 IF mode='all_versions' THEN
  IF TG_TABLE_NAME='object_storage_key_grants' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Retained versions require per-attempt admission';
  ELSIF NOT NEW.native_version THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Retained versions require per-attempt admission';
  END IF;
 ELSE
  IF TG_TABLE_NAME='object_storage_write_admissions' THEN
   IF NEW.native_version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Version inventory is required before version admission'; END IF;
  END IF;
  IF (EXISTS(SELECT 1 FROM object_upload_completions WHERE bucket_id=bid AND recovery_versions_observed) OR EXISTS(SELECT 1 FROM object_version_references WHERE bucket_id=bid AND versions_observed) OR EXISTS(SELECT 1 FROM object_storage_multipart_uploads WHERE bucket_id=bid AND completion_versions_observed) OR EXISTS(SELECT 1 FROM object_bucket_versioning WHERE bucket_id=bid AND versions_required)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Version inventory is required before new writes';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_protection_capture_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_protection_capture_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bucket_state text;
BEGIN
 -- Fence queries need a fresh snapshot after waiting for the source lock.
 -- Reject old transaction snapshots rather than hiding a committed hold.
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_protection_admission_isolation',MESSAGE='Protection admission requires READ COMMITTED';
 END IF;
 SELECT state INTO bucket_state FROM object_buckets WHERE id=NEW.bucket_id FOR UPDATE;
 IF bucket_state IS DISTINCT FROM 'ready' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_protection_bucket_not_ready',MESSAGE='Bucket cleanup fences protection admission';
 END IF;
 IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=NEW.bucket_id) THEN
  RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_protection_capture_fenced',MESSAGE='Checkpoint capture fences new protection admission';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_upload_capture_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_upload_capture_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bucket_state text;
BEGIN
 -- Fence queries need a fresh snapshot after waiting for the source lock.
 -- Reject old transaction snapshots rather than hiding a committed hold.
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_admission_isolation',MESSAGE='Upload admission requires READ COMMITTED';
 END IF;
 -- Match the application admission order: account before source bucket.
 -- An older replica's INSERT must not invert the account FK/row locks.
 PERFORM id FROM accounts WHERE id=NEW.account_id FOR UPDATE;
 SELECT state INTO bucket_state FROM object_buckets
 WHERE id=NEW.bucket_id AND account_id=NEW.account_id AND app_id=NEW.app_id FOR UPDATE;
 IF bucket_state IS DISTINCT FROM 'ready' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_bucket_not_ready',MESSAGE='Bucket cleanup fences upload admission';
 END IF;
 IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=NEW.bucket_id) THEN
  RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_upload_capture_fenced',MESSAGE='Checkpoint capture fences new upload admission';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_version_protection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_version_protection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bid uuid;
BEGIN
 IF TG_TABLE_NAME='object_buckets' THEN
  IF NEW.state<>'deleting' OR OLD.state='deleting' THEN RETURN NEW; END IF;
  bid:=NEW.id;
 ELSE
  bid:=NEW.bucket_id;
  IF TG_OP='UPDATE' AND TG_TABLE_NAME IN ('object_bucket_object_lock','object_bucket_encryption','object_bucket_versioning') THEN
   IF NEW.revision=OLD.revision AND NOT (NOT OLD.dispatched AND NEW.dispatched) THEN RETURN NEW; END IF;
  END IF;
  PERFORM 1 FROM object_buckets WHERE id=bid FOR SHARE;
 END IF;
 IF EXISTS(SELECT 1 FROM object_version_protection WHERE bucket_id=bid AND state IN ('waiting','applying')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_version_protection_fenced',MESSAGE='Unsettled version protection fences writes, deletion and configuration';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_version_reclamation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_version_reclamation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE versioned boolean;
BEGIN
 versioned:=OLD.inventory_scope='all_versions' OR (EXISTS(SELECT 1 FROM object_upload_completions WHERE bucket_id=NEW.bucket_id AND recovery_versions_observed) OR EXISTS(SELECT 1 FROM object_version_references WHERE bucket_id=NEW.bucket_id AND versions_observed) OR EXISTS(SELECT 1 FROM object_storage_multipart_uploads WHERE bucket_id=NEW.bucket_id AND completion_versions_observed) OR EXISTS(SELECT 1 FROM object_bucket_versioning WHERE bucket_id=NEW.bucket_id AND versions_required));
 IF OLD.inventory_scope='all_versions' AND NEW.inventory_scope<>'all_versions' THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Version accounting cannot revert to current-object inventory';
 END IF;
 IF versioned AND EXISTS(SELECT 1 FROM object_storage_capacity_reconciliations WHERE bucket_id=NEW.bucket_id AND state='scanning')
  AND NOT EXISTS(SELECT 1 FROM object_storage_capacity_reconciliations WHERE bucket_id=NEW.bucket_id AND state='scanning' AND inventory_scope='all_versions' AND inventory_verified AND lease_until>now()) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_version_reclamation_fenced',MESSAGE='Retained versions require verified version inventory';
 END IF;
 IF versioned AND (NEW.inventory_scope IS DISTINCT FROM OLD.inventory_scope
  OR NEW.baseline_bytes IS DISTINCT FROM OLD.baseline_bytes OR NEW.baseline_keys IS DISTINCT FROM OLD.baseline_keys
  OR NEW.observed_bytes IS DISTINCT FROM OLD.observed_bytes OR NEW.observed_keys IS DISTINCT FROM OLD.observed_keys
  OR NEW.observed_at IS DISTINCT FROM OLD.observed_at)
  AND NOT EXISTS(SELECT 1 FROM object_storage_capacity_reconciliations WHERE bucket_id=NEW.bucket_id AND state='scanning' AND inventory_scope='all_versions' AND inventory_verified AND lease_until>now()) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Retained versions require verified version observations';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_versioning_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_versioning_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bid uuid; jid uuid;
BEGIN
 IF TG_TABLE_NAME='object_storage_capacity_reconciliations' THEN
  IF NEW.state<>'scanning' THEN RETURN NEW; END IF;
  bid:=NEW.bucket_id;jid:=NEW.id;
 ELSE bid:=NEW.bucket_id;
 END IF;
 IF EXISTS(SELECT 1 FROM object_bucket_versioning v WHERE v.bucket_id=bid AND v.state<>'ready'
  AND (v.state<>'inventory' OR (TG_TABLE_NAME='object_storage_capacity_reconciliations' AND v.capacity_job_id IS DISTINCT FROM jid))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Configuration transition fences unrelated inventory';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_object_write_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_object_write_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE owner uuid; own_write uuid;
BEGIN
 SELECT account_id INTO owner FROM object_buckets WHERE id=NEW.bucket_id;
 PERFORM 1 FROM accounts WHERE id=owner FOR UPDATE;
 PERFORM 1 FROM object_buckets WHERE id=NEW.bucket_id FOR SHARE;
 IF TG_TABLE_NAME='object_storage_write_admissions' THEN
  own_write:=NEW.id;
 ELSE
  own_write:=NEW.last_write_id;
  IF TG_OP='UPDATE' AND NEW.last_write_id IS NOT DISTINCT FROM OLD.last_write_id THEN own_write:=NULL; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM object_storage_write_admissions w
  WHERE w.bucket_id=NEW.bucket_id AND w.key_hash=NEW.key_hash AND w.state='pending'
  AND w.id IS DISTINCT FROM own_write
  AND (w.multipart_upload_id IS NULL OR EXISTS(SELECT 1 FROM object_storage_multipart_uploads m
   WHERE m.id=w.multipart_upload_id AND m.state IN ('initiating','active','completing','completing_conditional','aborting')))) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_write_key_fenced',MESSAGE='Settle the pending write before replacing its proof';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: fence_untracked_object_lock_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fence_untracked_object_lock_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_TABLE_NAME='object_storage_key_grants' THEN
  IF NEW.last_write_id IS NOT NULL THEN RETURN NEW; END IF;
 ELSE
  IF NEW.kind<>'proxy' OR NEW.route_receipt THEN RETURN NEW; END IF;
 END IF;
 PERFORM 1 FROM accounts a JOIN object_buckets b ON b.account_id=a.id WHERE b.id=NEW.bucket_id FOR UPDATE OF a;
 PERFORM 1 FROM object_buckets WHERE id=NEW.bucket_id FOR NO KEY UPDATE;
 IF EXISTS(SELECT 1 FROM object_bucket_object_lock WHERE bucket_id=NEW.bucket_id AND (enabled_required OR native_enabled_observed OR state<>'ready')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_lock_admission_fenced',MESSAGE='Object Lock requires a tracked protection-aware write';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: forbid_runtime_upgrade_native_public_startup_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_runtime_upgrade_native_public_startup_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 RAISE EXCEPTION 'native startup provenance cannot be truncated' USING ERRCODE='23514';
END $$;


--
-- Name: github_webhook_secrets_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.github_webhook_secrets_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify(
        'github_webhook_secret_changed',
        jsonb_build_object('installation_id', NEW.installation_id)::text
    );
    RETURN NEW;
END;
$$;


--
-- Name: guard_account_managed_postgres_databases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_account_managed_postgres_databases() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'deleted_pending' AND EXISTS (
        SELECT 1 FROM managed_postgres_databases WHERE account_id = NEW.id AND state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'account has managed postgres databases'
            USING ERRCODE = '23514', CONSTRAINT = 'account_has_managed_postgres_databases';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_app_managed_postgres_bindings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_app_managed_postgres_bindings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'deleted' AND EXISTS (
        SELECT 1 FROM managed_postgres_bindings WHERE app_id = NEW.id AND state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'app has managed postgres bindings'
            USING ERRCODE = '23514', CONSTRAINT = 'app_has_managed_postgres_bindings';
    END IF;
    RETURN NEW;
END;
$$;


