    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_bound_multipart_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_bound_multipart_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.multipart_upload_id IS NOT NULL OR NEW.multipart_upload_id IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_mutation_immutable',MESSAGE='Original multipart receipts are immutable';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.multipart_upload_id IS NOT NULL AND EXISTS(SELECT 1 FROM object_storage_multipart_uploads WHERE id=OLD.multipart_upload_id AND state NOT IN ('completed','aborted')) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_mutation_unsettled',MESSAGE='Settle the original session before removing its provider receipt';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW.multipart_upload_id IS NOT NULL THEN
  IF current_setting('transaction_isolation')<>'read committed' THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_mutation_isolation',MESSAGE='Multipart receipt binding requires READ COMMITTED';
  END IF;
  SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.multipart_upload_id;
  PERFORM id FROM accounts WHERE id=u.account_id FOR UPDATE;
  PERFORM id FROM object_buckets WHERE id=u.bucket_id FOR UPDATE;
  SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.multipart_upload_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=u.bucket_id) THEN
   RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_multipart_capture_fenced',MESSAGE='Capture fences new receipt binding';
  END IF;
  IF u.id IS NULL OR u.bucket_id<>NEW.bucket_id OR u.state<>'initiating' OR u.provider_upload_id<>'' OR NEW.kind<>'request' OR NOT EXISTS(SELECT 1 FROM object_buckets WHERE id=u.bucket_id AND account_id=u.account_id AND app_id=u.app_id AND backend_id=NEW.backend_id AND backend_fingerprint=NEW.backend_fingerprint AND physical_name=NEW.physical_name AND state='ready') THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_mutation_original',MESSAGE='Bind only the original reserved session placement';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_bound_upload_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_bound_upload_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_upload_completions%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF OLD.upload_id IS NOT NULL OR NEW.upload_id IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_mutation_immutable',MESSAGE='Original upload receipts are immutable';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.upload_id IS NOT NULL AND EXISTS(SELECT 1 FROM object_upload_completions WHERE id=OLD.upload_id AND (write_phase<>'settled' OR status NOT IN ('completed','failed'))) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_mutation_unsettled',MESSAGE='Settle the original upload before removing its provider receipt';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW.upload_id IS NOT NULL THEN
  IF current_setting('transaction_isolation')<>'read committed' THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_mutation_isolation',MESSAGE='Upload receipt binding requires READ COMMITTED';
  END IF;
  SELECT * INTO u FROM object_upload_completions WHERE id=NEW.upload_id;
  PERFORM id FROM accounts WHERE id=u.account_id FOR UPDATE;
  PERFORM id FROM object_buckets WHERE id=u.bucket_id FOR UPDATE;
  SELECT * INTO u FROM object_upload_completions WHERE id=NEW.upload_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=u.bucket_id) THEN
   RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_upload_capture_fenced',MESSAGE='Capture fences new receipt binding';
  END IF;
  IF u.id IS NULL OR u.bucket_id<>NEW.bucket_id OR u.status<>'pending' OR u.write_phase<>'prepared' OR NEW.kind<>'request' OR NOT EXISTS(SELECT 1 FROM object_buckets WHERE id=u.bucket_id AND backend_id=NEW.backend_id AND backend_fingerprint=NEW.backend_fingerprint AND physical_name=NEW.physical_name AND state='ready') THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_upload_mutation_original',MESSAGE='Bind only the original prepared upload placement';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_checked_rollback_traffic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_checked_rollback_traffic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.status='live' AND NEW.traffic_percent>(CASE WHEN OLD.status='live' THEN OLD.traffic_percent ELSE 0 END)
 AND EXISTS(SELECT 1 FROM deployment_rollback_operations r WHERE r.target_deployment_id=NEW.id AND r.status NOT IN ('complete','failed')
   AND (r.status NOT IN ('ready','blocked') OR r.id::text IS DISTINCT FROM current_setting('faas.checked_rollback_request',true))) THEN
  RAISE EXCEPTION 'checked rollback operation required' USING ERRCODE='23514',CONSTRAINT='checked_rollback_required';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_clone_configuration_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_clone_configuration_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    before_row jsonb := CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
    after_row jsonb := CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) ELSE '{}'::jsonb END;
    before_id uuid := nullif(before_row ->> TG_ARGV[1], '')::uuid;
    after_id uuid := nullif(after_row ->> TG_ARGV[1], '')::uuid;
    project uuid;
BEGIN
    -- Protection intents are frozen customer configuration. Only the original
    -- journal's operational progress may change during a capture hold.
    IF TG_TABLE_NAME = 'object_version_protection' AND TG_OP = 'UPDATE' THEN
        IF (before_row - ARRAY['state','lease_token','lease_until','retry_at','dispatched','last_error_code','updated_at','event_hold_baseline'])
            IS DISTINCT FROM (after_row - ARRAY['state','lease_token','lease_until','retry_at','dispatched','last_error_code','updated_at','event_hold_baseline'])
            OR ((before_row ->> 'dispatched')::boolean AND NOT (after_row ->> 'dispatched')::boolean)
            OR ((before_row ->> 'state') IN ('ready','failed') AND before_row IS DISTINCT FROM after_row)
            OR (nullif(before_row -> 'event_hold_baseline', 'null'::jsonb) IS NOT NULL AND nullif(before_row -> 'event_hold_baseline', 'null'::jsonb) IS DISTINCT FROM nullif(after_row -> 'event_hold_baseline', 'null'::jsonb))
            OR ((before_row ->> 'dispatched')::boolean AND nullif(before_row -> 'event_hold_baseline', 'null'::jsonb) IS DISTINCT FROM nullif(after_row -> 'event_hold_baseline', 'null'::jsonb))
            OR ((after_row ->> 'state') = 'failed' AND (after_row ->> 'last_error_code') NOT IN ('preparation_failed','provider_rejected'))
            OR ((after_row ->> 'state') = 'failed' AND (after_row ->> 'dispatched')::boolean AND (after_row ->> 'last_error_code') <> 'provider_rejected') THEN
            RAISE EXCEPTION 'original protection intent and settled evidence are immutable'
                USING ERRCODE = '23514', CONSTRAINT = 'object_protection_original_immutable';
        END IF;
        RETURN NEW;
    END IF;
    PERFORM generation FROM project_environment_clone_configuration_clock WHERE singleton FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'configuration synchronization clock is missing'
            USING ERRCODE = '55000', CONSTRAINT = 'clone_configuration_guard_missing';
    END IF;
    FOR project IN
        SELECT DISTINCT p.project_id FROM (
            SELECT before_id AS project_id WHERE TG_ARGV[0] = 'project'
            UNION ALL SELECT after_id WHERE TG_ARGV[0] = 'project'
            UNION ALL SELECT a.project_id FROM apps a
                WHERE TG_ARGV[0] = 'app' AND a.id IN (before_id, after_id)
            UNION ALL SELECT a.project_id FROM deployments d JOIN apps a ON a.id = d.app_id
                WHERE TG_ARGV[0] = 'deployment' AND d.id IN (before_id, after_id)
            UNION ALL SELECT a.project_id FROM object_buckets b JOIN apps a ON a.id = b.app_id
                WHERE TG_ARGV[0] = 'bucket' AND b.id IN (before_id, after_id)
            UNION ALL SELECT a.project_id FROM managed_postgres_bindings b JOIN apps a ON a.id = b.app_id
                WHERE TG_ARGV[0] = 'database' AND b.database_id IN (before_id, after_id)
        ) p WHERE p.project_id IS NOT NULL ORDER BY p.project_id
    LOOP
        PERFORM assert_clone_configuration_mutable(project);
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_deployment_layer_artifacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_deployment_layer_artifacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE key text;
BEGIN
    IF TG_OP = 'INSERT' OR NEW.rootfs_key IS DISTINCT FROM OLD.rootfs_key OR
       (NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('pending', 'building', 'imaging', 'snapshotting', 'live')) THEN
        FOR key IN SELECT keys.key FROM (
            SELECT NEW.rootfs_key AS key
            UNION SELECT storage_key FROM deployment_sidecar_layers WHERE deployment_id = NEW.id
        ) keys WHERE coalesce(keys.key, '') <> '' ORDER BY keys.key LOOP
            PERFORM require_retained_layer_artifact(key);
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_durable_queue_consumer_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_durable_queue_consumer_deletion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.queue_binding_id IS NOT NULL AND EXISTS (SELECT 1 FROM apps WHERE id=OLD.app_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_durable_identity',
      MESSAGE='private queue consumer identity requires explicit recovery';
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: guard_environment_external_field_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_external_field_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src active_environment_git_sources%ROWTYPE;
BEGIN
 IF NEW.resource<>'environment' AND NOT EXISTS(SELECT 1 FROM apps a JOIN project_environments e ON e.account_id=a.account_id AND e.project_id=a.project_id
  WHERE e.id=NEW.environment_id AND NEW.resource='app/'||a.id::text AND a.status<>'deleted') THEN
  RAISE EXCEPTION 'External field ownership must target the scoped app' USING ERRCODE='23514';
 END IF;
 SELECT * INTO src FROM active_environment_git_sources WHERE environment_id=NEW.environment_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM environment_managed_fields f LEFT JOIN environment_gitops_resources r ON r.source_id=f.source_id AND r.logical_name=f.resource
  WHERE f.source_id=src.id AND (NEW.resource='environment' AND f.resource='environment' OR NEW.resource='app/'||r.app_id::text)
   AND (f.field_path=NEW.field_path OR starts_with(NEW.field_path,'variables/') AND f.field_path='secret_refs/'||substring(NEW.field_path FROM 11))) THEN
  RAISE EXCEPTION 'Field already has a Git owner' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_environment_git_field_foreign_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_git_field_foreign_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE app uuid;
BEGIN
 IF NEW.manager_kind<>'git' THEN RETURN NEW; END IF;
 PERFORM id FROM active_environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
 SELECT app_id INTO app FROM environment_gitops_resources WHERE source_id=NEW.source_id AND logical_name=NEW.resource;
 IF EXISTS(SELECT 1 FROM environment_external_field_owners f WHERE f.environment_id=NEW.environment_id
  AND (NEW.resource='environment' AND f.resource='environment' OR f.resource='app/'||app::text)
  AND (f.field_path=NEW.field_path OR starts_with(NEW.field_path,'secret_refs/') AND f.field_path='variables/'||substring(NEW.field_path FROM 13))) THEN
  RAISE EXCEPTION 'Field already has an external owner' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_environment_git_revision_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_git_revision_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  src environment_git_sources%ROWTYPE;
  rev environment_desired_revisions%ROWTYPE;
  proof jsonb;
  policy jsonb;
  checked timestamptz;
  policy_checked timestamptz;
  merged timestamptz;
  observed timestamptz := clock_timestamp();
  required_reviews integer;
  review jsonb;
  review_ids bigint[] := '{}';
  reviewer_ids bigint[] := '{}';
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM environment_git_sources WHERE id=OLD.source_id) THEN
      RAISE EXCEPTION 'Git approval provenance is immutable' USING ERRCODE='23514';
    END IF;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'Git approval provenance is immutable' USING ERRCODE='23514';
  END IF;
  SELECT * INTO STRICT src FROM environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
  SELECT * INTO STRICT rev FROM environment_desired_revisions WHERE source_id=src.id AND id=NEW.revision_id;
  proof := NEW.evidence;
  policy := proof->'policy';
  checked := (proof->>'checked_at')::timestamptz;
  policy_checked := (policy->>'checked_at')::timestamptz;
  merged := (proof->>'merged_at')::timestamptz;
  required_reviews := (policy->>'required_review_count')::integer;
  IF src.approval_policy <> 'protected_branch' OR src.suspended
    OR proof->>'reviewed_definition_digest' IS DISTINCT FROM NEW.definition_digest
    OR NEW.definition_digest <> rev.definition_digest OR rev.commit_sha !~ '^[a-f0-9]{40}$'
    OR NEW.approved_generation NOT IN (src.generation, src.generation+1)
    OR proof->>'qualified' IS DISTINCT FROM 'true' OR coalesce(proof->>'reason','') <> ''
    OR proof->>'profile' IS DISTINCT FROM 'reviewed_merge/v1'
    OR policy->>'qualified' IS DISTINCT FROM 'true' OR coalesce(policy->>'reason','') <> ''
    OR policy->>'profile' IS DISTINCT FROM 'classic_reviewed_branch/v1'
    OR policy->>'installation_id' IS DISTINCT FROM src.installation_id::text
    OR policy->>'repository_id' IS DISTINCT FROM src.repository_id::text
    OR policy->>'repository' IS DISTINCT FROM src.repository
    OR src.source_ref NOT LIKE 'refs/heads/%'
    OR policy->>'branch' IS DISTINCT FROM substring(src.source_ref FROM 12)
    OR policy->>'commit_sha' IS DISTINCT FROM rev.commit_sha
    OR coalesce(policy->>'policy_digest','') !~ '^[a-f0-9]{64}$'
    OR coalesce(proof->>'head_sha','') !~ '^[a-f0-9]{40}$'
    OR coalesce((proof->>'pull_request_id')::bigint,0) <= 0
    OR coalesce((proof->>'pull_request_number')::bigint,0) <= 0
    OR coalesce((proof->>'author_id')::bigint,0) <= 0
    OR checked IS NULL OR policy_checked IS NULL OR merged IS NULL
    OR checked > observed OR policy_checked > checked OR merged > checked
    OR policy_checked < observed-interval '1 minute'
    OR coalesce(required_reviews,0) <= 0
    OR jsonb_typeof(proof->'reviews') IS DISTINCT FROM 'array'
    OR NOT EXISTS (SELECT 1 FROM environment_git_source_polls WHERE source_id=src.id
      AND lease_token=NEW.poll_lease_token AND lease_until > observed)
  THEN
    RAISE EXCEPTION 'Git approval evidence does not qualify for this source' USING ERRCODE='23514';
  END IF;
  FOR review IN SELECT value FROM jsonb_array_elements(proof->'reviews') LOOP
    IF coalesce((review->>'id')::bigint,0) <= 0 OR coalesce((review->>'reviewer_id')::bigint,0) <= 0
      OR (review->>'reviewer_id')::bigint = (proof->>'author_id')::bigint
      OR coalesce(review->>'reviewer','') = '' OR review->>'head_sha' IS DISTINCT FROM proof->>'head_sha'
      OR (review->>'submitted_at')::timestamptz IS NULL OR (review->>'submitted_at')::timestamptz >= merged
      OR (review->>'id')::bigint = ANY(review_ids) OR (review->>'reviewer_id')::bigint = ANY(reviewer_ids)
    THEN
      RAISE EXCEPTION 'Git approval review does not qualify' USING ERRCODE='23514';
    END IF;
    review_ids := array_append(review_ids,(review->>'id')::bigint);
    reviewer_ids := array_append(reviewer_ids,(review->>'reviewer_id')::bigint);
  END LOOP;
  IF cardinality(review_ids) < required_reviews THEN
    RAISE EXCEPTION 'Git approval reviews are insufficient' USING ERRCODE='23514';
  END IF;
  NEW.recorded_at := observed;
  RETURN NEW;
END;
$_$;


--
-- Name: guard_environment_git_source_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_git_source_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.detached AND NOT NEW.detached THEN
  RAISE EXCEPTION 'Retired Git bindings cannot be reactivated' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $$;


--
-- Name: guard_environment_gitops_queue_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_gitops_queue_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.source_id IS DISTINCT FROM OLD.source_id OR NEW.resource IS DISTINCT FROM OLD.resource
  OR NEW.field_path IS DISTINCT FROM OLD.field_path OR (OLD.binding_id IS NOT NULL AND NEW.binding_id IS NOT NULL AND NEW.binding_id IS DISTINCT FROM OLD.binding_id)) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_queue_identity',MESSAGE='Git queue identity requires reviewed recovery';
 END IF;
 IF NEW.binding_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM queue_bindings b JOIN active_environment_git_sources s ON s.id=NEW.source_id
   JOIN environment_gitops_resources r ON r.source_id=s.id AND r.logical_name=NEW.resource
  WHERE b.id=NEW.binding_id AND b.app_id=r.app_id AND b.account_id=s.account_id
   AND b.environment_id=s.environment_id AND NEW.field_path='queue_bindings/'||b.name
   AND (b.retired_at IS NULL OR environment_gitops_queue_recovery_declared(s.id,b.id)) FOR SHARE OF b) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_queue_identity',MESSAGE='Git queue ownership requires its original scoped binding and reviewed recovery';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_environment_gitops_queue_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_gitops_queue_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 binding queue_bindings%ROWTYPE;
 src environment_git_sources%ROWTYPE;
 resource_name text;
 paths text[];
 controller boolean;
BEGIN
 IF TG_TABLE_NAME='queue_bindings' THEN
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'updated_at'-'created_at')=(to_jsonb(OLD)-'updated_at'-'created_at') THEN RETURN NEW; END IF;
  IF TG_OP='DELETE' THEN binding:=OLD; ELSE binding:=NEW; END IF;
  paths:=ARRAY['queue_bindings/'||binding.name];
  IF TG_OP='UPDATE' THEN paths:=paths||ARRAY['queue_bindings/'||OLD.name]; END IF;
 ELSE
  IF TG_OP='UPDATE' AND OLD.queue_binding_id IS NOT NULL AND NEW.id IS DISTINCT FROM OLD.id THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='queue_consumer_binding_identity',MESSAGE='private consumer UUID is immutable';
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'updated_at'-'created_at')=(to_jsonb(OLD)-'updated_at'-'created_at') THEN RETURN NEW; END IF;
  IF TG_OP='DELETE' THEN
   SELECT b.* INTO binding FROM queue_bindings b WHERE b.id=OLD.queue_binding_id;
  ELSE
   SELECT b.* INTO binding FROM queue_bindings b WHERE b.id=NEW.queue_binding_id;
  END IF;
  paths:=ARRAY['queue_bindings/'||binding.name];
 END IF;
 IF binding.environment_id IS NULL THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN apps a ON a.project_id=s.project_id AND a.account_id=s.account_id
  WHERE s.environment_id=binding.environment_id AND s.account_id=binding.account_id AND a.id=binding.app_id FOR UPDATE OF s;
 IF src.id IS NOT NULL THEN
  SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=binding.app_id;
  SELECT paths||coalesce(array_agg(q.field_path),'{}'::text[]) INTO paths FROM environment_gitops_queue_bindings q
   WHERE q.source_id=src.id AND q.binding_id=binding.id;
  controller:=EXISTS (SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id
   AND j.desired_generation=src.generation AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp()
   AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
  IF src.mode='enforce' AND NOT controller AND EXISTS (
   SELECT 1 FROM environment_managed_fields f WHERE f.environment_id=src.environment_id AND f.resource=resource_name
    AND f.field_path=ANY(paths) AND f.source_id=src.id AND NOT EXISTS (
     SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=f.environment_id AND o.resource=f.resource
      AND o.field_path=f.field_path AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
  END IF;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN
   INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
    ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at);
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_protected_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_protected_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (OLD.approval_policy='protected_branch' OR NEW.approval_policy='protected_branch') AND
    (NEW.account_id,NEW.project_id,NEW.environment_id,NEW.repository_id,NEW.installation_id,NEW.repository,NEW.source_ref,NEW.manifest_path,NEW.approval_policy)
    IS DISTINCT FROM
    (OLD.account_id,OLD.project_id,OLD.environment_id,OLD.repository_id,OLD.installation_id,OLD.repository,OLD.source_ref,OLD.manifest_path,OLD.approval_policy)
  THEN
    RAISE EXCEPTION 'Protected Git source identity is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.approval_policy='protected_branch' AND NEW.generation < OLD.generation THEN
    RAISE EXCEPTION 'Protected Git generations cannot move backwards' USING ERRCODE='23514';
  END IF;
  IF NEW.approval_policy='protected_branch' AND NEW.approved_revision_id IS DISTINCT FROM OLD.approved_revision_id THEN
    IF NEW.generation <> OLD.generation+1 OR NOT EXISTS (
      SELECT 1 FROM environment_git_revision_approvals a
      WHERE a.source_id=NEW.id AND a.revision_id=NEW.approved_revision_id AND a.approved_generation=NEW.generation
        AND a.id::text=current_setting('faas.environment_git_approval_id',true)
        AND a.recorded_at >= clock_timestamp()-interval '1 minute')
    THEN
      RAISE EXCEPTION 'Protected Git approval requires verified merge provenance' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_environment_protected_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_protected_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM environment_git_sources WHERE id=OLD.source_id AND approval_policy='protected_branch') THEN
    IF TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'Protected Git definition is immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_environment_qualification_attempt_replacement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_attempt_replacement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.reserved_instance_id IS DISTINCT FROM OLD.reserved_instance_id AND EXISTS(
  SELECT 1 FROM environment_qualification_executions WHERE instance_id=OLD.reserved_instance_id AND retired_at IS NULL) THEN
  RAISE EXCEPTION 'qualification attempt replacement requires physical retirement' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_execution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; i instances%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'qualification execution retention requires explicit collection' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id;
  SELECT * INTO i FROM instances WHERE id=NEW.instance_id;
  IF q.id IS NULL OR i.id IS NULL OR q.reserved_instance_id IS DISTINCT FROM i.id OR q.app_id IS DISTINCT FROM i.app_id
   OR q.deployment_id IS DISTINCT FROM i.deployment_id OR NEW.frame IS DISTINCT FROM environment_qualification_execution_frame(q,i)
   OR NEW.retirement IS NOT NULL OR NEW.retired_at IS NOT NULL THEN
   RAISE EXCEPTION 'qualification execution requires its original admitted attempt' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF ROW(NEW.instance_id,NEW.request_id,NEW.frame,NEW.cleanup_token,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.instance_id,OLD.request_id,OLD.frame,OLD.cleanup_token,OLD.created_at)
  OR OLD.dispatch_started AND NOT NEW.dispatch_started OR OLD.retired_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'qualification execution identity and retirement are immutable' USING ERRCODE='23514';
 END IF;
 IF NOT OLD.dispatch_started AND NEW.dispatch_started THEN
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE id=NEW.request_id;
  IF OLD.retired_at IS NOT NULL OR q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp()
   OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
   OR q.reserved_instance_id IS DISTINCT FROM NEW.instance_id OR q.attempt IS DISTINCT FROM (NEW.frame->>'attempt')::bigint
   OR NOT environment_workload_qualification_inputs_current(q.id) THEN
   RAISE EXCEPTION 'qualification dispatch requires its current execution lease' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL THEN
  IF NEW.cleanup_token::text IS DISTINCT FROM current_setting('gregale.gitops_qualification_cleanup',true)
   OR NEW.dispatch_started IS DISTINCT FROM OLD.dispatch_started THEN
   RAISE EXCEPTION 'qualification retirement requires its original cleanup capability' USING ERRCODE='23514';
  END IF;
  IF NOT OLD.dispatch_started THEN
   IF NEW.retirement IS DISTINCT FROM '{"kind":"never_dispatched"}'::jsonb THEN
    RAISE EXCEPTION 'unstarted qualification requires exact no-dispatch evidence' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.retirement->>'kind' IS DISTINCT FROM 'native_retired'
   OR NEW.retirement->'processes_exited' IS DISTINCT FROM 'true'::jsonb OR NEW.retirement->'resources_removed' IS DISTINCT FROM 'true'::jsonb
   OR coalesce((NEW.retirement->>'receipt_id')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
   OR coalesce((NEW.retirement->>'native_generation')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
   OR coalesce((NEW.retirement->>'kernel_boot_id')::uuid,'00000000-0000-0000-0000-000000000000')='00000000-0000-0000-0000-000000000000'
   OR NEW.retirement-(ARRAY['kind','receipt_id','native_generation','kernel_boot_id','processes_exited','resources_removed'])<>'{}'::jsonb THEN
   RAISE EXCEPTION 'qualification retirement requires complete native evidence' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_physical_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_physical_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE e environment_qualification_executions%ROWTYPE;
BEGIN
 SELECT * INTO e FROM environment_qualification_executions WHERE instance_id=OLD.id;
 IF e.instance_id IS NOT NULL THEN
  IF TG_OP='UPDATE' AND NEW.state='running' AND (NOT e.dispatch_started OR e.retired_at IS NOT NULL) THEN
   RAISE EXCEPTION 'qualification runtime requires a dispatched unretired attempt' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' AND e.retired_at IS NULL OR TG_OP='UPDATE' AND NEW.state NOT IN ('cold_booting','waking','running','draining','warm') AND e.retired_at IS NULL THEN
   RAISE EXCEPTION 'qualification reservation requires attempt-bound physical retirement' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.app_id,NEW.deployment_id,NEW.node_id,NEW.wake_id,NEW.ram_mb)
   IS DISTINCT FROM ROW(OLD.id,OLD.app_id,OLD.deployment_id,OLD.node_id,OLD.wake_id,OLD.ram_mb) THEN
   RAISE EXCEPTION 'qualification placement survives parent removal' USING ERRCODE='23514';
  END IF;
 ELSIF EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id AND environment_workload_runtime IS NOT NULL)
  AND (TG_OP='DELETE' OR NEW.state NOT IN ('cold_booting','waking','running','draining','warm')) THEN
  RAISE EXCEPTION 'legacy qualification has no recoverable execution frame' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_qualification_runtime_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_qualification_runtime_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; i instances%ROWTYPE;
BEGIN
 SELECT * INTO i FROM instances WHERE id=NEW.instance_id;
 IF NOT EXISTS(SELECT 1 FROM deployments WHERE id=i.deployment_id AND environment_workload_runtime IS NOT NULL) THEN RETURN NEW; END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=i.id;
 IF q.id IS NOT NULL THEN
  PERFORM s.id FROM active_environment_git_sources s JOIN environment_workload_graphs g ON g.source_id=s.id WHERE g.id=q.graph_id FOR UPDATE OF s;
  PERFORM a.id FROM apps a JOIN environment_workload_graphs g ON g.id=q.graph_id
   JOIN LATERAL jsonb_array_elements(g.members) m ON a.id=(m->>'app_id')::uuid ORDER BY a.id FOR UPDATE OF a;
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=i.id FOR UPDATE;
  PERFORM n.id FROM compute_nodes n WHERE n.id=i.node_id FOR SHARE OF n;
  PERFORM c.id FROM accounts c JOIN apps a ON a.account_id=c.id WHERE a.id=i.app_id FOR SHARE OF c;
  -- Terminal cleanup does not require the graph lock. Re-read and lock the
  -- incarnation after authority locks so a concurrent retirement wins.
  SELECT * INTO i FROM instances WHERE id=NEW.instance_id FOR UPDATE;
 END IF;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.lease_until<=clock_timestamp()
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR q.app_id<>i.app_id OR q.deployment_id<>i.deployment_id OR i.state<>'running'
  OR i.ram_mb IS DISTINCT FROM (SELECT a.ram_mb FROM apps a WHERE a.id=i.app_id)
  OR NOT EXISTS(SELECT 1 FROM compute_nodes n WHERE n.id=i.node_id AND n.active AND n.lifecycle='active')
  OR NEW.wake_id IS DISTINCT FROM i.wake_id OR NEW.scope IS DISTINCT FROM q.frozen_inputs->>'scope'
  OR NOT environment_workload_qualification_inputs_current(q.id)
  OR NOT environment_runtime_inputs_fresh(i.app_id,NEW.scope,NEW.boundary_at,NEW.variables,NEW.secret_versions,NEW.all_secrets,NEW.secret_refs,NEW.sidecar_secret_versions) THEN
  RAISE EXCEPTION 'environment runtime evidence requires its current qualification attempt and delivered inputs' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_secret_ref_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_secret_ref_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE row_value record; src environment_git_sources%ROWTYPE;
 resource_name text; controller boolean; stamp timestamptz;
BEGIN
 IF TG_OP='DELETE' THEN row_value:=OLD; ELSE row_value:=NEW; END IF;
 -- Parent cascades have already removed their catalog/app identity. Ordinary
 -- row deletion still passes through ownership enforcement below.
 IF TG_OP='DELETE' AND NOT EXISTS (SELECT 1 FROM apps a JOIN project_environments e ON e.id=row_value.environment_id
  WHERE a.id=row_value.app_id AND a.account_id=row_value.account_id AND a.project_id=row_value.project_id
   AND e.project_id=a.project_id AND e.account_id=a.account_id AND e.slug=row_value.scope) THEN
  -- Removing catalog intent also invalidates caches captured under its UUID.
  -- The surviving app can retain deployments/sealed provider credentials.
  IF EXISTS(SELECT 1 FROM apps WHERE id=row_value.app_id FOR UPDATE) THEN
   stamp:=clock_timestamp();
   INSERT INTO app_runtime_config_scope_changes(app_id,scope,changed_at) VALUES(row_value.app_id,row_value.scope,stamp)
    ON CONFLICT(app_id,scope) DO UPDATE SET changed_at=greatest(app_runtime_config_scope_changes.changed_at,excluded.changed_at);
   UPDATE snapshots p SET stale=true FROM deployments d WHERE p.deployment_id=d.id AND d.app_id=row_value.app_id
    AND d.scope=row_value.scope AND NOT p.stale;
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.project_id IS DISTINCT FROM OLD.project_id
  OR NEW.environment_id IS DISTINCT FROM OLD.environment_id OR NEW.app_id IS DISTINCT FROM OLD.app_id
  OR NEW.scope IS DISTINCT FROM OLD.scope OR NEW.key IS DISTINCT FROM OLD.key) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_identity',MESSAGE='secret reference identity is immutable';
 END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s
 WHERE s.environment_id=row_value.environment_id AND s.account_id=row_value.account_id FOR UPDATE OF s;
 IF TG_OP<>'DELETE' AND NOT EXISTS (SELECT 1 FROM apps a JOIN project_environments e ON e.id=row_value.environment_id
  WHERE a.id=row_value.app_id AND a.account_id=row_value.account_id AND a.project_id=row_value.project_id
   AND a.status<>'deleted' AND e.project_id=a.project_id AND e.account_id=a.account_id AND e.slug=row_value.scope
  FOR SHARE OF a,e) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_scope',MESSAGE='secret reference requires its account-owned project environment';
 END IF;
 IF src.id IS NOT NULL THEN
  SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=row_value.app_id;
  controller:=EXISTS (SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id
   AND j.desired_generation=src.generation AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp()
   AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true)
   AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
  IF src.mode='enforce' AND NOT controller AND EXISTS (
   SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=resource_name
    AND f.field_path='secret_refs/'||row_value.key AND NOT EXISTS (SELECT 1 FROM environment_management_overrides o
     WHERE o.environment_id=f.environment_id AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
  END IF;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN
   INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
   ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at);
  END IF;
 END IF;
 -- Publication and every ordinary writer share the app lock and scoped stamp.
 IF EXISTS(SELECT 1 FROM apps WHERE id=row_value.app_id FOR UPDATE) THEN
  stamp:=clock_timestamp();
  INSERT INTO app_runtime_config_scope_changes(app_id,scope,changed_at) VALUES(row_value.app_id,row_value.scope,stamp)
   ON CONFLICT(app_id,scope) DO UPDATE SET changed_at=greatest(app_runtime_config_scope_changes.changed_at,excluded.changed_at);
  UPDATE snapshots p SET stale=true FROM deployments d WHERE p.deployment_id=d.id AND d.app_id=row_value.app_id
   AND d.scope=row_value.scope AND NOT p.stale;
 END IF;
 -- Both kinds of intent share the same app lock. Direct SQL cannot retain
 -- a positive reference and a suppression for the same destination.
 IF TG_OP<>'DELETE' THEN
  IF (TG_TABLE_NAME='app_environment_secret_refs' AND EXISTS(SELECT 1 FROM app_environment_secret_ref_suppressions
    WHERE app_id=row_value.app_id AND environment_id=row_value.environment_id AND key=row_value.key))
   OR (TG_TABLE_NAME='app_environment_secret_ref_suppressions' AND EXISTS(SELECT 1 FROM app_environment_secret_refs
    WHERE app_id=row_value.app_id AND environment_id=row_value.environment_id AND key=row_value.key)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_exclusive',MESSAGE='reference and suppression are mutually exclusive';
  END IF;
  -- Mirrored by api.EnvironmentSecretReferenceSuppressionsMaxPerApp.
  IF TG_TABLE_NAME='app_environment_secret_ref_suppressions' AND TG_OP='INSERT'
   AND NOT EXISTS(SELECT 1 FROM app_environment_secret_ref_suppressions WHERE app_id=row_value.app_id AND environment_id=row_value.environment_id AND key=row_value.key)
   AND (SELECT count(*) FROM app_environment_secret_ref_suppressions WHERE app_id=row_value.app_id)>=1024 THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_secret_ref_suppression_quota',MESSAGE='secret reference suppression limit reached';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE NEW.updated_at:=stamp; RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_secret_reference_baseline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_secret_reference_baseline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE old_app uuid; new_app uuid; old_scope text; new_scope text; src environment_git_sources%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' AND OLD.status='live' THEN old_app:=OLD.app_id; old_scope:=OLD.scope; END IF;
 IF TG_OP<>'DELETE' AND NEW.status='live' THEN new_app:=NEW.app_id; new_scope:=NEW.scope; END IF;
 IF old_app IS NULL AND new_app IS NULL THEN
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 END IF;
 FOR src IN SELECT s.* FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
  JOIN apps a ON a.project_id=s.project_id AND a.account_id=s.account_id
  WHERE (a.id=old_app AND e.slug=old_scope) OR (a.id=new_app AND e.slug=new_scope)
  ORDER BY s.id FOR UPDATE OF s LOOP
  PERFORM 1 FROM apps a WHERE (a.id=old_app OR a.id=new_app) AND a.project_id=src.project_id ORDER BY a.id FOR UPDATE;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN
   INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
   ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at);
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_secret_reference_shadow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_secret_reference_shadow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE; resource_name text;
BEGIN
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
 JOIN apps a ON a.project_id=s.project_id AND a.account_id=s.account_id
 WHERE a.id=NEW.app_id AND a.account_id=NEW.account_id AND e.slug=NEW.scope FOR UPDATE OF s;
 IF src.id IS NULL OR src.mode<>'enforce' THEN RETURN NEW; END IF;
 SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=NEW.app_id;
 IF EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=resource_name
  AND f.field_path='secret_refs/'||NEW.key AND NOT EXISTS(SELECT 1 FROM environment_management_overrides o
   WHERE o.environment_id=f.environment_id AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp()))
 AND NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
  AND j.claimed_generation=src.generation AND j.lease_token=current_setting('gregale.gitops_lease',true)
  AND j.lease_token<>'' AND j.lease_until>clock_timestamp() AND NOT src.suspended AND src.approved_revision_id IS NOT NULL) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_environment_workload_candidate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_candidate() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE frozen jsonb; src environment_git_sources%ROWTYPE; allowed boolean;
BEGIN
 frozen:=NEW.environment_workload_runtime;
 IF TG_OP='UPDATE' AND OLD.environment_workload_runtime IS NOT NULL THEN
  IF NEW.environment_workload_runtime IS DISTINCT FROM OLD.environment_workload_runtime OR
   (OLD.environment_workload_runtime ? 'source_archive' AND ROW(NEW.source_bytes,NEW.source_url,NEW.log_path,NEW.inferred_profile,NEW.github_source_ref,NEW.github_installation_id)
    IS DISTINCT FROM ROW(OLD.source_bytes,OLD.source_url,OLD.log_path,OLD.inferred_profile,OLD.github_source_ref,OLD.github_installation_id)) OR
   (NEW.build_id IS DISTINCT FROM OLD.build_id AND (OLD.build_id IS NOT NULL OR frozen->'source_archive' IS NULL OR
    NEW.build_id IS DISTINCT FROM (frozen->'source_archive'->>'build_id')::uuid OR NOT EXISTS(
     SELECT 1 FROM builds b WHERE b.id=NEW.build_id AND b.deployment_id=NEW.id AND b.kind='github' AND b.source_bytes=NEW.source_bytes))) OR
   environment_workload_deployment_inputs(NEW) IS DISTINCT FROM environment_workload_deployment_inputs(OLD) OR
   ROW(NEW.app_id,NEW.scope,NEW.kind,NEW.image_digest,NEW.commit_sha,NEW.source_path,NEW.source_root,NEW.source_sha256,NEW.handler,
       NEW.override_entrypoint,NEW.override_cmd,NEW.override_env,NEW.override_env_secrets,NEW.override_port,NEW.override_healthcheck,
       NEW.override_liveness_probe,NEW.override_readiness_probe,NEW.override_main_depends_on,NEW.release_command,NEW.release_command_shell)
   IS DISTINCT FROM
   ROW(OLD.app_id,OLD.scope,OLD.kind,OLD.image_digest,OLD.commit_sha,OLD.source_path,OLD.source_root,OLD.source_sha256,OLD.handler,
       OLD.override_entrypoint,OLD.override_cmd,OLD.override_env,OLD.override_env_secrets,OLD.override_port,OLD.override_healthcheck,
       OLD.override_liveness_probe,OLD.override_readiness_probe,OLD.override_main_depends_on,OLD.release_command,OLD.release_command_shell) THEN
   RAISE EXCEPTION 'frozen environment workload inputs are immutable' USING ERRCODE='23514';
  END IF;
 ELSIF frozen IS NOT NULL THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'environment workload inputs must be created atomically' USING ERRCODE='23514'; END IF;
  SELECT * INTO src FROM active_environment_git_sources WHERE id=(frozen->>'source_id')::uuid FOR UPDATE;
  allowed:=src.id IS NOT NULL AND src.mode='enforce' AND NOT src.suspended AND src.generation=(frozen->>'generation')::bigint
   AND src.intent_version=(frozen->>'intent_version')::bigint AND src.environment_id=(frozen->>'environment_id')::uuid
   AND src.approved_revision_id=(frozen->>'revision_id')::uuid AND EXISTS(SELECT 1 FROM environment_gitops_jobs j
    WHERE j.source_id=src.id AND j.desired_generation=src.generation AND j.claimed_generation=src.generation
     AND j.lease_until>clock_timestamp() AND j.lease_token<>'' AND j.lease_token=current_setting('gregale.gitops_lease',true));
  IF NOT allowed OR NOT EXISTS(SELECT 1 FROM environment_gitops_resources r JOIN apps a ON a.id=r.app_id
   JOIN project_environments e ON e.id=src.environment_id JOIN app_environment_workload_intents w ON w.app_id=a.id AND w.environment_id=e.id
   JOIN environment_desired_revisions rev ON rev.id=src.approved_revision_id AND rev.source_id=src.id
   WHERE r.source_id=src.id AND r.logical_name=frozen->>'resource' AND r.app_id=NEW.app_id AND a.status IN ('active','evicted_cold') AND a.type='app'
    AND a.account_id=src.account_id AND a.project_id=src.project_id AND e.account_id=src.account_id AND e.project_id=src.project_id
    AND NEW.app_id=(frozen->>'app_id')::uuid AND NEW.scope=frozen->>'scope' AND NEW.scope=e.slug AND NEW.status='pending' AND (
     (NEW.kind='image' AND (
       (w.source->>'kind'='image' AND NEW.image_digest=w.source->>'image') OR
       (w.source IS NULL AND frozen ? 'deployment_inputs' AND jsonb_array_length(coalesce(frozen->'source_deployments','[]'::jsonb))>0
        AND NOT EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=a.id AND d.scope=e.slug AND d.status='live'
         AND (d.kind<>'image' OR d.image_digest IS DISTINCT FROM NEW.image_digest))))
      AND NEW.image_digest ~ '^[^[:space:]]+@sha256:[a-f0-9]{64}$') OR
     (NEW.kind='github' AND w.source->>'kind' IN ('source','dockerfile') AND w.source_revision=rev.commit_sha
      AND EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=r.logical_name AND f.field_path='source') AND frozen->'source'=w.source AND
      jsonb_typeof(frozen->'source_archive')='object' AND frozen->'source_archive' ?& ARRAY['build_id','path','sha256','bytes','log_path','revision_id','commit_sha','definition_digest'] AND
      frozen->'source_archive'->>'revision_id'=rev.id::text AND frozen->'source_archive'->>'commit_sha'=rev.commit_sha AND
      frozen->'source_archive'->>'definition_digest'=rev.definition_digest AND frozen->>'definition_digest'=rev.definition_digest AND
      (frozen->'source_archive'->>'build_id')::uuid IS NOT NULL AND substring(frozen->'source_archive'->>'build_id',15,1)='7' AND
      NEW.source_root=w.source->>'directory' AND NEW.source_path=frozen->'source_archive'->>'path' AND NEW.source_path LIKE '/%' AND
      NEW.source_sha256=frozen->'source_archive'->>'sha256' AND NEW.source_sha256 ~ '^[a-f0-9]{64}$' AND
      NEW.source_bytes=(frozen->'source_archive'->>'bytes')::bigint AND NEW.source_bytes>0 AND
      NEW.log_path=frozen->'source_archive'->>'log_path' AND NEW.log_path LIKE '/%' AND
      NEW.source_url='github://'||src.repository||'@'||rev.commit_sha AND NEW.build_id IS NULL AND NEW.inferred_profile IS NULL AND
      coalesce(NEW.github_source_ref,'')='' AND coalesce(NEW.image_digest,'')=''))
    AND NEW.commit_sha=rev.commit_sha AND frozen->'runtime'=w.runtime
    AND jsonb_strip_nulls(frozen->'baseline')=jsonb_strip_nulls(a.manifest)
    AND frozen->>'start_command'=coalesce(a.start_command,'')
    AND frozen->>'app_type'=a.type AND frozen->>'runtime_base'=coalesce(a.runtime,'') AND frozen->>'workload_class'=a.workload_class
    AND coalesce(a.manifest->'env','{}'::jsonb) IN ('{}'::jsonb,'null'::jsonb) AND coalesce(a.manifest->'service_bindings','[]'::jsonb) IN ('[]'::jsonb,'null'::jsonb)
    AND EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=r.logical_name AND (f.field_path='source' OR starts_with(f.field_path,'runtime/')))) THEN
   RAISE EXCEPTION 'environment workload preparation lost its reviewed authority' USING ERRCODE='23514';
  END IF;
  IF frozen ? 'deployment_inputs' AND (
   jsonb_typeof(frozen->'deployment_inputs') IS DISTINCT FROM 'object' OR
   frozen->'deployment_inputs' IS DISTINCT FROM environment_workload_deployment_inputs(NEW) OR
   frozen->'source_deployments' IS DISTINCT FROM coalesce((SELECT jsonb_agg(d.id::text ORDER BY d.id)
    FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.status='live'),'[]'::jsonb) OR
   NOT EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.status='live') OR
   EXISTS(SELECT 1 FROM deployments d WHERE d.app_id=NEW.app_id AND d.scope=NEW.scope AND d.status='live'
    AND environment_workload_deployment_inputs(d) IS DISTINCT FROM frozen->'deployment_inputs')) THEN
   RAISE EXCEPTION 'inherited environment workload inputs changed after review' USING ERRCODE='23514';
  END IF;
 END IF;
 IF frozen IS NOT NULL AND NEW.status='live' THEN
  RAISE EXCEPTION 'environment workload graph is not qualified for activation' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_environment_workload_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE src environment_git_sources%ROWTYPE; rev environment_desired_revisions%ROWTYPE;
 member jsonb; member_count integer; names jsonb; allowed boolean;
 binding queue_bindings%ROWTYPE; consumer_ids jsonb; binding_resource text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF NOT EXISTS(SELECT 1 FROM active_environment_git_sources s JOIN project_environments e ON e.id=s.environment_id
   WHERE s.id=OLD.source_id AND e.id=OLD.environment_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'environment graph journal is retained with its original source' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.source_id,NEW.environment_id,NEW.revision_id,NEW.generation,NEW.intent_version,
  NEW.plan_hash,NEW.definition_digest,NEW.members,NEW.resource_ids,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.source_id,OLD.environment_id,OLD.revision_id,OLD.generation,OLD.intent_version,
  OLD.plan_hash,OLD.definition_digest,OLD.members,OLD.resource_ids,OLD.created_at) THEN
  RAISE EXCEPTION 'reviewed environment graph inputs are immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO src FROM active_environment_git_sources WHERE id=NEW.source_id FOR UPDATE;
 allowed:=src.id IS NOT NULL AND src.environment_id=NEW.environment_id AND src.mode='enforce' AND NOT src.suspended
  AND src.generation=NEW.generation AND src.intent_version=NEW.intent_version AND src.approved_revision_id=NEW.revision_id
  AND EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp() AND j.lease_token<>''
   AND j.lease_token=current_setting('gregale.gitops_lease',true));
 SELECT * INTO rev FROM environment_desired_revisions WHERE id=NEW.revision_id AND source_id=NEW.source_id;
 IF NOT coalesce(allowed,false) OR rev.definition_digest IS DISTINCT FROM NEW.definition_digest THEN
  RAISE EXCEPTION 'environment graph preparation lost reviewed authority' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' AND (NEW.phase<>'preparing' OR NEW.prepared_at IS NOT NULL OR NEW.error_code<>'') THEN
  RAISE EXCEPTION 'environment graph must begin in preparation' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.phase='failed' AND ROW(NEW.phase,NEW.error_code,NEW.prepared_at) IS DISTINCT FROM ROW(OLD.phase,OLD.error_code,OLD.prepared_at)
  OR OLD.phase='prepared' AND NEW.phase='preparing'
  OR OLD.phase=NEW.phase AND ROW(NEW.error_code,NEW.prepared_at) IS DISTINCT FROM ROW(OLD.error_code,OLD.prepared_at)) THEN
  RAISE EXCEPTION 'environment graph preparation transition is invalid' USING ERRCODE='23514';
 END IF;
 SELECT count(DISTINCT value->>'resource'),coalesce(jsonb_agg(value->>'resource' ORDER BY value->>'resource'),'[]')
  INTO member_count,names FROM jsonb_array_elements(NEW.members);
 IF member_count<>jsonb_array_length(NEW.members) OR names IS DISTINCT FROM
  (SELECT coalesce(jsonb_agg('workload/'||key ORDER BY key),'[]') FROM jsonb_object_keys(rev.definition->'workloads') key) THEN
  RAISE EXCEPTION 'environment graph must include every reviewed workload exactly once' USING ERRCODE='23514';
 END IF;
 FOR member IN SELECT value FROM jsonb_array_elements(NEW.members) LOOP
  IF jsonb_typeof(member) IS DISTINCT FROM 'object' OR NOT member ?& ARRAY['resource','app_id','retained_deployments']
   OR jsonb_typeof(member->'retained_deployments') IS DISTINCT FROM 'array' OR NOT EXISTS(
    SELECT 1 FROM environment_gitops_resources r JOIN apps a ON a.id=r.app_id JOIN project_environments e ON e.id=src.environment_id
    WHERE r.source_id=src.id AND r.logical_name=member->>'resource' AND a.id=(member->>'app_id')::uuid
     AND a.account_id=src.account_id AND a.project_id=src.project_id AND a.status IN ('active','evicted_cold')
     AND e.account_id=src.account_id AND e.project_id=src.project_id
     AND NEW.resource_ids->>r.logical_name=a.id::text) OR
   member->'retained_deployments' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(d.id::text ORDER BY d.id),'[]')
    FROM deployments d JOIN project_environments e ON e.id=src.environment_id
    WHERE d.app_id=(member->>'app_id')::uuid AND d.scope=e.slug AND d.status='live') THEN
   RAISE EXCEPTION 'environment graph original workload identities changed' USING ERRCODE='23514';
  END IF;
  IF member ? 'candidate_deployment_id' THEN
   IF NOT EXISTS(SELECT 1 FROM deployments d WHERE d.id=(member->>'candidate_deployment_id')::uuid
    AND d.app_id=(member->>'app_id')::uuid AND d.environment_workload_runtime->>'source_id'=src.id::text
    AND d.environment_workload_runtime->>'environment_id'=src.environment_id::text
    AND d.environment_workload_runtime->>'revision_id'=rev.id::text
    AND d.environment_workload_runtime->>'generation'=NEW.generation::text
    AND d.environment_workload_runtime->>'intent_version'=NEW.intent_version::text
    AND d.environment_workload_runtime->>'resource'=member->>'resource'
    AND d.environment_workload_runtime->>'plan_hash'=NEW.plan_hash
    AND (NEW.phase<>'prepared' OR d.status='snapshotting' AND (coalesce(d.rootfs_path,'')<>'' OR coalesce(d.rootfs_key,'')<>''))) THEN
    RAISE EXCEPTION 'environment graph candidate does not match its reviewed inputs or artifact phase' USING ERRCODE='23514';
   END IF;
  ELSIF EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id AND f.resource=member->>'resource'
   AND (f.field_path='source' OR starts_with(f.field_path,'runtime/'))) THEN
   RAISE EXCEPTION 'environment graph is missing a managed workload candidate' USING ERRCODE='23514';
  END IF;
  FOR binding IN SELECT b.* FROM queue_bindings b WHERE b.app_id=(member->>'app_id')::uuid
   AND b.account_id=src.account_id AND b.environment_id=src.environment_id LOOP
   binding_resource:=(member->>'resource')||'/queue_bindings/'||binding.name;
   SELECT coalesce(jsonb_agg(t.id::text ORDER BY t.id),'[]') INTO consumer_ids FROM triggers t WHERE t.queue_binding_id=binding.id;
   IF NEW.resource_ids->>binding_resource IS DISTINCT FROM binding.id::text OR
    jsonb_array_length(consumer_ids)=1 AND NEW.resource_ids->>(binding_resource||'/consumer') IS DISTINCT FROM consumer_ids->>0 OR
    jsonb_array_length(consumer_ids)<>1 AND NEW.resource_ids ? (binding_resource||'/consumer') THEN
    RAISE EXCEPTION 'environment graph original queue and consumer identities changed' USING ERRCODE='23514';
   END IF;
  END LOOP;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_instance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_instance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q environment_workload_qualification_requests%ROWTYPE; app_ram integer; may_deploy boolean;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM deployments d
   JOIN active_environment_git_sources s ON s.id=(d.environment_workload_runtime->>'source_id')::uuid
   JOIN project_environments e ON e.id=(d.environment_workload_runtime->>'environment_id')::uuid WHERE d.id=OLD.deployment_id) THEN
   SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=OLD.id FOR UPDATE;
   IF OLD.state NOT IN ('parked','stopped','failed') OR (q.id IS NOT NULL AND q.lease_until>clock_timestamp()) THEN
    RAISE EXCEPTION 'environment qualification reservation must remain until retired and its attempt released' USING ERRCODE='23514';
   END IF;
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id AND environment_workload_runtime IS NOT NULL)
  AND ROW(NEW.id,NEW.app_id,NEW.deployment_id,NEW.node_id,NEW.wake_id,NEW.mode,NEW.ram_mb,NEW.kind,NEW.job_id)
   IS DISTINCT FROM ROW(OLD.id,OLD.app_id,OLD.deployment_id,OLD.node_id,OLD.wake_id,OLD.mode,OLD.ram_mb,OLD.kind,OLD.job_id) THEN
  RAISE EXCEPTION 'environment qualification instance identity is immutable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=NEW.id;
 IF q.id IS NOT NULL AND (q.app_id IS DISTINCT FROM NEW.app_id OR q.deployment_id IS DISTINCT FROM NEW.deployment_id) THEN
  RAISE EXCEPTION 'environment qualification reservation cannot be reassigned' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM deployments WHERE id=NEW.deployment_id AND environment_workload_runtime IS NOT NULL) THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NOT EXISTS(SELECT 1 FROM deployments WHERE id=OLD.deployment_id AND environment_workload_runtime IS NOT NULL) THEN
  RAISE EXCEPTION 'environment qualification instances must be created under their attempt' USING ERRCODE='23514';
 END IF;
 -- Retirement must remain available after expiry, supersession and parent
 -- deletion. It cannot grant execution or qualification evidence.
 IF TG_OP='UPDATE' AND NEW.state IN ('parked','stopped','failed','evicting_account_deleting') THEN RETURN NEW; END IF;
 IF q.id IS NOT NULL THEN
  PERFORM s.id FROM active_environment_git_sources s JOIN environment_workload_graphs g ON g.source_id=s.id
   WHERE g.id=q.graph_id FOR UPDATE OF s;
  PERFORM a.id FROM apps a JOIN environment_workload_graphs g ON g.id=q.graph_id
   JOIN LATERAL jsonb_array_elements(g.members) m ON a.id=(m->>'app_id')::uuid ORDER BY a.id FOR UPDATE OF a;
  SELECT * INTO q FROM environment_workload_qualification_requests WHERE reserved_instance_id=NEW.id AND deployment_id=NEW.deployment_id FOR UPDATE;
 END IF;
 IF q.id IS NULL OR q.phase<>'claimed' OR q.execution_mode='job' OR q.lease_until<=clock_timestamp()
  OR q.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true)
  OR q.app_id<>NEW.app_id OR NEW.kind<>'wake' OR NEW.job_id IS NOT NULL
  OR NEW.mode IS DISTINCT FROM (CASE q.execution_mode WHEN 'worker' THEN 'worker' WHEN 'service' THEN 'service' ELSE 'normal' END)
  OR NOT environment_workload_qualification_inputs_current(q.id) THEN
  RAISE EXCEPTION 'environment workload execution requires its current qualification attempt' USING ERRCODE='23514';
 END IF;
 SELECT a.ram_mb,c.status='active' AND c.abuse_hold_at IS NULL INTO app_ram,may_deploy
  FROM apps a JOIN accounts c ON c.id=a.account_id WHERE a.id=NEW.app_id FOR SHARE OF c;
 IF NOT coalesce(may_deploy,false) OR NEW.ram_mb IS DISTINCT FROM app_ram OR NOT EXISTS(
  SELECT 1 FROM compute_nodes WHERE id=NEW.node_id AND active AND lifecycle='active') OR
  (TG_OP='INSERT' AND (NEW.state<>'cold_booting' OR coalesce(NEW.netns,'')<>'' OR NEW.host_ip IS NOT NULL
   OR coalesce(NEW.guest_uid,0)<>0 OR NEW.framework_ready_at IS NOT NULL)) THEN
  RAISE EXCEPTION 'environment qualification admission shape is invalid' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_environment_workload_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 row_value jsonb; prior jsonb; src environment_git_sources%ROWTYPE;
 resource_name text; paths text[]; controller boolean;
BEGIN
 IF TG_OP='DELETE' THEN row_value:=to_jsonb(OLD); ELSE row_value:=to_jsonb(NEW); END IF;
 -- Parent purges remove their original identity before cascading. Ordinary
 -- scoped-row deletion still requires ownership authority below.
 IF TG_OP='DELETE' AND NOT EXISTS(SELECT 1 FROM apps a JOIN accounts c ON c.id=a.account_id
  JOIN project_environments e ON e.account_id=a.account_id AND e.project_id=a.project_id
  WHERE a.id=OLD.app_id AND a.account_id=OLD.account_id AND e.id=OLD.environment_id) THEN
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.app_id IS DISTINCT FROM OLD.app_id OR NEW.environment_id IS DISTINCT FROM OLD.environment_id) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_workload_intent_identity',MESSAGE='scoped workload identity is immutable';
 END IF;
 IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
  WHERE a.id=NEW.app_id AND a.account_id=NEW.account_id AND e.id=NEW.environment_id AND a.status<>'deleted') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_workload_intent_identity',MESSAGE='scoped workload requires its original project environment';
 END IF;
 SELECT s.* INTO src FROM active_environment_git_sources s WHERE s.account_id=(row_value->>'account_id')::uuid
  AND s.environment_id=(row_value->>'environment_id')::uuid FOR UPDATE OF s;
 -- ON CONFLICT fires the INSERT trigger before its UPDATE trigger. Compare
 -- against the original scoped row so an unchanged owned field is not an edit.
 IF TG_OP='INSERT' THEN
  SELECT to_jsonb(w) INTO prior FROM app_environment_workload_intents w
   WHERE w.app_id=NEW.app_id AND w.environment_id=NEW.environment_id FOR UPDATE OF w;
  prior:=coalesce(prior,'{}');
 ELSE prior:=to_jsonb(OLD); END IF;
 IF TG_OP='DELETE' THEN row_value:=row_value||jsonb_build_object('source',NULL,'source_revision',NULL,'runtime','{}'::jsonb); END IF;
 SELECT array_agg('runtime/'||k) INTO paths FROM (
  SELECT key k FROM jsonb_each(coalesce(prior->'runtime','{}')) UNION SELECT key FROM jsonb_each(row_value->'runtime')
 ) keys WHERE (prior->'runtime'->k) IS DISTINCT FROM (row_value->'runtime'->k);
 IF coalesce(prior->'source','null'::jsonb) IS DISTINCT FROM coalesce(row_value->'source','null'::jsonb) THEN paths:=coalesce(paths,'{}')||ARRAY['source']; END IF;
 IF coalesce(prior->'source_revision','null'::jsonb) IS DISTINCT FROM coalesce(row_value->'source_revision','null'::jsonb) THEN paths:=coalesce(paths,'{}')||ARRAY['source_revision','source']; END IF;
 IF coalesce(cardinality(paths),0)=0 THEN IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END IF;
 IF src.id IS NOT NULL THEN
  SELECT logical_name INTO resource_name FROM environment_gitops_resources WHERE source_id=src.id AND app_id=(row_value->>'app_id')::uuid;
  controller:=EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp() AND j.lease_token<>''
   AND j.lease_token=current_setting('gregale.gitops_lease',true) AND src.approved_revision_id IS NOT NULL AND NOT src.suspended);
  IF src.mode='enforce' AND NOT controller AND EXISTS(SELECT 1 FROM environment_managed_fields f WHERE f.source_id=src.id
   AND f.environment_id=src.environment_id AND f.resource=resource_name AND f.field_path=ANY(paths)
   AND NOT EXISTS(SELECT 1 FROM environment_management_overrides o WHERE o.environment_id=f.environment_id
    AND o.resource=f.resource AND o.field_path=f.field_path AND o.expires_at>clock_timestamp())) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='environment_gitops_field_owned',MESSAGE='setting is managed by the environment Git source';
  END IF;
  UPDATE environment_git_sources SET intent_version=intent_version+1,updated_at=now() WHERE id=src.id;
  IF src.generation>0 THEN INSERT INTO environment_gitops_jobs(source_id,desired_generation,next_attempt_at) VALUES(src.id,src.generation,now())
   ON CONFLICT(source_id) DO UPDATE SET next_attempt_at=least(environment_gitops_jobs.next_attempt_at,excluded.next_attempt_at); END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


--
-- Name: guard_environment_workload_qualification_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_environment_workload_qualification_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE graph environment_workload_graphs%ROWTYPE; src environment_git_sources%ROWTYPE; dep deployments%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF NOT EXISTS(SELECT 1 FROM environment_workload_graphs WHERE id=OLD.graph_id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'qualification work is retained with its reviewed graph' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.graph_id,NEW.deployment_id,NEW.app_id,NEW.resource,NEW.artifact,NEW.frozen_inputs,NEW.execution_mode,NEW.created_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.graph_id,OLD.deployment_id,OLD.app_id,OLD.resource,OLD.artifact,OLD.frozen_inputs,OLD.execution_mode,OLD.created_at) THEN
  RAISE EXCEPTION 'environment qualification inputs are immutable' USING ERRCODE='23514';
 END IF;
 -- The state store takes source, then sorted app locks, before this row.
 SELECT s.* INTO src FROM active_environment_git_sources s JOIN environment_workload_graphs g ON g.source_id=s.id WHERE g.id=NEW.graph_id FOR UPDATE OF s;
 SELECT * INTO graph FROM environment_workload_graphs WHERE id=NEW.graph_id;
 SELECT * INTO dep FROM deployments WHERE id=NEW.deployment_id;
 IF src.id IS NULL OR src.mode<>'enforce' OR src.suspended OR graph.phase<>'prepared' OR graph.generation<>src.generation OR
  graph.intent_version<>src.intent_version OR graph.revision_id IS DISTINCT FROM src.approved_revision_id OR graph.environment_id<>src.environment_id OR
  dep.status<>'snapshotting' OR coalesce(dep.rootfs_bytes,0)<=0 OR coalesce(dep.rootfs_key,'')='' AND coalesce(dep.rootfs_path,'')='' OR
  NEW.artifact IS DISTINCT FROM environment_workload_artifact(dep) OR NEW.frozen_inputs IS DISTINCT FROM dep.environment_workload_runtime OR
  NEW.execution_mode IS DISTINCT FROM (CASE WHEN NEW.frozen_inputs->'runtime' ? 'execution_mode'
   THEN coalesce(nullif(NEW.frozen_inputs->'runtime'->>'execution_mode',''),'request')
   ELSE coalesce(nullif(NEW.frozen_inputs->'baseline'->>'execution_mode',''),'request') END) OR
  NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph.members) m WHERE m->>'resource'=NEW.resource AND m->>'app_id'=NEW.app_id::text
   AND m->>'candidate_deployment_id'=NEW.deployment_id::text) OR NOT EXISTS(
   SELECT 1 FROM apps a JOIN project_environments e ON e.id=graph.environment_id
   WHERE a.id=NEW.app_id AND a.id=dep.app_id AND a.status IN ('active','evicted_cold') AND a.account_id=src.account_id AND a.project_id=src.project_id
    AND e.account_id=src.account_id AND e.project_id=src.project_id AND dep.scope=e.slug
    AND jsonb_strip_nulls(NEW.frozen_inputs->'baseline')=jsonb_strip_nulls(a.manifest)
    AND NEW.frozen_inputs->>'start_command'=coalesce(a.start_command,'')
    AND NEW.frozen_inputs->>'app_type'=a.type AND NEW.frozen_inputs->>'runtime_base'=coalesce(a.runtime,'')
    AND NEW.frozen_inputs->>'workload_class'=a.workload_class) THEN
  RAISE EXCEPTION 'environment qualification lost its reviewed graph or artifact' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.phase<>'queued' OR NOT EXISTS(SELECT 1 FROM environment_gitops_jobs j WHERE j.source_id=src.id AND j.desired_generation=src.generation
   AND j.claimed_generation=src.generation AND j.lease_until>clock_timestamp() AND j.lease_token<>''
   AND j.lease_token=current_setting('gregale.gitops_lease',true)) THEN
   RAISE EXCEPTION 'environment qualification publication requires the issued intent lease' USING ERRCODE='23514';
  END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(graph.members) m LEFT JOIN environment_workload_qualification_requests q
   ON q.graph_id=graph.id AND q.resource=m->>'resource' AND q.deployment_id=(m->>'candidate_deployment_id')::uuid
   LEFT JOIN deployments d ON d.id=q.deployment_id LEFT JOIN apps a ON a.id=d.app_id
   WHERE m ? 'candidate_deployment_id' AND (q.id IS NULL OR d.status IS DISTINCT FROM 'snapshotting'
    OR q.artifact IS DISTINCT FROM environment_workload_artifact(d) OR q.frozen_inputs IS DISTINCT FROM d.environment_workload_runtime
    OR a.status IS NULL OR a.status NOT IN ('active','evicted_cold')
    OR jsonb_strip_nulls(q.frozen_inputs->'baseline') IS DISTINCT FROM jsonb_strip_nulls(a.manifest)
    OR q.frozen_inputs->>'start_command' IS DISTINCT FROM coalesce(a.start_command,'')
    OR q.frozen_inputs->>'app_type' IS DISTINCT FROM a.type OR q.frozen_inputs->>'runtime_base' IS DISTINCT FROM coalesce(a.runtime,'')
    OR q.frozen_inputs->>'workload_class' IS DISTINCT FROM a.workload_class)) THEN
   RAISE EXCEPTION 'environment qualification requires the complete unchanged artifact cohort' USING ERRCODE='23514';
  END IF;
  IF NEW.phase<>'claimed' OR NEW.lease_token IS DISTINCT FROM current_setting('gregale.gitops_qualification',true) OR
   NEW.lease_until<=clock_timestamp() OR NEW.lease_until>clock_timestamp()+interval '15 minutes' OR
   (OLD.phase='claimed' AND OLD.lease_until>clock_timestamp() AND
    (NEW.lease_token<>OLD.lease_token OR NEW.worker_id<>OLD.worker_id OR NEW.attempt<>OLD.attempt OR NEW.lease_until<OLD.lease_until
     OR NEW.reserved_instance_id IS DISTINCT FROM OLD.reserved_instance_id)) OR
   ((OLD.phase='queued' OR OLD.lease_until<=clock_timestamp()) AND
    (NEW.attempt<>OLD.attempt+1 OR NEW.lease_token=OLD.lease_token OR
     OLD.reserved_instance_id IS NOT NULL AND NEW.execution_mode<>'job' AND NEW.reserved_instance_id=OLD.reserved_instance_id OR
     EXISTS(SELECT 1 FROM instances i WHERE i.id=OLD.reserved_instance_id AND i.state NOT IN ('parked','stopped','failed')))) THEN
   RAISE EXCEPTION 'environment qualification execution lease is stale' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_event_delivery_replay(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_event_delivery_replay() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE slot event_delivery_slots%ROWTYPE; caps event_delivery_capacity%ROWTYPE;
 consumer_count bigint; app_count bigint; account_count bigint; scope text;
BEGIN
 IF NEW.state NOT IN ('pending','dispatching') THEN RETURN NEW; END IF;
 IF TG_OP = 'UPDATE' AND OLD.state IN ('pending','dispatching') THEN RETURN NEW; END IF;
 SELECT * INTO slot FROM event_delivery_slots WHERE invocation_id=NEW.id;
 IF NOT FOUND AND NEW.replayed_from_invocation_id IS NOT NULL THEN
  SELECT * INTO slot FROM event_delivery_slots WHERE invocation_id=NEW.replayed_from_invocation_id;
 END IF;
 IF slot.invocation_id IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO STRICT caps FROM event_delivery_capacity WHERE account_id=slot.account_id FOR UPDATE;
 SELECT count(*), count(*) FILTER (WHERE s.app_id=slot.app_id),
   count(*) FILTER (WHERE s.app_id=slot.app_id AND s.subscription_id=slot.subscription_id)
 INTO account_count, app_count, consumer_count
 FROM event_delivery_slots s JOIN invocations i ON i.id=s.invocation_id
 WHERE s.account_id=slot.account_id AND i.state IN ('pending','dispatching') AND i.id<>NEW.id;
 scope := CASE WHEN consumer_count>=caps.consumer_limit THEN 'consumer'
   WHEN app_count>=caps.app_limit THEN 'app' WHEN account_count>=caps.account_limit THEN 'account' END;
 IF scope IS NOT NULL THEN
  RAISE EXCEPTION 'event delivery capacity exhausted: %',scope USING ERRCODE='23514', CONSTRAINT='event_delivery_capacity', DETAIL=scope;
 END IF;
 INSERT INTO event_delivery_slots VALUES (NEW.id,slot.account_id,slot.app_id,slot.subscription_id) ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;


--
-- Name: guard_held_queue_consumer_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_held_queue_consumer_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE can_claim boolean;
BEGIN
  IF NEW.state='claimed' AND (OLD.state IS DISTINCT FROM 'claimed'
    OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation) THEN
    SELECT b.enabled AND b.mode='push' AND b.retired_at IS NULL AND (b.deployment_scope='' OR EXISTS (
      SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
        WHERE a.id=b.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope)) INTO can_claim
      FROM queue_bindings b JOIN triggers t ON t.queue_binding_id=b.id WHERE t.id=NEW.trigger_id FOR SHARE OF b;
    IF can_claim IS FALSE THEN RETURN NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_instance_layer_artifacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_instance_layer_artifacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.deployment_id IS NOT NULL AND NEW.state IN ('pending', 'waking', 'cold_booting', 'running', 'snapshotting', 'migrating', 'warm', 'draining') THEN
        PERFORM require_deployment_layer_artifacts(NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_deployment_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_deployment_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND (NEW.deployment_scope IS NULL OR NEW.deployment_scope = '') THEN
    SELECT CASE WHEN a.project_id IS NOT NULL AND coalesce(a.preview_of_slug, '') = ''
      THEN 'production' ELSE 'default' END INTO NEW.deployment_scope
      FROM apps a WHERE a.id = NEW.app_id FOR SHARE OF a;
  ELSIF TG_OP = 'UPDATE' AND NEW.deployment_scope IS DISTINCT FROM OLD.deployment_scope THEN
    RAISE EXCEPTION 'invocation deployment scope is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'invocation_deployment_scope_identity';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_platform_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_platform_tenant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE tenant_status text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.platform_tenant_id IS DISTINCT FROM OLD.platform_tenant_id OR
       (OLD.platform_tenant_id IS NOT NULL AND
        (NEW.app_id IS DISTINCT FROM OLD.app_id OR NEW.account_id IS DISTINCT FROM OLD.account_id)) THEN
      RAISE EXCEPTION 'invocation tenant identity is immutable'
        USING ERRCODE = '23514', CONSTRAINT = 'invocation_platform_tenant_identity';
    END IF;
  END IF;
  IF NEW.platform_tenant_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' OR (OLD.state = 'pending' AND NEW.state = 'dispatching') THEN
    SELECT t.status INTO tenant_status FROM platform_tenants t JOIN apps a ON a.account_id = t.account_id
      WHERE t.id = NEW.platform_tenant_id AND t.account_id = NEW.account_id
        AND a.id = NEW.app_id
      FOR SHARE OF t, a;
    IF NOT FOUND THEN
      IF TG_OP = 'UPDATE' THEN RETURN NULL; END IF;
      RAISE EXCEPTION 'invocation tenant must be active and own the app account'
        USING ERRCODE = '23514', CONSTRAINT = 'invocation_platform_tenant_identity';
    END IF;
    IF tenant_status <> 'active' THEN
      IF TG_OP = 'UPDATE' THEN RETURN NULL; END IF;
      RAISE EXCEPTION 'invocation platform tenant is suspended'
        USING ERRCODE = '23514', CONSTRAINT = 'invocation_platform_tenant_active';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_queue_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_queue_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.queue_binding_id IS DISTINCT FROM OLD.queue_binding_id OR
      (OLD.queue_binding_id IS NOT NULL AND (NEW.app_id IS DISTINCT FROM OLD.app_id
        OR NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.source IS DISTINCT FROM OLD.source
        OR NEW.queue_name IS DISTINCT FROM OLD.queue_name)) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_identity',
        MESSAGE='accepted queue binding identity is immutable';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.queue_binding_id IS NOT NULL AND NEW.source<>'queue' THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_source',
      MESSAGE='binding identity requires a queue invocation';
  END IF;
  IF NEW.environment_id IS NOT NULL AND NEW.source='queue' THEN
    IF NEW.queue_binding_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_private_queue_binding',
        MESSAGE='private queue work cannot capture a public binding';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.source='queue' THEN
    IF NEW.queue_binding_id IS NULL AND NEW.queue_name<>'' THEN
      SELECT b.id INTO NEW.queue_binding_id FROM queue_bindings b
        WHERE b.app_id=NEW.app_id AND b.account_id=NEW.account_id AND b.queue_name=NEW.queue_name
          AND (b.deployment_scope='' OR (b.deployment_scope=NEW.deployment_scope AND EXISTS
            (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
              WHERE a.id=NEW.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope)))
        ORDER BY (b.deployment_scope<>'') DESC LIMIT 1;
    ELSIF NEW.queue_binding_id IS NULL AND NEW.work_policy_name IS NULL THEN
      SELECT b.id INTO NEW.queue_binding_id FROM queue_bindings b JOIN triggers t ON t.queue_binding_id=b.id
        WHERE b.app_id=NEW.app_id AND b.account_id=NEW.account_id AND b.enabled
          AND (b.deployment_scope='' OR (b.deployment_scope=NEW.deployment_scope AND EXISTS
            (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
              WHERE a.id=NEW.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope)))
          AND b.mode='push' AND b.retired_at IS NULL AND t.enabled AND t.kind='queue' AND t.source='queue'
          AND NOT EXISTS (SELECT 1 FROM triggers other WHERE other.app_id=NEW.app_id
            AND other.kind='queue' AND other.source='queue' AND other.enabled AND other.id<>t.id
            AND (other.queue_binding_scope='' OR (other.queue_binding_scope=NEW.deployment_scope AND EXISTS
              (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
                WHERE a.id=NEW.app_id AND e.id=other.queue_binding_environment_id AND e.slug=other.queue_binding_scope))));
    END IF;
    IF NEW.queue_binding_id IS NOT NULL THEN
      PERFORM 1 FROM queue_bindings b WHERE b.id=NEW.queue_binding_id
        AND b.app_id=NEW.app_id AND b.account_id=NEW.account_id
        AND (b.deployment_scope='' OR (b.deployment_scope=NEW.deployment_scope AND EXISTS
            (SELECT 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
              WHERE a.id=NEW.app_id AND e.id=b.environment_id AND e.slug=b.deployment_scope))) FOR SHARE;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_tenant',
          MESSAGE='queue binding must belong to the admitted app, account and environment';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_invocation_replay_generation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_invocation_replay_generation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    NEW.replay_generation=0;
  ELSIF OLD.state='dead_letter' AND NEW.state='pending' THEN
    NEW.replay_generation=OLD.replay_generation+1;
  ELSIF NEW.replay_generation IS DISTINCT FROM OLD.replay_generation THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_replay_generation_identity',
      MESSAGE='invocation replay generation is owned by the delivery ledger';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_accounting_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_accounting_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.accounting_required AND NOT NEW.accounting_required THEN
        RAISE EXCEPTION 'managed postgres accounting obligation cannot be cleared'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_accounting_intent_retained';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_admission_fence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_admission_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE intent managed_postgres_cutovers%ROWTYPE; checked_at timestamptz;
BEGIN
 IF NEW.managed_postgres_admission_cutover_id IS NOT DISTINCT FROM OLD.managed_postgres_admission_cutover_id THEN
  IF NEW.managed_postgres_admission_fenced_at IS DISTINCT FROM OLD.managed_postgres_admission_fenced_at
   OR (OLD.managed_postgres_admission_cutover_id IS NOT NULL AND ROW(NEW.id,NEW.account_id) IS DISTINCT FROM ROW(OLD.id,OLD.account_id)) THEN
   RAISE EXCEPTION 'admission fence is immutable' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.managed_postgres_admission_cutover_id IS NOT NULL THEN
  SELECT * INTO intent FROM managed_postgres_cutovers WHERE id=OLD.managed_postgres_admission_cutover_id FOR SHARE;
  IF NEW.managed_postgres_admission_cutover_id IS NOT NULL OR intent.state IS DISTINCT FROM 'cancelled' THEN
   RAISE EXCEPTION 'admission fence cannot be released' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 ELSE
  SELECT * INTO intent FROM managed_postgres_cutovers WHERE id=NEW.managed_postgres_admission_cutover_id FOR SHARE;
  checked_at := clock_timestamp();
  IF intent.app_id IS DISTINCT FROM NEW.id OR intent.account_id IS DISTINCT FROM NEW.account_id
   OR intent.state IS DISTINCT FROM 'verified' OR intent.lease_token IS NOT NULL
   OR intent.verified_at IS NULL OR intent.verified_at>checked_at OR intent.verified_at<checked_at-interval '5 minutes'
   OR NEW.status NOT IN ('active','evicted_cold')
   OR NOT EXISTS (SELECT 1 FROM managed_postgres_cutover_credentials WHERE cutover_id=intent.id)
   OR EXISTS (SELECT 1 FROM managed_postgres_cutover_credentials WHERE cutover_id=intent.id
    AND (state<>'sealed' OR verified_at IS NULL OR verified_at>checked_at OR verified_at<checked_at-interval '5 minutes')) THEN
   RAISE EXCEPTION 'cutover verification is not fresh' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
  NEW.managed_postgres_admission_fenced_at := checked_at;
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_app_task_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_app_task_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pinned uuid;
BEGIN
 IF NEW.status NOT IN ('restoring','running') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.app_id,NEW.status) IS NOT DISTINCT FROM ROW(OLD.app_id,OLD.status) THEN
  RETURN NEW;
 END IF;
 -- Same tuple barrier as ordinary instances; old repeatable-read claims
 -- abort rather than admitting commands from a pre-fence snapshot.
 SELECT managed_postgres_admission_cutover_id INTO pinned FROM apps WHERE id=NEW.app_id FOR SHARE;
 IF pinned IS NOT NULL THEN
  RAISE EXCEPTION 'app task admission is fenced by a database cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_admission_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_binding_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_binding_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM managed_postgres_databases database
        JOIN apps app ON app.id = NEW.app_id
        WHERE database.id = NEW.database_id
          AND database.account_id = NEW.account_id
          AND app.account_id = NEW.account_id
          AND database.state <> 'deleted'
          AND app.status <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed postgres binding owner mismatch or parent is deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_binding_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_cutover_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_cutover_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pinned uuid;
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') AND OLD.cutover_id IS NOT NULL THEN
  IF TG_OP='DELETE' OR (to_jsonb(NEW)-'cutover_id') IS DISTINCT FROM (to_jsonb(OLD)-'cutover_id')
   OR (NEW.cutover_id IS DISTINCT FROM OLD.cutover_id AND (NEW.cutover_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM managed_postgres_cutovers WHERE id=OLD.cutover_id AND state='cancelled'))) THEN
   RAISE EXCEPTION 'binding is pinned by a cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 END IF;
 IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND ROW(NEW.database_id,NEW.app_id,NEW.scope,NEW.environment_key) IS DISTINCT FROM ROW(OLD.database_id,OLD.app_id,OLD.scope,OLD.environment_key)) THEN
  SELECT cutover_id INTO pinned FROM managed_postgres_databases WHERE id=NEW.database_id FOR KEY SHARE;
  IF pinned IS NOT NULL THEN
   RAISE EXCEPTION 'database is pinned by a cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_cutover_database(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_cutover_database() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.cutover_id IS NOT NULL THEN
  IF TG_OP='DELETE' OR ROW(NEW.account_id,NEW.state,NEW.backend_id,NEW.backend_fingerprint,NEW.provider_resource_id,NEW.desired_generation,NEW.region,NEW.postgres_major,NEW.service_class,NEW.availability,NEW.scale_to_zero,NEW.storage_limit_bytes,NEW.restore_window_seconds)
     IS DISTINCT FROM ROW(OLD.account_id,OLD.state,OLD.backend_id,OLD.backend_fingerprint,OLD.provider_resource_id,OLD.desired_generation,OLD.region,OLD.postgres_major,OLD.service_class,OLD.availability,OLD.scale_to_zero,OLD.storage_limit_bytes,OLD.restore_window_seconds)
     OR (NEW.cutover_id IS DISTINCT FROM OLD.cutover_id AND (NEW.cutover_id IS NOT NULL OR NOT EXISTS (SELECT 1 FROM managed_postgres_cutovers WHERE id=OLD.cutover_id AND state='cancelled'))) THEN
   RAISE EXCEPTION 'database is pinned by a cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_conflict';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_database_bindings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_database_bindings() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state = 'deleted' AND EXISTS (
        SELECT 1 FROM managed_postgres_bindings WHERE database_id = NEW.id AND state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed postgres database has active bindings'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_database_has_bindings';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_instance_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_instance_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE pinned uuid;
BEGIN
 IF NEW.app_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state IN ('parked','stopped','failed') THEN RETURN NEW; END IF;
 ELSIF ROW(NEW.app_id,NEW.state) IS NOT DISTINCT FROM ROW(OLD.app_id,OLD.state)
  OR NEW.state NOT IN ('waking','cold_booting','running','warm') THEN
  RETURN NEW;
 END IF;
 -- A SHARE lock conflicts with the app UPDATE that installs the fence.
 -- The updated app tuple also fences transactions using repeatable-read.
 SELECT managed_postgres_admission_cutover_id INTO pinned FROM apps WHERE id=NEW.app_id FOR SHARE;
 IF pinned IS NOT NULL THEN
  RAISE EXCEPTION 'instance admission is fenced by a database cutover' USING ERRCODE='23514', CONSTRAINT='managed_postgres_cutover_admission_fenced';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_resize_database(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_resize_database() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM managed_postgres_resizes WHERE database_id=OLD.id AND state='pending') THEN
  IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'database has an unresolved resize' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
  END IF;
  IF ROW(NEW.account_id,NEW.backend_id,NEW.backend_fingerprint,NEW.provider_resource_id,NEW.data_resource_id,
      NEW.region,NEW.postgres_major,NEW.service_class,NEW.availability,NEW.scale_to_zero,NEW.storage_limit_bytes,NEW.restore_window_seconds,
      NEW.desired_generation,NEW.observed_generation,NEW.cutover_id,NEW.environment_clone_operation_id,NEW.clone_resource_role)
      IS DISTINCT FROM ROW(OLD.account_id,OLD.backend_id,OLD.backend_fingerprint,OLD.provider_resource_id,OLD.data_resource_id,
      OLD.region,OLD.postgres_major,OLD.service_class,OLD.availability,OLD.scale_to_zero,OLD.storage_limit_bytes,OLD.restore_window_seconds,
      OLD.desired_generation,OLD.observed_generation,OLD.cutover_id,OLD.environment_clone_operation_id,OLD.clone_resource_role)
      OR NEW.state<>'updating' THEN
   RAISE EXCEPTION 'database has an unresolved resize' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_resize_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_resize_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.state='pending' AND EXISTS(SELECT 1 FROM managed_postgres_databases WHERE id=OLD.database_id) THEN
   RAISE EXCEPTION 'pending resize intent cannot be removed' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
  END IF;
  RETURN OLD;
 END IF;
 IF (to_jsonb(NEW)-'state'-'completed_at') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'completed_at')
  OR (OLD.state='succeeded' AND NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'resize intent is immutable' USING ERRCODE='23514', CONSTRAINT='managed_postgres_resize_conflict';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_restore_sources(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_restore_sources() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state = 'deleted' AND EXISTS (
        SELECT 1 FROM managed_postgres_databases
        WHERE restore_source_database_id = NEW.id AND state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed postgres database has active restore descendants'
            USING ERRCODE = '23514', CONSTRAINT = 'managed_postgres_database_has_restore_descendants';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_managed_postgres_secret_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_managed_postgres_secret_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.managed_postgres_binding_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM managed_postgres_bindings binding
        WHERE binding.id = NEW.managed_postgres_binding_id
          AND binding.account_id = NEW.account_id
          AND binding.app_id = NEW.app_id
          AND binding.scope = NEW.scope
          AND binding.environment_key = NEW.key
          AND binding.credential_generation = NEW.managed_credential_generation
          AND binding.state <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'managed app secret owner does not match its binding'
            USING ERRCODE = '23514', CONSTRAINT = 'app_secret_managed_postgres_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_object_multipart_initiation_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_multipart_initiation_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF EXISTS(SELECT 1 FROM object_bucket_mutations WHERE multipart_upload_id=OLD.multipart_upload_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_live',MESSAGE='Retain original initiation evidence while the provider receipt is outstanding';
  END IF;
  RETURN OLD;
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_isolation',MESSAGE='Initiation dispatch requires READ COMMITTED';
 END IF;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.multipart_upload_id;
 PERFORM id FROM accounts WHERE id=u.account_id FOR UPDATE;
 PERFORM id FROM object_buckets WHERE id=u.bucket_id FOR UPDATE;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.multipart_upload_id FOR UPDATE;
 IF u.id IS NULL OR u.state<>'initiating' OR u.provider_upload_id<>'' OR NOT EXISTS(
  SELECT 1 FROM object_bucket_mutations m JOIN object_buckets b ON b.id=m.bucket_id
  WHERE m.multipart_upload_id=u.id AND m.kind='request' AND b.id=u.bucket_id AND b.account_id=u.account_id AND b.app_id=u.app_id
  AND b.state='ready' AND b.backend_id=m.backend_id AND b.backend_fingerprint=m.backend_fingerprint AND b.physical_name=m.physical_name
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_original',MESSAGE='Initiation requires the original session receipt and placement';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.dispatched OR NEW.dispatch_token<>'' OR NEW.provider_upload_id<>'' OR u.lease_token IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_reserved',MESSAGE='Initialize dispatch evidence only with a new reservation';
  END IF;
 ELSIF NEW.multipart_upload_id<>OLD.multipart_upload_id OR u.lease_token IS NULL OR u.lease_token='' OR u.lease_until IS NULL OR u.lease_until<=clock_timestamp() OR NOT (
  (NOT OLD.dispatched AND NEW.dispatched AND NEW.dispatch_token=u.lease_token AND NEW.provider_upload_id='') OR
  (OLD.dispatched AND NEW.dispatched AND OLD.dispatch_token=u.lease_token AND NEW.dispatch_token=OLD.dispatch_token AND OLD.provider_upload_id='' AND btrim(NEW.provider_upload_id)<>'' AND NEW.provider_upload_id !~ '[[:cntrl:]]')
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_initiation_immutable',MESSAGE='Dispatch is once-only and only its live owner may record a positive reply';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_object_multipart_part_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_multipart_part_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.multipart_part_writer_id IS NOT NULL AND EXISTS(SELECT 1 FROM object_multipart_part_writers WHERE id=OLD.multipart_part_writer_id AND NOT settled) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Settle the original part writer before deleting its receipt';
  END IF;
  RETURN OLD;
 ELSIF TG_OP='UPDATE' THEN
  IF NEW.multipart_part_writer_id IS NOT NULL OR OLD.multipart_part_writer_id IS NOT NULL THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Original part receipts are immutable';
  END IF;
 ELSIF NEW.multipart_part_writer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM object_multipart_part_writers d WHERE d.id=NEW.multipart_part_writer_id AND d.id=NEW.id AND d.managed AND d.dispatched AND NOT d.settled AND d.bucket_id=NEW.bucket_id AND d.backend_id=NEW.backend_id AND d.backend_fingerprint=NEW.backend_fingerprint AND d.physical_name=NEW.physical_name AND NEW.kind='request') THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Bind the receipt to its original claimed part attempt';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_object_multipart_part_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_object_multipart_part_writer() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE u object_storage_multipart_uploads%ROWTYPE; g object_storage_multipart_part_grants%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.dispatched AND NOT OLD.settled THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Uncertain part evidence cannot be deleted';
  END IF;
  RETURN OLD;
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Part writers require READ COMMITTED';
 END IF;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.upload_id;
 PERFORM id FROM accounts WHERE id=u.account_id FOR UPDATE;
 PERFORM id FROM object_buckets WHERE id=u.bucket_id FOR UPDATE;
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.upload_id FOR UPDATE;
 SELECT * INTO g FROM object_storage_multipart_part_grants WHERE upload_id=NEW.upload_id AND part_number=NEW.part_number;
 IF u.id IS NULL OR u.bucket_id<>NEW.bucket_id OR NOT EXISTS(SELECT 1 FROM object_buckets b WHERE b.id=u.bucket_id AND b.account_id=u.account_id AND b.app_id=u.app_id AND b.state='ready' AND b.backend_id=NEW.backend_id AND b.backend_fingerprint=NEW.backend_fingerprint AND b.physical_name=NEW.physical_name) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Part writer requires its original placement';
 END IF;
 IF TG_OP='INSERT' THEN
  IF EXISTS(SELECT 1 FROM object_bucket_write_fences WHERE bucket_id=u.bucket_id) THEN
   RAISE EXCEPTION USING ERRCODE='55000',CONSTRAINT='object_multipart_part_capture_fenced',MESSAGE='Capture fences new part transfer admission';
  END IF;
  IF NOT NEW.managed OR NEW.dispatched OR NEW.settled OR u.state<>'active' OR g.transfer_token IS DISTINCT FROM NEW.transfer_token THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Reserve part evidence only with new unfenced transfer authority';
  END IF;
 ELSIF (to_jsonb(NEW)-ARRAY['dispatched','settled','copy_intent','put_intent','body_sha256']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['dispatched','settled','copy_intent','put_intent','body_sha256']) OR OLD.settled OR NOT OLD.managed OR NOT (
  (OLD.copy_intent IS NULL AND OLD.put_intent IS NULL AND OLD.body_sha256='' AND NEW.body_sha256='' AND NOT OLD.dispatched AND NEW.dispatched AND NOT NEW.settled AND u.state='active' AND u.expires_at>clock_timestamp() AND g.transfer_token IS NOT DISTINCT FROM NEW.transfer_token AND g.unsafe_until>clock_timestamp()) OR
  (NEW.copy_intent IS NOT DISTINCT FROM OLD.copy_intent AND NEW.put_intent IS NOT DISTINCT FROM OLD.put_intent AND NEW.body_sha256=OLD.body_sha256 AND NEW.dispatched=OLD.dispatched AND NEW.settled AND (NOT OLD.dispatched OR g.transfer_token IS NOT DISTINCT FROM NEW.transfer_token))
  OR (OLD.dispatched AND NOT OLD.settled AND NEW.dispatched AND NOT NEW.settled AND OLD.put_intent IS NOT NULL AND OLD.copy_intent IS NULL
   AND NEW.put_intent IS NOT DISTINCT FROM OLD.put_intent AND NEW.copy_intent IS NOT DISTINCT FROM OLD.copy_intent
   AND (OLD.body_sha256='' OR OLD.body_sha256=NEW.body_sha256) AND NEW.body_sha256 ~ '^[0-9a-f]{64}$' AND g.transfer_token IS NOT DISTINCT FROM NEW.transfer_token
   AND (OLD.put_intent->>'expected_sha256'='' OR OLD.put_intent->>'expected_sha256'=NEW.body_sha256))
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Dispatch once; settle only the original attempt with qualified proof';
 END IF;
 IF TG_OP='UPDATE' AND NOT OLD.dispatched AND NEW.dispatched AND NEW.copy_intent IS NOT NULL AND NOT COALESCE((
  NEW.copy_intent->>'destination_key'=u.object_key AND NEW.copy_intent->>'provider_upload_id'=u.provider_upload_id
  AND (NEW.copy_intent->>'expected_size')::bigint BETWEEN 1 AND g.max_bytes
  AND (NEW.copy_intent->>'source_size')::bigint >= (NEW.copy_intent->>'expected_size')::bigint
  AND NEW.copy_intent->>'source_etag'<>'' AND NEW.copy_intent->>'source_key'<>''
  AND ((g.source_bucket_id IS NULL AND NEW.copy_intent->>'source_bucket_id'=u.bucket_id::text)
   OR (NEW.copy_intent->>'source_bucket_id'=g.source_bucket_id::text AND NEW.copy_intent->>'source_key'=g.source_key))
  AND EXISTS(SELECT 1 FROM object_buckets b WHERE b.id::text=NEW.copy_intent->>'source_bucket_id' AND b.account_id=u.account_id AND b.state='ready'
   AND b.backend_id=NEW.copy_intent->>'source_backend_id' AND b.backend_fingerprint=NEW.copy_intent->>'source_backend_fingerprint' AND b.physical_name=NEW.copy_intent->>'source_physical_name')
  AND (((NEW.copy_intent->>'has_range')::boolean AND (NEW.copy_intent->>'range_first')::bigint>=0 AND (NEW.copy_intent->>'range_last')::bigint<(NEW.copy_intent->>'source_size')::bigint
    AND (NEW.copy_intent->>'expected_size')::bigint=(NEW.copy_intent->>'range_last')::bigint-(NEW.copy_intent->>'range_first')::bigint+1)
   OR (NOT (NEW.copy_intent->>'has_range')::boolean AND (NEW.copy_intent->>'range_first')::bigint=0 AND (NEW.copy_intent->>'range_last')::bigint=0 AND NEW.copy_intent->>'expected_size'=NEW.copy_intent->>'source_size'))
 ),false) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='Copy intent requires the original measured source, range and destination';
 END IF;
 IF TG_OP='UPDATE' AND NOT OLD.dispatched AND NEW.dispatched AND NEW.put_intent IS NOT NULL AND NOT COALESCE((
  NEW.copy_intent IS NULL AND g.source_bucket_id IS NULL
  AND NEW.put_intent->>'destination_key'=u.object_key AND NEW.put_intent->>'provider_upload_id'=u.provider_upload_id
  AND ((g.url_credential_id IS NULL AND (NEW.put_intent->>'expected_size')::bigint BETWEEN 1 AND g.max_bytes)
   OR (g.url_credential_id IS NOT NULL AND u.part_count>0 AND u.part_size_bytes>0 AND u.size_bytes>0
    AND NEW.part_number BETWEEN 1 AND u.part_count
    AND (NEW.put_intent->>'expected_size')::bigint=least(u.part_size_bytes,u.size_bytes-(NEW.part_number-1)::bigint*u.part_size_bytes)))
  AND (NEW.put_intent->>'expected_sha256'='' OR NEW.put_intent->>'expected_sha256' ~ '^[0-9a-f]{64}$')
 ),false) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_multipart_part_writer_conflict',MESSAGE='PUT intent requires its original destination and admitted size';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_outbound_app_binding_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_app_binding_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM apps app
          JOIN outbound_integrations integration
            ON integration.id = NEW.integration_id
         WHERE app.id = NEW.app_id
           AND app.account_id = NEW.account_id
           AND app.status <> 'deleted'
           AND integration.account_id = NEW.account_id
           AND integration.provider_auth_mode = 'managed'
    ) THEN
        RAISE EXCEPTION 'outbound binding owner mismatch or integration is not managed'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_app_binding_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbound_credential_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_credential_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM outbound_integrations integration
         WHERE integration.id = NEW.integration_id
           AND integration.account_id = NEW.account_id
           AND integration.provider_auth_mode = 'managed'
           AND integration.credential_source = 'customer_sealed'
    ) THEN
        RAISE EXCEPTION 'outbound credential owner or source mismatch'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_credential_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbound_integration_app_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_integration_app_owner() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM outbound_integrations integration
        JOIN apps app ON app.id = NEW.app_id
        WHERE integration.id = NEW.integration_id
          AND integration.account_id = app.account_id
          AND app.status <> 'deleted'
    ) THEN
        RAISE EXCEPTION 'outbound integration app owner mismatch or app is deleted'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_integration_app_owner';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbound_integration_owner_kind(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_outbound_integration_owner_kind() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.owner_kind <> NEW.owner_kind THEN
        RAISE EXCEPTION 'outbound integration owner kind is immutable'
            USING ERRCODE = '23514', CONSTRAINT = 'outbound_integration_owner_kind_immutable';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_queue_binding_environment_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_binding_environment_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE environment uuid;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.environment_id IS DISTINCT FROM OLD.environment_id OR NEW.deployment_scope IS DISTINCT FROM OLD.deployment_scope OR
      (OLD.deployment_scope<>'' AND (NEW.id IS DISTINCT FROM OLD.id
        OR NEW.app_id IS DISTINCT FROM OLD.app_id OR NEW.account_id IS DISTINCT FROM OLD.account_id)) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_scope_identity',
        MESSAGE='queue binding environment identity is immutable';
    END IF;
  ELSIF NEW.deployment_scope<>'' THEN
    SELECT e.id INTO environment FROM apps a JOIN project_environments e ON e.project_id=a.project_id
      AND e.account_id=a.account_id AND e.slug=NEW.deployment_scope
      WHERE a.id=NEW.app_id AND a.account_id=NEW.account_id AND a.status<>'deleted'
      FOR SHARE OF a,e;
    IF NOT FOUND OR (NEW.environment_id IS NOT NULL AND NEW.environment_id IS DISTINCT FROM environment) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_environment_membership',
        MESSAGE='scoped queue binding requires an account-owned project environment';
    END IF;
    NEW.environment_id=environment;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_queue_binding_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_binding_retirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.retired_at IS NOT NULL AND EXISTS(SELECT 1 FROM apps WHERE id=OLD.app_id) THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='queue_binding_retirement_identity',MESSAGE='retired queue identity requires explicit recovery';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.retired_at IS NOT NULL AND NEW.retired_at IS NULL
  AND (to_jsonb(NEW)-'retired_at'-'updated_at')=(to_jsonb(OLD)-'retired_at'-'updated_at')
  AND environment_gitops_queue_recovery_authorized(OLD.id) THEN
  RETURN NEW;
 END IF;
 IF OLD.retired_at IS NOT NULL AND
  (NEW.retired_at IS DISTINCT FROM OLD.retired_at OR NEW.id IS DISTINCT FROM OLD.id
   OR NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.app_id IS DISTINCT FROM OLD.app_id
   OR NEW.name IS DISTINCT FROM OLD.name OR NEW.queue_name IS DISTINCT FROM OLD.queue_name
   OR NEW.mode IS DISTINCT FROM OLD.mode OR NEW.workload_class IS DISTINCT FROM OLD.workload_class
   OR NEW.enabled IS DISTINCT FROM OLD.enabled OR NEW.max_concurrency IS DISTINCT FROM OLD.max_concurrency
   OR NEW.retry_policy IS DISTINCT FROM OLD.retry_policy) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='queue_binding_retirement_identity',MESSAGE='retired queue binding requires explicit recovery';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_queue_consumer_binding_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_consumer_binding_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.queue_binding_id IS NOT NULL
    AND (NEW.queue_binding_id IS DISTINCT FROM OLD.queue_binding_id
      OR NEW.app_id IS DISTINCT FROM OLD.app_id
      OR NEW.account_id IS DISTINCT FROM OLD.account_id) THEN
    RAISE EXCEPTION 'queue consumer binding identity is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'queue_consumer_binding_identity';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_queue_consumer_environment_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_queue_consumer_environment_scope() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE scope text; environment uuid;
BEGIN
  IF TG_OP='UPDATE' AND (NEW.queue_binding_scope IS DISTINCT FROM OLD.queue_binding_scope
    OR NEW.queue_binding_environment_id IS DISTINCT FROM OLD.queue_binding_environment_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_scope_identity',
      MESSAGE='queue consumer environment identity is immutable';
  END IF;
  IF NEW.queue_binding_id IS NULL THEN
    IF NEW.queue_binding_scope<>'' OR NEW.queue_binding_environment_id IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_scope_identity',
        MESSAGE='scoped consumer requires an immutable binding';
    END IF;
  ELSE
    SELECT b.deployment_scope,b.environment_id INTO scope,environment FROM queue_bindings b
      WHERE b.id=NEW.queue_binding_id AND b.app_id=NEW.app_id AND b.account_id=NEW.account_id FOR SHARE;
    IF NOT FOUND THEN RETURN NEW; END IF; -- The existing deferred tenant FK owns this rejection.
    IF (TG_OP='UPDATE' AND (NEW.queue_binding_scope IS DISTINCT FROM scope OR NEW.queue_binding_environment_id IS DISTINCT FROM environment))
      OR (TG_OP='INSERT' AND ((NEW.queue_binding_scope<>'' AND NEW.queue_binding_scope IS DISTINCT FROM scope)
        OR (NEW.queue_binding_environment_id IS NOT NULL AND NEW.queue_binding_environment_id IS DISTINCT FROM environment))) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_scope_identity',
        MESSAGE='queue consumer must retain its parent environment';
    END IF;
    NEW.queue_binding_scope=scope;
    NEW.queue_binding_environment_id=environment;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_retired_queue_invocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_retired_queue_invocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE binding_retired_at timestamptz; binding_scope text; binding_environment uuid;
BEGIN
  IF NEW.environment_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.source='queue' AND (TG_OP='INSERT' OR
    (NEW.state='dispatching' AND OLD.state IS DISTINCT FROM 'dispatching')) THEN
    SELECT b.retired_at,b.deployment_scope,b.environment_id INTO binding_retired_at,binding_scope,binding_environment FROM queue_bindings b
      WHERE b.app_id=NEW.app_id AND b.account_id=NEW.account_id AND
        (b.id=NEW.queue_binding_id OR (NEW.queue_binding_id IS NULL
          AND b.deployment_scope='' AND b.queue_name=NEW.queue_name)) FOR SHARE;
    IF binding_scope<>'' AND NOT EXISTS (SELECT 1 FROM apps a JOIN project_environments e
      ON e.project_id=a.project_id AND e.account_id=a.account_id WHERE a.id=NEW.app_id
        AND e.id=binding_environment AND e.slug=binding_scope) THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_environment_unavailable',
        MESSAGE='captured queue binding environment is unavailable';
    END IF;
    IF binding_retired_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_retired', MESSAGE='queue binding is retired';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_release_qualification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_release_qualification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP = 'INSERT' THEN
  IF NOT EXISTS (SELECT 1 FROM runtime_releases WHERE id=NEW.release_id AND architecture=NEW.architecture) THEN
   RAISE EXCEPTION 'runtime qualification architecture differs from release' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP = 'DELETE' THEN
  RAISE EXCEPTION 'runtime qualification evidence is retained' USING ERRCODE = '23514';
 END IF;
 IF ROW(NEW.release_id,NEW.profile,NEW.architecture,NEW.host_id,NEW.kernel_boot_id,NEW.source_commit,
  NEW.kernel_sha256,NEW.firecracker_sha256,NEW.report_sha256,NEW.test_metal_sha256,NEW.leakcheck_sha256,
  NEW.started_at,NEW.completed_at,NEW.recorded_at) IS DISTINCT FROM
  ROW(OLD.release_id,OLD.profile,OLD.architecture,OLD.host_id,OLD.kernel_boot_id,OLD.source_commit,
  OLD.kernel_sha256,OLD.firecracker_sha256,OLD.report_sha256,OLD.test_metal_sha256,OLD.leakcheck_sha256,
  OLD.started_at,OLD.completed_at,OLD.recorded_at) OR
  (OLD.revoked_at IS NOT NULL AND ROW(NEW.revoked_at,NEW.revocation_sha256) IS DISTINCT FROM ROW(OLD.revoked_at,OLD.revocation_sha256)) THEN
  RAISE EXCEPTION 'runtime qualification evidence and revocation are immutable' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_upgrade_external_fence_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_external_fence_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' OR (TG_OP='INSERT' AND (NEW.revoked_at IS NOT NULL OR NEW.created_at>clock_timestamp())) THEN
  RAISE EXCEPTION 'external authority history cannot be erased or pre-revoked' USING ERRCODE='23514';
 END IF;
 IF TG_OP='UPDATE' AND (OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.revoked_at>clock_timestamp()
  OR (to_jsonb(NEW)-'revoked_at') IS DISTINCT FROM (to_jsonb(OLD)-'revoked_at')) THEN
  RAISE EXCEPTION 'authority key is immutable and revocation is irreversible' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_external_fence_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_external_fence_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE withdrawn runtime_upgrade_public_edge_withdrawals;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'external fence intent is immutable' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=NEW.gateway_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external fence internal head changed' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton AND revision=NEW.public_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external fence public head changed' USING ERRCODE='23514'; END IF;
 SELECT * INTO withdrawn FROM runtime_upgrade_public_edge_withdrawals WHERE id=NEW.withdrawal_id FOR UPDATE;
 IF NOT FOUND OR NEW.created_at<withdrawn.created_at OR NEW.created_at>clock_timestamp()
  OR EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_withdrawal_receipts WHERE withdrawal_id=NEW.withdrawal_id)
  OR EXISTS(SELECT 1 FROM runtime_upgrade_external_fence_receipts WHERE withdrawal_id=NEW.withdrawal_id) THEN
  RAISE EXCEPTION 'external fence requires unresolved exact withdrawal' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_external_fence_authorities WHERE id=NEW.authority_id AND revoked_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external fence authority unavailable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_external_fence_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_external_fence_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE reviewed runtime_upgrade_external_fence_intents;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'external fence receipt is immutable' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 SELECT * INTO reviewed FROM runtime_upgrade_external_fence_intents WHERE id=NEW.intent_id FOR SHARE;
 IF NOT FOUND OR reviewed.withdrawal_id<>NEW.withdrawal_id THEN
  RAISE EXCEPTION 'external receipt intent mismatch' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_public_edge_withdrawals WHERE id=NEW.withdrawal_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_withdrawal_receipts WHERE withdrawal_id=NEW.withdrawal_id)
  OR NOT EXISTS(SELECT 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=reviewed.gateway_revision)
  OR NOT EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton AND revision=reviewed.public_revision) THEN
  RAISE EXCEPTION 'external receipt resolved elsewhere or head changed' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_external_fence_authorities WHERE id=reviewed.authority_id AND revoked_at IS NULL FOR SHARE;
 IF NOT FOUND OR NEW.enforced_at<reviewed.created_at OR NEW.observed_at>clock_timestamp()
  OR clock_timestamp()-NEW.issued_at>interval '60 seconds'
  OR encode(sha256(NEW.envelope),'hex')<>NEW.envelope_sha256 THEN
  RAISE EXCEPTION 'external receipt authority, clock or bytes invalid' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_gateway_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_gateway_roster() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE canonical uuid[]; unique_sessions integer;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'immutable runtime upgrade gateway roster' USING ERRCODE='23514';
 END IF;
 SELECT array_agg(DISTINCT s ORDER BY s) INTO canonical FROM unnest(NEW.slot_ids) s;
 SELECT count(DISTINCT s) INTO unique_sessions FROM unnest(NEW.gateway_sessions) s;
 IF NEW.slot_ids IS DISTINCT FROM canonical OR unique_sessions<>cardinality(NEW.gateway_sessions)
  OR array_position(NEW.slot_ids,NULL::uuid) IS NOT NULL OR array_position(NEW.gateway_sessions,NULL::uuid) IS NOT NULL
  OR array_position(NEW.slot_ids,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL
  OR array_position(NEW.gateway_sessions,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL THEN
  RAISE EXCEPTION 'invalid runtime upgrade gateway roster' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_native_public_startup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_native_public_startup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE roster runtime_upgrade_public_edge_rosters; body jsonb; selected jsonb; epoch jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'native startup provenance is immutable' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=NEW.gateway_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'native startup internal head changed' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton AND revision=NEW.public_revision FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'native startup public head changed' USING ERRCODE='23514'; END IF;
 SELECT * INTO roster FROM runtime_upgrade_public_edge_rosters WHERE revision=NEW.public_revision;
 IF roster.gateway_roster_revision IS DISTINCT FROM NEW.gateway_revision
  OR roster.public_sessions[array_position(roster.slot_ids,NEW.slot_id)] IS DISTINCT FROM NEW.public_session_id
  OR roster.config_sha256s[array_position(roster.slot_ids,NEW.slot_id)] IS DISTINCT FROM NEW.config_sha256
  OR NEW.observed_at<roster.created_at OR NEW.recorded_at>clock_timestamp()
  OR EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_withdrawals WHERE public_session_id=NEW.public_session_id)
  OR NOT EXISTS(SELECT 1 FROM runtime_upgrade_public_edge_guards WHERE slot_id=NEW.slot_id AND public_session_id=NEW.public_session_id
    AND public_roster_revision=NEW.public_revision AND config_sha256=NEW.config_sha256 AND guard_enabled
    AND observed_at<=clock_timestamp() AND expires_at>clock_timestamp()) THEN
  RAISE EXCEPTION 'native startup requires exact current guarded member before withdrawal' USING ERRCODE='23514';
 END IF;
 IF encode(sha256(NEW.review),'hex')<>NEW.review_sha256 OR encode(sha256(NEW.envelope),'hex')<>NEW.envelope_sha256 THEN
  RAISE EXCEPTION 'native startup evidence digest mismatch' USING ERRCODE='23514';
 END IF;
 selected:=convert_from(NEW.review,'UTF8')::jsonb;
 body:=convert_from(NEW.envelope,'UTF8')::jsonb;
 epoch:=body#>'{proof,startup,epoch}';
 IF body->'review' IS DISTINCT FROM selected OR jsonb_array_length(body->'native') IS DISTINCT FROM 2
  OR body#>>'{proof,startup,slot_id}' IS DISTINCT FROM NEW.slot_id::text
  OR body#>>'{proof,startup,session_id}' IS DISTINCT FROM NEW.public_session_id::text
  OR body#>>'{proof,startup,config_sha256}' IS DISTINCT FROM NEW.config_sha256
  OR epoch->>'machine_id' IS DISTINCT FROM NEW.machine_id OR epoch->>'boot_id' IS DISTINCT FROM NEW.boot_id::text
  OR epoch->>'pid' IS DISTINCT FROM NEW.pid::text OR epoch->>'start_ticks' IS DISTINCT FROM NEW.start_ticks
  OR epoch->>'pid_namespace' IS DISTINCT FROM NEW.pid_namespace OR epoch->>'net_namespace' IS DISTINCT FROM NEW.net_namespace THEN
  RAISE EXCEPTION 'native startup evidence identity mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.account_id,NEW.app_id,NEW.deployment_id,NEW.serving_deployment_id,NEW.target_release_id,
      NEW.source_sha256,NEW.qualification_report_sha256,NEW.created_at,NEW.deadline_at,NEW.source_path)
   IS DISTINCT FROM
     (OLD.id,OLD.account_id,OLD.app_id,OLD.deployment_id,OLD.serving_deployment_id,OLD.target_release_id,
      OLD.source_sha256,OLD.qualification_report_sha256,OLD.created_at,OLD.deadline_at,OLD.source_path)
   OR OLD.phase IN ('complete','blocked','cancelled')
   OR (OLD.phase='waiting' AND NEW.phase IN ('reserved','prepared'))
   OR (OLD.phase='prepared' AND NEW.phase='reserved')
   OR (OLD.phase='reserved' AND NEW.phase IN ('waiting','complete')) THEN
   RAISE EXCEPTION 'immutable runtime upgrade intent or terminal operation' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.phase='complete' AND NOT EXISTS (
  SELECT 1 FROM deployment_runtime_upgrade_cutovers c WHERE c.deployment_id=NEW.deployment_id
   AND c.serving_deployment_id=NEW.serving_deployment_id AND c.target_release_id=NEW.target_release_id
   AND c.qualification_report_sha256=NEW.qualification_report_sha256 AND c.wake_id=NEW.wake_id
 ) THEN
  RAISE EXCEPTION 'runtime upgrade completion requires retained cutover' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_operation_effect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_operation_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE operation_phase text;
BEGIN
 PERFORM 1 FROM apps a JOIN deployments d ON d.app_id=a.id WHERE d.id=NEW.deployment_id FOR UPDATE OF a;
 SELECT phase INTO operation_phase FROM runtime_upgrade_operations WHERE deployment_id=NEW.deployment_id;
 IF (TG_TABLE_NAME='builds' AND operation_phase IN ('reserved','blocked','cancelled','complete'))
  OR (TG_TABLE_NAME='deployment_runtime_upgrade_cutovers' AND operation_phase IS NOT NULL AND operation_phase<>'waiting') THEN
  RAISE EXCEPTION 'runtime upgrade operation cannot publish this effect' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_activity_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_activity_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.public_session_id=NEW.public_session_id AND OLD.public_roster_revision=NEW.public_roster_revision AND (
  NEW.activity_version < OLD.activity_version
  OR (NOT OLD.coverage_known AND NEW.coverage_known)
  OR (NEW.activity_version=OLD.activity_version AND
   (NEW.coverage_known,NEW.pending_forwards,NEW.current_forwards,NEW.previous_forwards)
   IS DISTINCT FROM (OLD.coverage_known,OLD.pending_forwards,OLD.current_forwards,OLD.previous_forwards))) THEN
  RAISE EXCEPTION 'public ingress activity cannot rewind or restore unknown coverage' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_fact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_fact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 IF NOT EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r
  JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=r.revision
  JOIN runtime_upgrade_gateway_roster_head g ON g.revision=r.gateway_roster_revision
  WHERE r.revision=NEW.public_roster_revision
   AND r.public_sessions[array_position(r.slot_ids,NEW.slot_id)]=NEW.public_session_id
   AND r.config_sha256s[array_position(r.slot_ids,NEW.slot_id)]=NEW.config_sha256) THEN
  RAISE EXCEPTION 'public guard fact requires exact current reviewed process and config' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_head_withdrawals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_head_withdrawals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE next_roster runtime_upgrade_public_edge_rosters;
BEGIN
 IF TG_OP='DELETE' OR NEW.revision IS NULL THEN
  RAISE EXCEPTION 'public edge head cannot erase withdrawal history' USING ERRCODE='23514';
 END IF;
 SELECT * INTO next_roster FROM runtime_upgrade_public_edge_rosters WHERE revision=NEW.revision;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=next_roster.gateway_roster_revision FOR SHARE;
 IF NOT FOUND OR EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_withdrawals w WHERE w.public_session_id=ANY(next_roster.public_sessions)) THEN
  RAISE EXCEPTION 'public review cannot resurrect a withdrawn process or bind an old internal review' USING ERRCODE='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters prior, generate_subscripts(prior.public_sessions,1) i
  WHERE prior.revision=OLD.revision AND prior.public_sessions[i]=ANY(next_roster.public_sessions)
   AND (prior.slot_ids[i],prior.config_sha256s[i]) IS DISTINCT FROM
    (next_roster.slot_ids[array_position(next_roster.public_sessions,prior.public_sessions[i])],next_roster.config_sha256s[array_position(next_roster.public_sessions,prior.public_sessions[i])])) THEN
  RAISE EXCEPTION 'startup session cannot change public slot or configuration' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_roster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_roster() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE canonical uuid[];
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'immutable public edge roster' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton AND revision=NEW.gateway_roster_revision FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'public edge roster requires current internal roster' USING ERRCODE='23514';
 END IF;
 SELECT array_agg(DISTINCT s ORDER BY s) INTO canonical FROM unnest(NEW.slot_ids) s;
 IF NEW.slot_ids IS DISTINCT FROM canonical
  OR (SELECT count(DISTINCT s) FROM unnest(NEW.public_sessions) s) <> cardinality(NEW.public_sessions)
  OR array_position(NEW.slot_ids,NULL::uuid) IS NOT NULL OR array_position(NEW.public_sessions,NULL::uuid) IS NOT NULL
  OR array_position(NEW.slot_ids,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL
  OR array_position(NEW.public_sessions,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL
  OR EXISTS (SELECT 1 FROM unnest(NEW.config_sha256s) s WHERE s IS NULL OR s !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'invalid public edge roster' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_runtime_upgrade_public_edge_withdrawal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_withdrawal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP <> 'INSERT' THEN
  RAISE EXCEPTION 'immutable public edge withdrawal' USING ERRCODE='23514';
 END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 IF EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=r.revision WHERE NEW.public_session_id=ANY(r.public_sessions))
  OR NOT EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r WHERE r.revision=NEW.roster_revision
   AND r.public_sessions[array_position(r.slot_ids,NEW.slot_id)]=NEW.public_session_id
   AND r.config_sha256s[array_position(r.slot_ids,NEW.slot_id)]=NEW.config_sha256) THEN
  RAISE EXCEPTION 'withdrawal requires exact previously reviewed absent process' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_public_edge_withdrawal_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_public_edge_withdrawal_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE withdrawn runtime_upgrade_public_edge_withdrawals;
BEGIN
 IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'immutable public edge withdrawal receipt' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
 PERFORM 1 FROM runtime_upgrade_public_edge_roster_head WHERE singleton FOR SHARE;
 SELECT * INTO withdrawn FROM runtime_upgrade_public_edge_withdrawals WHERE id=NEW.withdrawal_id FOR UPDATE;
 IF NOT FOUND OR NEW.observed_at < withdrawn.created_at OR NEW.observed_at > clock_timestamp()
  OR EXISTS(SELECT 1 FROM runtime_upgrade_external_fence_receipts WHERE withdrawal_id=NEW.withdrawal_id)
  OR EXISTS (SELECT 1 FROM runtime_upgrade_public_edge_rosters r JOIN runtime_upgrade_public_edge_roster_head h ON h.revision=r.revision WHERE withdrawn.public_session_id=ANY(r.public_sessions)) THEN
  RAISE EXCEPTION 'withdrawal receipt requires an absent unresolved process and current clock' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_runtime_upgrade_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM deployment_runtime_upgrade_targets WHERE deployment_id = OLD.id) AND
  ROW(NEW.app_id, NEW.source_sha256, NEW.source_root, NEW.source_bytes, NEW.kind, NEW.handler)
  IS DISTINCT FROM ROW(OLD.app_id, OLD.source_sha256, OLD.source_root, OLD.source_bytes, OLD.kind, OLD.handler) THEN
  RAISE EXCEPTION 'runtime upgrade source is immutable' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_upgrade_target(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP = 'DELETE' THEN
  IF EXISTS(SELECT 1 FROM deployments WHERE id = OLD.deployment_id) THEN
   RAISE EXCEPTION 'runtime upgrade target is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
 END IF;
 IF NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'runtime upgrade target is immutable' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: guard_runtime_upgrade_verification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_runtime_upgrade_verification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE canonical uuid[];
BEGIN
 SELECT array_agg(DISTINCT s ORDER BY s) INTO canonical FROM unnest(NEW.gateway_sessions) s;
 IF NEW.gateway_sessions IS DISTINCT FROM canonical OR array_position(NEW.gateway_sessions,NULL::uuid) IS NOT NULL
  OR array_position(NEW.gateway_sessions,'00000000-0000-0000-0000-000000000000'::uuid) IS NOT NULL THEN
  RAISE EXCEPTION 'invalid runtime upgrade verification participants' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  PERFORM 1 FROM runtime_upgrade_gateway_roster_head WHERE singleton FOR SHARE;
  IF NEW.gateway_roster_revision IS NULL OR NOT EXISTS (
   SELECT 1 FROM runtime_upgrade_gateway_rosters r JOIN runtime_upgrade_gateway_roster_head h ON h.revision=r.revision
   WHERE r.revision=NEW.gateway_roster_revision AND NEW.gateway_sessions=(SELECT array_agg(s ORDER BY s) FROM unnest(r.gateway_sessions) s)) THEN
   RAISE EXCEPTION 'runtime upgrade verification requires full current gateway roster' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM runtime_upgrade_operations o JOIN deployment_runtime_upgrade_cutovers c ON c.deployment_id=o.deployment_id
   WHERE o.id=NEW.operation_id AND o.phase='complete' AND c.cutover_at=NEW.cutover_at AND c.serving_deployment_id=o.serving_deployment_id
   AND c.target_release_id=o.target_release_id AND c.wake_id=o.wake_id AND c.qualification_report_sha256=o.qualification_report_sha256) THEN
   RAISE EXCEPTION 'runtime upgrade verification requires matching activation' USING ERRCODE='23514';
  END IF;
 ELSIF (NEW.operation_id,NEW.gateway_sessions,NEW.gateway_roster_revision,NEW.cutover_at,NEW.created_at,NEW.deadline_at)
   IS DISTINCT FROM (OLD.operation_id,OLD.gateway_sessions,OLD.gateway_roster_revision,OLD.cutover_at,OLD.created_at,OLD.deadline_at)
   OR (OLD.phase<>'pending' AND NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'immutable runtime upgrade verification' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_scoped_queue_binding_work(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_scoped_queue_binding_work() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE scope text; environment uuid;
BEGIN
  IF NEW.source='queue' AND NEW.queue_binding_id IS NOT NULL AND (TG_OP='INSERT'
    OR (NEW.state='dispatching' AND OLD.state IS DISTINCT FROM 'dispatching')) THEN
    SELECT b.deployment_scope,b.environment_id INTO scope,environment FROM queue_bindings b
      WHERE b.id=NEW.queue_binding_id AND b.app_id=NEW.app_id AND b.account_id=NEW.account_id FOR SHARE;
    IF scope<>'' THEN
      IF scope IS DISTINCT FROM NEW.deployment_scope THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='invocation_queue_binding_tenant',
          MESSAGE='queue binding must retain the admitted environment';
      END IF;
      PERFORM 1 FROM apps a JOIN project_environments e ON e.project_id=a.project_id AND e.account_id=a.account_id
        WHERE a.id=NEW.app_id AND e.id=environment AND e.slug=scope FOR SHARE OF a,e;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_binding_environment_unavailable',
          MESSAGE='captured queue binding environment is unavailable';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_scoped_queue_consumer_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_scoped_queue_consumer_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM triggers t WHERE t.id=NEW.trigger_id AND t.queue_binding_scope<>'')
    AND NOT EXISTS (SELECT 1 FROM triggers t JOIN invocations i ON i.id::text=NEW.item_identifier
      AND i.app_id=t.app_id AND i.account_id=t.account_id AND i.source='queue'
      AND i.queue_binding_id=t.queue_binding_id AND i.deployment_scope=t.queue_binding_scope
      WHERE t.id=NEW.trigger_id) THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='queue_consumer_receipt_scope',
      MESSAGE='scoped consumer receipt requires work captured for its binding';
  END IF;
  IF NEW.state='claimed' AND (TG_OP='INSERT' OR OLD.state IS DISTINCT FROM 'claimed'
    OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation) AND EXISTS (
      SELECT 1 FROM triggers t WHERE t.id=NEW.trigger_id AND t.queue_binding_scope<>'') THEN
    PERFORM 1 FROM triggers t JOIN apps a ON a.id=t.app_id JOIN project_environments e
        ON e.project_id=a.project_id AND e.account_id=a.account_id AND e.id=t.queue_binding_environment_id
        AND e.slug=t.queue_binding_scope WHERE t.id=NEW.trigger_id FOR SHARE OF a,e;
    IF NOT FOUND THEN RETURN NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_sidecar_layer_artifact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_sidecar_layer_artifact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM require_retained_layer_artifact(NEW.storage_key);
    RETURN NEW;
END;
$$;


--
-- Name: guard_snapshot_layer_artifacts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_snapshot_layer_artifacts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT NEW.stale THEN
        PERFORM require_deployment_layer_artifacts(NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_worker_admission_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_worker_admission_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (OLD.mode = 'worker' OR NEW.mode = 'worker') AND OLD.mode IS DISTINCT FROM NEW.mode THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'instances_worker_admission_identity',
      MESSAGE = 'worker mode is immutable; create a reserved instance';
  END IF;
  IF NEW.mode = 'worker'
     AND OLD.state NOT IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm')
     AND NEW.state IN ('waking','cold_booting','running','draining','snapshotting','migrating','warm') THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'instances_worker_admission_identity',
      MESSAGE = 'worker residency requires a newly reserved instance';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_workflow_code_pin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_code_pin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF NEW.deployment_id IS DISTINCT FROM OLD.deployment_id OR NEW.app_id IS DISTINCT FROM OLD.app_id THEN
            RAISE EXCEPTION 'workflow deployment is immutable' USING ERRCODE='23514', CONSTRAINT='workflow_code_immutable';
        END IF;
    ELSE
        PERFORM pin_workflow_code(NEW.app_id,NEW.deployment_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_workflow_event_code_pins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_event_code_pins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE recipient jsonb;
BEGIN
    DELETE FROM workflow_event_code_refs WHERE outbox_id=NEW.id;
    FOR recipient IN SELECT r FROM jsonb_array_elements(NEW.recipient_snapshot) r
        WHERE r ? 'workflow' AND coalesce(r->>'deployment_id','')<>'' ORDER BY r->>'app_id',r->>'deployment_id'
    LOOP
        IF NOT EXISTS(SELECT 1 FROM apps a WHERE a.id::text=recipient->>'app_id'
            AND a.account_id=NEW.account_id AND a.account_id::text=recipient->>'account_id') THEN
            RAISE EXCEPTION 'workflow event owner is unavailable' USING ERRCODE='23514', CONSTRAINT='workflow_code_available';
        END IF;
        PERFORM pin_workflow_code((recipient->>'app_id')::uuid,(recipient->>'deployment_id')::uuid);
        INSERT INTO workflow_event_code_refs(outbox_id,deployment_id,app_id)
        VALUES(NEW.id,(recipient->>'deployment_id')::uuid,(recipient->>'app_id')::uuid) ON CONFLICT DO NOTHING;
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: guard_workflow_webhook_routing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_workflow_webhook_routing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE endpoint uuid;
BEGIN
    IF TG_TABLE_NAME = 'exclusive_work_trigger_bindings' THEN
        IF NEW.source <> 'inbound_webhook' THEN RETURN NEW; END IF;
        endpoint := NEW.trigger_id;
    ELSE
        endpoint := NEW.endpoint_id;
    END IF;
    PERFORM 1 FROM inbound_webhook_endpoints WHERE id = endpoint FOR UPDATE;
    IF TG_TABLE_NAME = 'workflow_webhook_bindings' THEN
        IF EXISTS (SELECT 1 FROM workflow_callback_webhook_bindings WHERE endpoint_id = endpoint)
           OR EXISTS (SELECT 1 FROM exclusive_work_trigger_bindings WHERE source = 'inbound_webhook' AND trigger_id = endpoint) THEN
            RAISE EXCEPTION 'endpoint already has a callback or operation binding' USING ERRCODE = '23505';
        END IF;
    ELSIF EXISTS (SELECT 1 FROM workflow_webhook_bindings WHERE endpoint_id = endpoint) THEN
        RAISE EXCEPTION 'endpoint already starts an automation' USING ERRCODE = '23505';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: initialize_clone_configuration_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initialize_clone_configuration_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO project_environment_clone_configuration_guards(project_id, account_id)
    VALUES (NEW.id, NEW.account_id)
    ON CONFLICT (project_id) DO UPDATE SET account_id = EXCLUDED.account_id,
        generation = project_environment_clone_configuration_guards.generation + 1
    WHERE project_environment_clone_configuration_guards.state = 'open';
    RETURN NEW;
END;
$$;


--
-- Name: instance_readiness_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.instance_readiness_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.kind IN ('wake.sidecar_health', 'wake.app_readiness')
       AND NEW.data->>'status' IN ('ready', 'unready')
       AND coalesce(NEW.data->>'app_id', '') <> ''
       AND coalesce(NEW.data->>'instance_id', '') <> '' THEN
        PERFORM pg_notify('instance_readiness_changed', json_build_object(
            'app_id', NEW.data->>'app_id',
            'instance_id', NEW.data->>'instance_id',
            'source', CASE
                WHEN NEW.kind = 'wake.app_readiness' THEN 'primary_app'
                ELSE 'sidecar:' || coalesce(NEW.data->>'sidecar_name', '')
            END,
            'status', NEW.data->>'status',
            'at', NEW.at,
            'event_id', NEW.id
        )::text);
    END IF;
    RETURN NEW;
END;
$$;


