--
-- Name: purge_inactive_outbound_credential(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_inactive_outbound_credential() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.credential_source = 'customer_sealed'
       AND (NEW.credential_source <> 'customer_sealed' OR NEW.provider_auth_mode <> 'managed') THEN
        DELETE FROM outbound_integration_credentials WHERE integration_id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: rearm_queue_replay_receipts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rearm_queue_replay_receipts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.state='dead_letter' AND NEW.state='pending' AND NEW.source IN ('queue','delayed_task') THEN
    -- Preserve the original receipt UUID, payload, work lane and failure audit.
    -- A renamed private binding is addressed only by its immutable identity.
    UPDATE trigger_records r SET state='pending', attempts=0, last_error=NULL,
      next_fire_at=clock_timestamp(), claim_generation=r.claim_generation+1, claim_expires_at=NULL
      FROM triggers t WHERE t.id=r.trigger_id AND t.app_id=NEW.app_id AND t.account_id=NEW.account_id
        AND t.kind='queue' AND t.source=NEW.source AND r.item_identifier=NEW.id::text
        AND (NEW.queue_binding_id IS NULL OR t.queue_binding_id=NEW.queue_binding_id)
        AND r.state NOT IN ('superseded','cancelled','expired');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: reconcile_queue_work_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_queue_work_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE trigger_records tr
       SET state = NEW.state,
           claim_expires_at = NULL,
           last_error = 'queue work ' || NEW.state
      FROM triggers t
     WHERE t.id = tr.trigger_id
       AND t.app_id = NEW.app_id
       AND t.kind = 'queue'
       AND tr.item_identifier = NEW.id::text
       AND tr.state IN ('pending', 'retry', 'claimed');
    RETURN NEW;
END;
$$;


--
-- Name: record_commit_managed_operation_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_commit_managed_operation_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 UPDATE commit_receipts SET operation_state=CASE NEW.state
 WHEN 'pending' THEN 'accepted' WHEN 'running' THEN 'running'
 WHEN 'completed' THEN 'completed' WHEN 'cancelled' THEN 'cancelled'
 WHEN 'failed' THEN 'failed' WHEN 'expired' THEN 'failed'
 ELSE 'unknown' END, completed_at=NEW.completed_at
 WHERE operation_id=NEW.id;
 RETURN NEW;
END;
$$;


--
-- Name: record_commit_operation_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_commit_operation_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 UPDATE commit_receipts SET operation_state=CASE NEW.state
 WHEN 'pending' THEN 'accepted' WHEN 'dispatching' THEN 'running'
 WHEN 'completed' THEN 'completed' WHEN 'cancelled' THEN 'cancelled'
 WHEN 'failed' THEN 'failed' WHEN 'dead_letter' THEN 'failed'
 ELSE 'unknown' END, completed_at=NEW.completed_at
 WHERE invocation_id=NEW.id;
 RETURN NEW;
END;
$$;


--
-- Name: record_invocation_attempt_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_invocation_attempt_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  recorded_at timestamptz := clock_timestamp();
  attempt_outcome text;
BEGIN
  IF NEW.source NOT IN ('async_invoke','replay') THEN RETURN NEW; END IF;
  -- Both writes share the execution transaction. No backfill or pre-claim attempts.
  IF OLD.state='dispatching' AND (NEW.state<>'dispatching'
      OR NEW.attempts<>OLD.attempts OR NEW.replay_generation<>OLD.replay_generation) THEN
    attempt_outcome := CASE
      WHEN NEW.replay_generation<>OLD.replay_generation THEN 'unknown'
      WHEN NEW.state='completed' THEN 'succeeded'
      WHEN NEW.outcome='uncertain' THEN 'unknown'
      WHEN NEW.state='pending' AND NEW.last_error='dispatch lease expired; requeued' THEN 'unknown'
      WHEN NEW.state='pending' THEN 'retry'
      WHEN NEW.state='failed' THEN 'failed'
      WHEN NEW.state='dead_letter' THEN 'dead_letter'
      WHEN NEW.state='cancelled' THEN 'cancelled'
      ELSE 'unknown' END;
    UPDATE invocation_attempt_history SET
      finished_at=greatest(recorded_at,started_at), outcome=attempt_outcome,
      error_detail=left(coalesce(NEW.last_error,''),1024),
      next_attempt_at=CASE WHEN NEW.state='pending' THEN NEW.due_at END,
      retain_until=least(coalesce(NEW.result_retention_until,recorded_at+interval '30 days'),recorded_at+interval '30 days')
    WHERE invocation_id=OLD.id AND replay_generation=OLD.replay_generation
      AND attempt=OLD.attempts AND outcome='running';
  END IF;
  IF NEW.state='dispatching' AND NEW.attempts>0 AND (OLD.state<>'dispatching'
      OR NEW.attempts<>OLD.attempts OR NEW.replay_generation<>OLD.replay_generation) THEN
    INSERT INTO invocation_attempt_history(invocation_id,account_id,app_id,
      root_invocation_id,root_created_at,replay_generation,attempt,started_at,outcome,retain_until)
    VALUES(NEW.id,NEW.account_id,NEW.app_id,coalesce(NEW.replay_root_invocation_id,NEW.id),
      coalesce(NEW.replay_root_created_at,NEW.created_at),NEW.replay_generation,NEW.attempts,
      recorded_at,'running',recorded_at+interval '30 days');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: record_job_task_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_job_task_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.attempt > OLD.attempt THEN
        -- A claimed VM may fail before a terminal task row is written. Its
        -- retry transition still consumes an attempt and needs a result.
        INSERT INTO job_task_attempts (
            run_id, task_index, attempt, status, instance_id, error_class,
            error_message, exit_code, started_at, finished_at, log_content,
            log_truncated, output_manifest, work_decision, outcome_code)
        VALUES (
            OLD.run_id, OLD.task_index, OLD.attempt,
            CASE WHEN OLD.status = 'claimed' THEN
                CASE WHEN NEW.error_class = 'infra' THEN 'failed' ELSE 'timeout' END
                ELSE OLD.status END,
            OLD.instance_id,
            CASE WHEN OLD.status = 'claimed' THEN COALESCE(NEW.error_class, 'infra') ELSE OLD.error_class END,
            CASE WHEN OLD.status = 'claimed' THEN
                COALESCE(NEW.error_message, 'reaper reclaimed stale lease')
                ELSE OLD.error_message END,
            CASE WHEN OLD.status = 'claimed' THEN
                CASE WHEN NEW.error_class = 'infra' THEN 1 ELSE 124 END
                ELSE OLD.exit_code END,
            OLD.started_at, COALESCE(OLD.finished_at, clock_timestamp()),
            OLD.log_content, OLD.log_truncated, OLD.output_manifest,
            COALESCE(NEW.work_decision, OLD.work_decision), COALESCE(NEW.outcome_code, OLD.outcome_code))
        ON CONFLICT (run_id, task_index, attempt) DO NOTHING;
    ELSIF NEW.status IN ('succeeded', 'failed', 'timeout', 'cancelled', 'oom')
       AND OLD.status NOT IN ('succeeded', 'failed', 'timeout', 'cancelled', 'oom') THEN
        INSERT INTO job_task_attempts (
            run_id, task_index, attempt, status, instance_id, error_class,
            error_message, exit_code, started_at, finished_at, log_content,
            log_truncated, output_manifest, work_decision, outcome_code)
        VALUES (
            NEW.run_id, NEW.task_index, NEW.attempt, NEW.status, NEW.instance_id,
            NEW.error_class, NEW.error_message, NEW.exit_code, NEW.started_at,
            COALESCE(NEW.finished_at, clock_timestamp()), NEW.log_content,
            NEW.log_truncated, NEW.output_manifest, NEW.work_decision, NEW.outcome_code)
        ON CONFLICT (run_id, task_index, attempt) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: record_object_s3_copy_source_epoch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_object_s3_copy_source_epoch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 -- AFTER runs only for the winning insert/update of an upsert. An idempotent
 -- update of the current identity is valid; every new identity is single use.
 IF TG_OP='INSERT' OR NEW.id IS DISTINCT FROM OLD.id THEN
  INSERT INTO object_s3_copy_source_epochs(id,account_id) VALUES(NEW.id,NEW.account_id) ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN
   RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_copy_source_fenced',MESSAGE='Copy source identity was already published';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: record_project_release_policy_change(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_project_release_policy_change(release_uuid uuid, app_uuid uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(711901248671::bigint);
    INSERT INTO control_plane_change_log (resource_type, resource_id, app_id, operation)
    VALUES ('project_release', release_uuid, app_uuid, 'updated');
    PERFORM pg_notify('app_changed', app_uuid::text);
END;
$$;


--
-- Name: refresh_event_routing_backlog(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_event_routing_backlog(p_outbox_id bigint, p_subscription_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql
    AS $$
WITH candidates AS MATERIALIZED (
    SELECT * FROM event_routing_backlog_source
    WHERE outbox_id=p_outbox_id AND (p_subscription_id IS NULL OR subscription_id=p_subscription_id)
), inserted AS (
    INSERT INTO event_routing_backlog
        (outbox_id,subscription_id,account_id,app_id,accepted_at,routing_mode,routing_state,capacity_scope,
         attempts,capacity_deferrals,next_attempt_at,lease_until,consumer_kind,origin,workflow_name)
    SELECT outbox_id,subscription_id,account_id,app_id,accepted_at,routing_mode,routing_state,capacity_scope,
           attempts,capacity_deferrals,next_attempt_at,lease_until,consumer_kind,origin,workflow_name
    FROM candidates ORDER BY subscription_id
    ON CONFLICT (outbox_id,subscription_id) DO UPDATE SET
        account_id=excluded.account_id,app_id=excluded.app_id,accepted_at=excluded.accepted_at,
        routing_mode=excluded.routing_mode,routing_state=excluded.routing_state,capacity_scope=excluded.capacity_scope,
        attempts=excluded.attempts,capacity_deferrals=excluded.capacity_deferrals,
        next_attempt_at=excluded.next_attempt_at,lease_until=excluded.lease_until,
        consumer_kind=excluded.consumer_kind,origin=excluded.origin,workflow_name=excluded.workflow_name
    WHERE (event_routing_backlog.account_id,event_routing_backlog.app_id,event_routing_backlog.accepted_at,
           event_routing_backlog.routing_mode,event_routing_backlog.routing_state,event_routing_backlog.capacity_scope,
           event_routing_backlog.attempts,event_routing_backlog.capacity_deferrals,event_routing_backlog.next_attempt_at,
           event_routing_backlog.lease_until,event_routing_backlog.consumer_kind,event_routing_backlog.origin,
           event_routing_backlog.workflow_name)
       IS DISTINCT FROM (excluded.account_id,excluded.app_id,excluded.accepted_at,excluded.routing_mode,excluded.routing_state,
                         excluded.capacity_scope,excluded.attempts,excluded.capacity_deferrals,excluded.next_attempt_at,
                         excluded.lease_until,excluded.consumer_kind,excluded.origin,excluded.workflow_name)
)
DELETE FROM event_routing_backlog b WHERE b.outbox_id=p_outbox_id
    AND (p_subscription_id IS NULL OR b.subscription_id=p_subscription_id)
    AND NOT EXISTS (SELECT 1 FROM candidates c WHERE c.subscription_id=b.subscription_id);
$$;


--
-- Name: reject_reserved_app_slug_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_reserved_app_slug_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.slug = ANY (ARRAY[
        'account','admin','api','assets','billing','cdn','console','dashboard',
        'docs','help','login','logout','mail','ns','operations','security',
        'signup','static','status','support','www'
    ]::text[])
       AND (TG_OP = 'INSERT' OR NEW.slug IS DISTINCT FROM OLD.slug) THEN
        RAISE EXCEPTION 'app slug % is reserved for a Gregale service', NEW.slug
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_status_update_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_status_update_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'status incident updates cannot be deleted' USING ERRCODE = '55000';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.incident_id IS DISTINCT FROM OLD.incident_id
       OR NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state
       OR NEW.posted_at IS DISTINCT FROM OLD.posted_at
       OR NEW.actor IS DISTINCT FROM OLD.actor
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.impact IS DISTINCT FROM OLD.impact
       OR NEW.affected_components IS DISTINCT FROM OLD.affected_components
       OR NEW.edited_at IS NULL THEN
        RAISE EXCEPTION 'status incident update correction may change only message and edited_at' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: renew_runtime_upgrade_routing_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renew_runtime_upgrade_routing_token() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 NEW.runtime_upgrade_routing_token:=gen_random_uuid();
 RETURN NEW;
END $$;


--
-- Name: require_deployment_layer_artifacts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_deployment_layer_artifacts(deployment uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE key text;
BEGIN
    FOR key IN SELECT keys.key FROM (
        SELECT rootfs_key AS key FROM deployments WHERE id = deployment
        UNION SELECT storage_key FROM deployment_sidecar_layers WHERE deployment_id = deployment
    ) keys WHERE coalesce(keys.key, '') <> '' ORDER BY keys.key LOOP
        PERFORM require_retained_layer_artifact(key);
    END LOOP;
END;
$$;


--
-- Name: require_fixed_multipart_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_fixed_multipart_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE u object_storage_multipart_uploads;
BEGIN
 SELECT * INTO u FROM object_storage_multipart_uploads WHERE id=NEW.id;
 IF NOT FOUND OR NOT u.fixed_admission OR u.state IN ('completed','aborted') THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM object_storage_write_admissions w WHERE w.id=u.id AND w.multipart_upload_id=u.id AND w.bucket_id=u.bucket_id
  AND w.kind='multipart' AND NOT w.route_receipt AND w.key_hash=encode(sha256(convert_to(u.object_key,'UTF8')),'hex')
  AND w.native_bytes=CASE WHEN w.native_version THEN u.size_bytes ELSE 0 END) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_fixed_multipart_admission_fenced',MESSAGE='Fixed multipart session requires its full-object admission';
 END IF;
 RETURN NULL;
END $$;


--
-- Name: require_object_bucket_default(uuid, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_object_bucket_default(bucket uuid, snapshot jsonb, revision bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE p object_bucket_encryption;
BEGIN
 SELECT * INTO p FROM object_bucket_encryption WHERE bucket_id=bucket FOR SHARE;
 IF (revision>0 AND (NOT FOUND OR p.state<>'ready' OR p.revision<>revision OR p.encryption_snapshot IS DISTINCT FROM snapshot)) OR
  (revision=0 AND snapshot='{}' AND FOUND AND (p.state<>'ready' OR p.encryption_snapshot<>'{}')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',CONSTRAINT='object_bucket_default_fenced',MESSAGE='New writes require the verified captured bucket default';
 END IF;
END $$;


--
-- Name: require_retained_layer_artifact(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_retained_layer_artifact(key text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF key IS NULL OR key = '' THEN RETURN; END IF;
    INSERT INTO layer_artifact_retention(storage_key) VALUES (key) ON CONFLICT DO NOTHING;
    PERFORM 1 FROM layer_artifact_retention WHERE storage_key = key AND state = 'retained' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'layer artifact is retired' USING ERRCODE = '55000', CONSTRAINT = 'layer_artifact_retention_reference_fence';
    END IF;
END;
$$;


--
