    CONSTRAINT managed_realtime_drain_operations_closed_check CHECK ((closed >= 0)),
    CONSTRAINT managed_realtime_drain_operations_connection_ids_array CHECK ((jsonb_typeof(connection_ids) = 'array'::text)),
