--
-- Name: usage_daily; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.usage_daily (
    account_id uuid NOT NULL,
    app_id uuid NOT NULL,
    day date NOT NULL,
    mb_seconds bigint DEFAULT 0 NOT NULL,
